WordHunterWoW_QuestEN = WordHunterWoW_QuestEN or {}
WordHunterWoW_QuestEN[61050] = { title = "How to Wear Seven Medallions", description = "One venthyr cannot wear seven medallions and command the power they bestow, nor command respect from anyone looking at them.\n\nWhat I propose is the crafting of an artifact that can contain the power of the medallions. Focusing that power to one wielder.\n\nUnfortunately, Revendreth lacks the craftsmanship needed to channel such powers. Not without turning the wearer into a puppet of Denathrius.\n\nNo, for this, we must employ the aid of a realm that specializes in service.\n\nDraven has the details.", objectives = "" }
WordHunterWoW_QuestEN[61051] = { title = "The Absent-Minded Artisan", description = "Of all the foolhardy, misguided, exasperating...\n\n<Guardian Kota snorts and stomps a hoof.>\n\nBut standing here does Sha'lor no good. We must find him and bring him back safely.\n\nCome, meet me at the Autumnal Rise. We can survey the burrows below and see if there is any sign that he lives.", objectives = "" }
WordHunterWoW_QuestEN[61056] = { title = "Niya of Ardenweald", description = "To soulbind with another is not an irrevocable bond. However, it is not to be entered into lightly.\n\nYou will experience one another's pasts. Your hopes, fears, dreams, your very memories--if any still linger. You will become kindred spirits in the truest sense.\n\nOnce complete, your connection will transcend physical space and make you stronger in more than mere brawn.", objectives = "" }
WordHunterWoW_QuestEN[61057] = { title = "By Trials Forged", description = "You have shown strength, cunning and compassion since your arrival in Ardenweald. These are the values the greatest hunters possess. \n\nIt has been a privilege to fight by your side, {name}. It would be my honor to continue, as your Soulbind.", objectives = "" }
WordHunterWoW_QuestEN[61058] = { title = "Bound in Dreams", description = "I knew you were something special when Ysera's wildseed reacted to you. Without you, she would have been lost! It would have been a tragedy not just for Ardenweald, but your world as well!\n\nSince then, I have seen you take on many more tasks to help others in need. With your help, Ardenweald grows stronger.\n\nI would be honored to help you continue the good work you have been doing, and to become your soulbind.", objectives = "" }
WordHunterWoW_QuestEN[61061] = { title = "Ulfar's Guidance", description = "There is one who may know how to dispel the curse from Gweyir.\n\nIn the mountains of Drustvar lives Ulfar, an ancient Thornspeaker who sided with the humans of Kul Tiras against his fellow Drust.\n\nJourney to his den and ask for his wisdom. He may hold the answers you seek.\n\nLord Herne and I will tend to Gweyir once she arrives with Ara'lon.", objectives = "" }
WordHunterWoW_QuestEN[61075] = { title = "A Spark of Light", description = "Gorgoa is a protean force fueled by souls that trickle in from many worlds. They wash in from the head of the river, a place they have named the Crucible of the Damned.\n\nThe Jailer's unblinking eyes patrol the river and watch for souls who attempt escape.\n\nBlind the eyes that find them. Close them for good. \n\nTake this and do what must be done.", objectives = "" }
WordHunterWoW_QuestEN[61076] = { title = "Into the Flame", description = "I know the curse of which you speak. Dark magic that possesses the mind of the afflicted.\n\nLong ago, the Drust were ruled by a sorcerer king named Gorak Tul. It was he who twisted our rituals and set us on the path of death and domination.\n\nYou will need to claim a portion of his power to break the curse. \n\nTake this fetish to Gol Inath and temper it in the Flame of Oblivion. But beware... it is a vile place, and danger lurks among its shadows.", objectives = "" }
WordHunterWoW_QuestEN[61077] = { title = "Confronting Sin", description = "Thanks to the raid launched against Castle Nathria, we have obtained an opportunity.\n\nA soul, powerful and fused with dark purpose at the hands of the Master's experiments. \n\nGiven this soul is from Azeroth, the Accuser has asked for your assistance in untwining the corruption done to his sinstone.\n\nThe Accuser awaits you in the lower levels of Sinfall.", objectives = "" }
WordHunterWoW_QuestEN[61079] = { title = "The Jailer's Share", description = "The Mawsworn's torturers have a talent for misery.\n\nThe suffering they inflict often produces more stygia than they can collect. The excess floats loosely in the air, left to drift into the abyss.\n\nI have fashioned a conduit specifically for capturing the leftover stygia. You can borrow it if you wish.\n\nThere are a handful of prime gathering locations throughout Calcis. As you'll be using my conduits, we can split what you find upon your return.", objectives = "" }
WordHunterWoW_QuestEN[61088] = { title = "Dust to Dust", description = "The Mawsworn never cease to invent new forms of suffering.\n\nEven the ground on which we tread is formed from souls pounded into dust. With the flood of souls passing through Gorgoa, the Mawsworn are keen to expand their domain.\n\nAt present, the Mawsworn are burying souls and crafting new terrain from their torment. It is not too late for some of them.\n\nFree the buried souls and stop the endless expansion of suffering.", objectives = "" }
WordHunterWoW_QuestEN[61096] = { title = "The Arbiter's Will", description = "We will all suffer if Bastion and Maldraxxus fall into war.\n\nFor some time, the Necrolords have been isolated. You must travel to their realm and seek the truth of their incursion.\n\nThough our anima reserves remain low, they will be enough to open the way for you.", objectives = "" }
WordHunterWoW_QuestEN[61099] = { title = "The Search for Baine", description = "I dare not step inside that accursed tower myself, of course.\n\nWhile I cannot tell you exactly where your comrade is being held, I offer a gift to assist you.\n\nUse it inside Torghast. It should take you somewhere near your missing ally. Baine Bloodhoof was his name, yes?\n\nEither that, or you'll end up trapped within the tower's ever-shifting halls for all eternity.\n\nBut those are the risks one must take, I suppose. Best of luck!", objectives = "" }
WordHunterWoW_QuestEN[61102] = { title = "Kivarr the Thornspeaker", description = "In my youth, I was mentored by a wise and powerful Thornspeaker named Kivarr. She passed from this world long ago, but her soul may yet rest within the Shadowlands.\n\nKivarr's knowledge is ancient and vast, far eclipsing my own. She may be able to offer you the guidance that I cannot.\n\nSeek her out. Deliver the fetish to her. She will know what to do.\n\nMay the wind be your guide.", objectives = "" }
WordHunterWoW_QuestEN[61103] = { title = "Disrupting the Cycle", description = "The shacklers in the Tremaculum are an awful sort.\n\nSouls are tortured there until they turn malevolent. They are then outfitted as guards so the cycle can continue. \n\nIf you wish to slow the rate at which the Jailer raises his armies, start at the source. \n\nDisrupt the cycle at the Tremaculum.", objectives = "" }
WordHunterWoW_QuestEN[61104] = { title = "Grathalax, the Extractor", description = "There are many powerful lieutenants among the Mawsworn, but there is one who is particularly important to the Jailer.\n\nFar beneath the Tremaculum lives the Jailer's prime interrogator, Grathalax. Power is fed to him via conduits throughout the area.\n\nHis role is to make the process of anima extraction more efficient. His methods are... unkind.\n\nI believe we would both benefit from the end of his existence.", objectives = "" }
WordHunterWoW_QuestEN[61107] = { title = "A Land of Strife", description = "It is imperative that you identify the cause of the attack on Bastion.\n\nWe will require your aid to open the gateway. Once the focus is sufficiently powered, we will call upon the gate to Maldraxxus and direct it into position.\n\nFrom there, the fate of this war must rest upon your shoulders.", objectives = "" }
WordHunterWoW_QuestEN[61112] = { title = "A Hunger for Flesh", description = "<The bile-soaked cloth bears a deathly odor. Upon closer inspection, it appears familiar. The insignia of the Argent Crusade is unmistakable.\n\nCommander Gregor will want to know of this at once.>", objectives = "" }
WordHunterWoW_QuestEN[61113] = { title = "Kivarr's Den", description = "Kivarr... I have not heard that name in many an age.\n\nShe used to make her home near Eventide Grove to the south. Ara'lon knows the area well. I suggest you take him with you.\n\nI fear that the situation with Gweyir weighs heavily upon him. Perhaps joining you on the hunt will do him some good.", objectives = "" }
WordHunterWoW_QuestEN[61114] = { title = "A Hunger for Flesh", description = "<The bile-soaked leather bears a deathly odor. Upon closer inspection, it appears familiar. The insignia of the Argent Crusade is unmistakable.\n\nCommander Throgg will want to know of this at once.>", objectives = "" }
WordHunterWoW_QuestEN[61135] = { title = "Heart of the Crest", description = "With this greatest of gifts from Ardenweald, we have the final piece to rebuild the Crest of Ascension.\n\nLet us make certain Willowblossom's sacrifice is not in vain.", objectives = "" }
WordHunterWoW_QuestEN[61143] = { title = "Return to the Den", description = "There may be a way to break the curse and free your friend's mind, but it will require some work.\n\nUlfar was wise to send you to me. He knew that a portion of Gorak Tul's power would be necessary, but the other reagents we need do not exist on Azeroth.\n\nMy den is not far from here. Meet me there and I will help you prepare a ritual to break the curse.", objectives = "" }
WordHunterWoW_QuestEN[61145] = { title = "Take The Fight To Them", description = "Our scouts report that Margrave Gharmal gathers their forces at the House of Constructs.\n\nOur necropolis and our new kyrian allies have already begun an aerial assault. I need you to lead our forces on the ground.\n\nMeet me within Zerekriss. We will begin our attack immediately.", objectives = "" }
WordHunterWoW_QuestEN[61146] = { title = "Manifesting Power", description = "As you know, shedding our memories of life can result in dangerous creatures known as manifestations. They have increased in number and strength as of late, but I believe we can find use for them yet.\n\nManifestations carry great power within them--power we may purify and use in our own creations at the forge here. In making something positive out of such negativity, we do a noble act of service.\n\nSimply eliminate any you come across, and collect their essence. That is all.", objectives = "" }
WordHunterWoW_QuestEN[61149] = { title = "[DNT] Kivarr's Remedy", description = "When Gorak Tul developed the power of possession, he used it to construct an army of unliving soldiers made of earth and stone. The wicker creatures you encountered in Drustvar were created in much the same way.\n\nBut these masks are different. I have never seen this power used to control the living...\n\nI can help you brew a potion to break the bonds of possession, but I do not know what will happen when the bonds are severed from a living creature...\n\nThere is only one way to find out.", objectives = "" }
WordHunterWoW_QuestEN[61156] = { title = "Where There's a Quill...", description = "In times long past, Aspirants trained against the fauna of Bastion. The creation of the Centurions rendered such unstructured progression obsolete.\n\nThe many flying denizens of this realm are known for their quills. They are light and sturdy, perfect for our purposes.\n\nGather all that you can, please. Any flying creature shall suffice.", objectives = "" }
WordHunterWoW_QuestEN[61157] = { title = "Straight to the Point", description = "The horned beasts of Bastion were once commonly used in aspirant training, but centurion sparring units have mostly taken their place. Over the past few eons, their numbers have grown and now must be culled.\n\nTheir horns are critical components to our work. Many specimens are broken from use in battle--they will not suffice. You must be careful in collecting them.\n\nFace them, defeat them, and bring back their horns.", objectives = "" }
WordHunterWoW_QuestEN[61159] = { title = "Signs of Demise", description = "All members of the Forsworn carry an insignia on their person at all times. We suspect they are imbued with the power of the Temple of Loyalty, bolstering their strength against us.\n\nCollect these insignias from their deceased forms. Strip them of this power, and we shall put it to better use in our own machinations.\n\nSuch is the Archon's will, as it is ours.", objectives = "" }
WordHunterWoW_QuestEN[61166] = { title = "Reduce, Reuse, Recycle", description = "Centurions need lots of parts. But so do we!\n\nKofi needs their metal. Can be from Centurions or the ground. Your choice!\n\nNot too damaged, ok? Hard to clean!", objectives = "" }
WordHunterWoW_QuestEN[61167] = { title = "[DNT] Delivering Hope", description = "Even Gorak Tul, for all his evil, never used the power of possession to dominate the minds and souls of living creatures.\n\nTo see such a terrible power used on the living is truly frightening. The curse must be stopped before it spreads across both the Shadowlands and Azeroth.\n\nTake this potion and deliver it to your friends in the Heart of the Forest. If there is a way to save those who have been cursed, this potion represents our only hope.", objectives = "" }
WordHunterWoW_QuestEN[61171] = { title = "Unbroken Bonds", description = "The Drust will pay for this foul curse that they've unleashed upon us.\n\nWe have lost too many allies... too many friends to give up now. Even though we cannot save those who have fallen into possession, we can end their torment. I will instruct the hunt to put down all possessed they encounter.\n\nPlease deliver this report to the Winter Queen. She must be told what we have learned.\n\nThank you for your service, {name}. You are a true friend and guardian of Ardenweald.", objectives = "" }
WordHunterWoW_QuestEN[61179] = { title = "Forge Ahead", description = "The Eternal Forge has anima again?\n\nAh! Yes! So exciting!\n\nYou must go. Find Forgelite Selene. She will help! So much to make!", objectives = "" }
WordHunterWoW_QuestEN[61180] = { title = "Burn Before Reading", description = "The scroll you recovered details all manner of horrific ways to 'integrate' fallen kyrian into Gharmal's constructs.\n\nIt is also incomplete. There must be more of these among Stitchflesh's remaining followers.\n\nI saw a number of surgeons and their lackeys retreat into the Hall of Chains just ahead as we arrived. I suspect they hold more of these scrolls.\n\nWe must ensure they are never read again.", objectives = "" }
WordHunterWoW_QuestEN[61182] = { title = "Pollen Your Weight", description = "You know Twirlpetal flowers?! They spin around in the light!\n\nWe need pollen. Only pollen if in bloom!\n\nGet a bunch! Flowers in golden fields. And they spin! Round and round!", objectives = "" }
WordHunterWoW_QuestEN[61190] = { title = "Wake of Ashes", description = "It feels as if the Maw itself is sentient... and taking notice of our presence.\n\nWe must leave at once. Bolvar must be informed of what is happening here.\n\nI will bring my father with us. Lead the way out of here, {name}. With haste.", objectives = "" }
WordHunterWoW_QuestEN[61193] = { title = "A Light Touch", description = "Need Firstborne's Light! You know?\n\nNamed after Archon! Always in water. Kofi's favorite!\n\nShine big light when grown. And go to shore! Easy to see!", objectives = "" }
WordHunterWoW_QuestEN[61196] = { title = "The Secret Ingredient", description = "At times, even the most seasoned kyrian may have difficulty meditating. Recently, such problems have become increasingly common.\n\nThere is a special draught crafted from our purest waters that can be used to focus the mind. I believe it may prove useful in our work here as well, perhaps as a catalyst for more potent reactions.\n\nWill you gather some? Move swiftly, for the liquid becomes unstable once removed from our sacred pools.", objectives = "" }
WordHunterWoW_QuestEN[61199] = { title = "Arms Day", description = "Many battles here. Especially lately!\n\nNow weapons all over. Too many. We can use!\n\nGo to big battle places and grab them. We will use better!", objectives = "" }
WordHunterWoW_QuestEN[61209] = { title = "A Somber Melody", description = "Though we kyrian cease to be should we perish in battle here, there is much power within Bastion itself that can call forth echoes of our former brothers and sisters.\n\nThese memories wander the roads. At times, they take on some purpose they served in their eternity here--crafting goods, guarding our sacred grounds, and the like.\n\nTake my lyre. Its ancient melody will dispel the memories, and in the process charge it with the residual energy of our realm.", objectives = "" }
WordHunterWoW_QuestEN[61217] = { title = "Champion: Thela Soulsipper", description = "", objectives = "" }
WordHunterWoW_QuestEN[61218] = { title = "Champion: Dug Gravewell", description = "", objectives = "" }
WordHunterWoW_QuestEN[61219] = { title = "Champion: Nerith Darkwing", description = "", objectives = "" }
WordHunterWoW_QuestEN[61221] = { title = "Champion: Stonehuck", description = "", objectives = "" }
WordHunterWoW_QuestEN[61222] = { title = "Champion: Kaletar the Mender", description = "", objectives = "" }
WordHunterWoW_QuestEN[61223] = { title = "Champion: Ayeleth the Deprived", description = "", objectives = "" }
WordHunterWoW_QuestEN[61226] = { title = "Extra Limbs", description = "We cannot carry out the baroness's plans alone. What she proposes will require a well-coordinated unit.\n\nThree individuals maintained Nurakkir alongside me. When the necropolis fell, two of my soulbinds fell with it.\n\nThere remains a single soul paired with mine. My sister, Xennir, survived the wreckage--though grief besets her.\n\nMeet with Xennir. Guide her through her trauma, and return when she is ready to rejoin the fight.", objectives = "" }
WordHunterWoW_QuestEN[61227] = { title = "The Other Foot", description = "It is a fool's errand to command a necropolis without someone to repair it and keep it airborne. Nurrakir's mechanic was slain in the crash.\n\nBut opportunity arises in dire times. Vyn has told me of an... altercation among the constructs. One of their own resisted the reckless scavenging of Nurakkir, and was promptly detained for his objections.\n\nFind this individual. An enemy deserter could make for a potential ally.", objectives = "" }
WordHunterWoW_QuestEN[61230] = { title = "Outside Influence", description = "It takes a particular kind of magic to pilot a necropolis. The Eyes' helmsman perished with Nurakkir.\n\nBut Baroness Vashj has informed me of a means to acquire a new helmsman.\n\nFollow me to our house's communications beacon. My baroness has taught me a way to summon just the individual we require.\n\nI suspect she will not be pleased at the prospect of serving us. I trust you will encourage her compliance.", objectives = "" }
WordHunterWoW_QuestEN[61246] = { title = "Power of the Chosen", description = "The necropolis is nearly in position. Now is the time to strike!\n\nWe must force Gharmal into the open together. Join me on my roc, and we will unleash your runeblade's power on the juggernauts.\n\nThe Margrave will be unable to ignore their deaths. Once they leave their blighted tower, we can finish them once and for all.", objectives = "" }
WordHunterWoW_QuestEN[61252] = { title = "Call In a Favor", description = "We will do just as my baroness commands. Let us conjure a helmsman before us... however displeased it might make her.\n\nActivate the beacon and prepare yourself for a fight. The liches regard all Eyes as their enemies, and I am certain your reputation among them does you no favors.", objectives = "" }
WordHunterWoW_QuestEN[61265] = { title = "Blueprint: Charm of Alacrity", description = "<You have discovered plans for a charm that seems to hasten your soulbinds in the Path of Ascension.\n\nDactylis should be able to help you with crafting this charm.>", objectives = "" }
WordHunterWoW_QuestEN[61269] = { title = "Blueprint: Charm of Persistence", description = "<You have discovered plans for a charm that encourages your soulbinds to persevere in the Path of Ascension.\n\nDactylis should be able to help you with crafting this charm.>", objectives = "" }
WordHunterWoW_QuestEN[61272] = { title = "Blueprint: Charm of Discord", description = "<You have discovered plans for a charm that seems to damage your soulbinds' enemies in the Path of Ascension.\n\nDactylis should be able to help you with crafting this charm.>", objectives = "" }
WordHunterWoW_QuestEN[61304] = { title = "Blueprint: Kyrian Smith's Kit", description = "<You have discovered plans for a kit that lets you repair a piece of armor while out adventuring.\n\nDactylis should be able to help you with crafting this kit.>", objectives = "" }
WordHunterWoW_QuestEN[61313] = { title = "Champion: Kythekios", description = "", objectives = "" }
WordHunterWoW_QuestEN[61314] = { title = "REUSE ME - SCS", description = "You'll need a vessel to hold the anima you need to collect, but one that will also allow you to channel said anima.\n\nThere was once such a device ages ago, but as of late they've become much more rare.\n\nIn my travels through the Maw, I have seen one once. It is in the (AREA NAME), held by (CREATURE).\n\nYou'll need luck on your side in order to retrieve it.", objectives = "" }
WordHunterWoW_QuestEN[61317] = { title = "Champion: Teliah", description = "", objectives = "" }
WordHunterWoW_QuestEN[61318] = { title = "Champion: Telethakas", description = "", objectives = "" }
WordHunterWoW_QuestEN[61319] = { title = "Champion: Hala", description = "", objectives = "" }
WordHunterWoW_QuestEN[61320] = { title = "Champion: Molako", description = "", objectives = "" }
WordHunterWoW_QuestEN[61321] = { title = "Champion: Ispiron", description = "", objectives = "" }
WordHunterWoW_QuestEN[61323] = { title = "See What You've Done", description = "We have gathered what forces we can. I hope it is enough.\n\nWithin the ruins of our necropolis awaits one final challenge. The one leading the salvage effort calls herself Gorgantus.\n\nTo preserve all that remains to us, we must end her. \n\nLead the attack, and the Eyes will join you. We will reclaim our home.", objectives = "" }
WordHunterWoW_QuestEN[61326] = { title = "[[Deprecated]]", description = "[[Deprecated]]", objectives = "" }
WordHunterWoW_QuestEN[61327] = { title = "[[Deprecated]]", description = "[[Deprecated]]", objectives = "" }
WordHunterWoW_QuestEN[61328] = { title = "[[Deprecated]]", description = "[[Deprecated]]", objectives = "" }
WordHunterWoW_QuestEN[61329] = { title = "[[Deprecated]]", description = "[[Deprecated]]", objectives = "" }
WordHunterWoW_QuestEN[61331] = { title = "Return Lost Souls", description = "Souls continue to pour into the Maw. As long as this is still happening, we need to save as many as possible!\n\nThe Jailer twists the cycle of life and rebirth. This cannot be allowed to continue! We must thwart his plans.\n\nReturn to the Maw and rescue those that you can.", objectives = "" }
WordHunterWoW_QuestEN[61332] = { title = "Return Lost Souls", description = "Souls continue to pour into the Maw, circumventing the natural order of the Shadowlands.\n\nThe Jailer denies these souls their rightful eternities. Only you, Maw Walker, can set things right.\n\nReturn to the Maw and save all that you can.", objectives = "" }
WordHunterWoW_QuestEN[61333] = { title = "Return Lost Souls", description = "Maw Walker, I'm sure you've seen firsthand the souls that continue to pour into the Maw. \n\nWe must act now to cut off the Jailer's power, denying him as many souls as possible. That power belongs to the Necrolords.\n\nI shall direct your efforts to save these souls, and help find them a place among the armies of Maldraxxus.\n\nReturn to the Maw and rescue those that you can.", objectives = "" }
WordHunterWoW_QuestEN[61334] = { title = "Return Lost Souls", description = "Souls continue to pour into the Maw. \n\nTheir anima, our very lifeblood of the Shadowlands, is going with those souls to fuel the Jailer. You rescued me from the Maw. I see no reason you cannot pull more souls from that abyss. \n\nBring souls you rescue from the Maw to me and I shall see them put to better use. At least in Revendreth they have a chance of redemption.", objectives = "" }
WordHunterWoW_QuestEN[61335] = { title = "Rage Against the Cage", description = "You're looking for a mechanic, are you? Look no further!\n\nI've been toiling on a new necropolis for ages. When Nurakkir collapsed, we saw a golden opportunity! We came to salvage parts from the wreckage, but these brutes locked me up when I criticized their methods.\n\nBut now you need help, right? I'm your construct!\n\nYou get me out of here, and you've got yourself a new mechanic!", objectives = "" }
WordHunterWoW_QuestEN[61355] = { title = "Rule 2: Keep a Low Profile", description = "Though you may wish to depart with your precious souls in tow, we now have additional matters to settle first.\n\nThe Eye of the Jailer is upon you. And that does not bode well for either of us.\n\nTake this device. You will reinforce my wards to ensure he does not take notice of me as well.\n\nThe last thing I need is a loud, inelegant mortal bringing more attention my way. I can't have the Jailer capturing me, after all.\n\nI'm far too valuable.", objectives = "" }
WordHunterWoW_QuestEN[61356] = { title = "Echthra, Dame of Hatred", description = "We have made contact with a member of the former House of Eyes in Maldraxxus. She is a powerful marksman who would prove a most worthy adversary for your soulbinds.\n\nShe has requested a special anointment oil used in kyrian ceremonies in return for her memory.", objectives = "" }
WordHunterWoW_QuestEN[61357] = { title = "Hatred Abated", description = "As agreed, you may take my memory for the trials you seek.\n\nHeed this warning, mortal--even as an echo of my physical form I will attack without hesitation. Expect no mercy, for I will show none.\n\nYou have done me a great service this day. See to your business.", objectives = "" }
WordHunterWoW_QuestEN[61358] = { title = "Alderyn and Myn'ir", description = "The Wild Hunt is made up of trackers and hunters of incredible might who protect Ardenweald from forces that wish to bring ruin to the place of rest.\n\nWe have reached out to a duo that has agreed to lend their memories if you help them take down a troublesome target.", objectives = "" }
WordHunterWoW_QuestEN[61359] = { title = "Power of the Primus", description = "As a Necrolord, your duty is to defend the Shadowlands. To carry out such service, the Primus grants us his strength.\n\nStand upon the altar of the Primus. Let his power become your own.", objectives = "" }
WordHunterWoW_QuestEN[61360] = { title = "The Hunt's Gratitude", description = "The forests of Ardenweald are safer with your help, envoy of the kyrian.\n\nAs a reward for your aid, we shall allow you to capture our memory. It is an honor to be chosen to help train the mighty warriors of Bastion.\n\nWhenever you are ready.", objectives = "" }
WordHunterWoW_QuestEN[61361] = { title = "Nuuminuuru", description = "The tirnenn of Ardenweald are ancient, mysterious fae with many lessons to teach. While they prefer to avoid conflict and battle, they are powerful foes if crossed.\n\nOne tirnenn has offered themself as a teacher for your soulbinds. Along with their fleet of faeries, they have many nontraditional, yet crucial, lessons to teach you.", objectives = "" }
WordHunterWoW_QuestEN[61362] = { title = "Caretaker of Faeries", description = "Tirnenn and faeries hold many dissimilarities.\n\nWhile tirnenn stand patient and calm, like the trees that grow tall and protect us, faeries dance and dart and declare their desires directly.\n\nDespite these differences, we stand together. Learning, growing, evolving.\n\nWe will help you and yours achieve the same symbiotic serenity.", objectives = "" }
WordHunterWoW_QuestEN[61363] = { title = "Mad Mortimer", description = "An alchemist in Maldraxxus swears that his new creation will be revolutionary, but is still missing a key catalyst.\n\nIf we lend him aid, he has agreed to allow you to capture his memory for the Path.", objectives = "" }
WordHunterWoW_QuestEN[61364] = { title = "Oozing with Opportunity", description = "They called me mad! As a matter of fact, they still do!\n\nAh, but none of them have the mental acuity of Doctor James Mortimus of the very much in-tact House of Plagues, nor his handsome smile! Fools!\n\nWith the catalyst you have so kindly provided, dear...whatever you are...certainly not a kyrian...\n\nI digress!\n\nWe shall get to whatever it is you wanted in a moment, for now is the time of SCIENCE! Come, come, let me show you the wondrous fruits of my labors!", objectives = "" }
WordHunterWoW_QuestEN[61365] = { title = "Splinterbark Nightmare", description = "Drust ritualists have created a horrific creature that threatens our nearby allies in Ardenweald.\n\nIf we can successfully clear a path to the creature and mark it with a Praetor Resonance Beacon, we can both capture its essence for the Path and ensure it does not bring harm to the fae realm.", objectives = "" }
WordHunterWoW_QuestEN[61366] = { title = "Tactical Operation", description = "Your target lies near the Oaken Assembly in Ardenweald on the Elder Strand. Take caution, for powerful drust forces lurk nearby.\n\nOnce your target is in sight, activate the beacon and protect the praetors that arrive as they work to subdue the beast. You will only be able to capture its memory once it has been fully incapacitated.\n\nMake haste, and good luck. Follow the path.", objectives = "" }
WordHunterWoW_QuestEN[61367] = { title = "Thran'tiok", description = "Maldraxxus is home to one of the most powerful types of anima wielders in the Shadowlands, the liches of the House of Rituals. \n\nTraining against a lich would teach your soulbinds important lessons and tactics they can wield if they ever come face to face with a magic user with ill intent.", objectives = "" }
WordHunterWoW_QuestEN[61368] = { title = "Filching Phylacteries", description = "This phylactery holds the soul of Thran'tiok... her very essence.\n\nBe quick in whatever you need to do. I must get this piece of her soul away from here before she returns.\n\nHer paranoia shall truly be her end.", objectives = "" }
WordHunterWoW_QuestEN[61369] = { title = "Craven Corinth", description = "One of Denathrius's former subjects, Craven Corinth, has been deemed too dangerous to roam free even in their light-bathed Ember Ward.\n\nHis memory would be a perfect opponent in the coliseum. All we need is a key to free him from his prison.", objectives = "" }
WordHunterWoW_QuestEN[61370] = { title = "No Other Way", description = "Corinth will not surrender his memory willingly. You must weaken him sufficiently before he will relent to the soul mirror's energy.\n\nYou will find him deep within the Desiccation in Revendreth, locked away among the other light-scarred venthyr. Once you free him, he will surely attack in his confused rage.\n\nSubdue him, and capture his memory. He may then roam free among his kind.", objectives = "" }
WordHunterWoW_QuestEN[61371] = { title = "Athanos", description = "For your final test in the Path, you must face an old friend from your first moments in this realm--Athanos.\n\nIt has been many millenia since the mighty goliath stepped into the arena with his legendary spear, Humility's Guard. The blade was disassembled upon his departure, as is tradition.\n\nShould Athanos bear witness to Humility's Guard once more, I believe he can be convinced to enter the arena once more. We have the shattered spear, but require materials to reforge it.", objectives = "" }
WordHunterWoW_QuestEN[61372] = { title = "Back to Him", description = "Even with Humility's Guard in hand, if you are to convince Athanos to join the Path of Ascension once more then you must prove yourself a worthy adversary.\n\nEnter the ring and wield the spear against him. Even with its power you cannot hope to defeat him, but it should be able to parry his mighty stomp.\n\nThwart his assault for long enough, and he will surely allow you to capture his memory.", objectives = "" }
WordHunterWoW_QuestEN[61373] = { title = "Azaruux, the Realm Ender", description = "You must act at once!\n\nA devourer of incredible strength has opened a rift in the coliseum and even now threatens to consume it! What few fighters were present at the time struggle to keep the creature at bay.\n\nIf this horror is not stopped, it will continue into the rest of the spires. You must take what anima you can in the area and subdue it.\n\nOnce the threat has been negated, take this spare mirror and capture its memory so we may learn more of its kind for future encounters.", objectives = "" }
WordHunterWoW_QuestEN[61388] = { title = "A Journey Made Together", description = "Binding souls is but the first step. \n\nOver time, the power of our bond will grow in strength and manifest itself in the form of amazing new abilities!\n\nTo tap into this newfound strength, all you must do is place your hand upon the Forge of Bonds. There is no price to pay--the only limitation is your connection to Necrolords.", objectives = "" }
WordHunterWoW_QuestEN[61391] = { title = "The Eye of the Jailer", description = "<The air around you stands still. A chill of domination suffuses your being. You hear a voice.>\n\nYes... I remember you...\n\nDo you think that because you evaded my grasp once, that I would let it happen again?\n\nNo. The Maw answers to me. All that befalls you here will be because I willed it so.\n\nDeath comes for you, mortal. Everywhere you go, my eye is upon you.", objectives = "" }
WordHunterWoW_QuestEN[61396] = { title = "Dark Developments", description = "<The torn document appears to have been written by Surgeon Stitchflesh.>\n\n...the kyrian flesh improves strength, obedience, and dexterity twofold! Such potential!\n\nNow, if subject number one-three-five succeeds in a proper wing transplant at last...\n\n<It continues on for some time. You should bring this to your kyrian allies.>", objectives = "" }
WordHunterWoW_QuestEN[61397] = { title = "Opportunity Strikes", description = "This sanctum cannot function on anima alone. It will take many willing souls working in harmony to unlock the full potential of the Seat of the Primus.\n\nOur Soul Warden is always in search of new souls to induct into the sanctum. Your ability to travel back and forth from the Maw will undoubtedly prove useful to him.\n\nYou should pay him a visit to see what assistance you can offer.", objectives = "" }
WordHunterWoW_QuestEN[61398] = { title = "Ember Court: Traditional", description = "Of course Darkhaven is honored to provide traditional decorations for Prince Renathal's court.\n\nVenthyr decor is all about setting a certain mood. That means lurking stonefiends and death blossom scented candles in vast quantity.\n\nOur resources are stretched thin, {name}. We can supply stonefiends easily, but our artisans need wax to melt with fresh death blossom. There should be candle remnants and drips in the village to scrape up. Death blossoms can be harvested from the plants themselves.", objectives = "" }
WordHunterWoW_QuestEN[61399] = { title = "Ember Court: Mortal Reminders", description = "For a reasonable renumeration, Ta Cartel can supply the decorations you require. \n\nRestocking unique and intriguing items is an important aspect of doing business. As you can freely return to your own world, you can provide me some new and exciting products to offer.\n\nYour world has captured the imagination of many of our clients. I have buyers looking for some specific things native to Azeroth.", objectives = "" }
WordHunterWoW_QuestEN[61400] = { title = "Ember Court: Mystery Mirrors", description = "I support Prince Renathal's efforts and will certainly help the Ember Court!\n\nMystery mirrors will be dangerous but add real excitement to the party. I will need a lot of mirror fragments to complete enough of them in time.\n\nYou will also need to refresh my supply of Ashen Cores so I can get the glass sufficiently molten to work.", objectives = "" }
WordHunterWoW_QuestEN[61401] = { title = "Ember Court: Venthyr Volunteers", description = "Oh, hello again!\n\nDid you hear that I have been given command of the guard for the Ember Court? That would probably be more impressive if there were already recruits.\n\nI need to get these recruiting posters up. If you can take care of that, I can meet the interested recruits here and then we can test their combat skills when you return.", objectives = "" }
WordHunterWoW_QuestEN[61402] = { title = "Ember Court: Stoneborn Reserves", description = "To call up the reserves to provide security for the Ember Court we will need anima. Good, loyal troops are ready as soon as we can animate them.\n\nWe will also need weapons for them.\n\nSort that out and I will make sure the Prince and his guests are well protected.", objectives = "" }
WordHunterWoW_QuestEN[61403] = { title = "Ember Court: Maldraxxus Army", description = "So your prince's little parties have attracted unwanted attention?\n\n<Emeni laughs.>\n\nI have my own long list of enemies, and far too many of them hide from me in the land of the living. Cowards!\n\nBut I have finally found a solution.\n\nTake this crystal to my remains on Azeroth, and use it to project my image among the living for a short time so that I may exact revenge on my old kin.", objectives = "" }
WordHunterWoW_QuestEN[61404] = { title = "Ember Court: Tubbins's Tea Party", description = "Theotar need tea for party? Tubbins make best!\n\nSpecial tea. Very special. Only I can make. Recipe need very good water from garden place. Good pool on special floaty island!\n\nYou go get and Tubbins makes tea!", objectives = "" }
WordHunterWoW_QuestEN[61405] = { title = "Ember Court: Divine Desserts", description = "Recipes very important. Must not be lost!\n\nI learn new foods from many mortals, add to my book. Best way is taste some of thing so can know what is good. You teach recipe to me this way and bring me right ingredients so I cook too. Then taste yours, then taste mine. Helps me learn.\n\nI bring desserts to Ember Court.\n\nFair, yes?", objectives = "" }
WordHunterWoW_QuestEN[61406] = { title = "Ember Court: Mushroom Surprise!", description = "I had not realized the fame of my fungi had reached so far. I'd be delighted to provide a mushroom feast to the Ember Court!\n\nHmmm... I will need you to collect some rare specimens and will loan you my favorite foraging bag. It will help you find the very best fungi. It's never failed me.\n\nLet's see, I need tiny lacy bells from Bastion and some of those Ardenweald fancy purple frills. From the very tops of our mushrooms here I will need the feather caps. You'll need to grapple your way up there.", objectives = "" }
WordHunterWoW_QuestEN[61407] = { title = "Ember Court: Atoning Rituals", description = "If Prince Renathal wishes to impart knowledge of Revendreth's highest calling to his guests, we would be honored to demonstrate the rituals of atonement.\n\nHowever, I must ask for your assistance preparing the necessary components quickly.\n\nCapture nearby fugitive souls that hide from the Lord Chamberlain's corrupt venthyr. Bring them to our avowed ritualists across the halls. They will prepare the souls for our purpose.\n\nSinstone fragments will also help us identify the sins of these lost souls.", objectives = "" }
WordHunterWoW_QuestEN[61408] = { title = "Ember Court: Glimpse of the Wilds", description = "It would be wonderful to show Revendreth the wild creatures of Ardenweald!\n\nYou can get some Radiant Groupers near the waterfalls. They're fast so you have to grab them as they swim by. \n\nHere's a net to use to subdue the Territorial Waders. They should follow you once you've caught them.\n\nHighland Runestags will let you ride them if you aren't aggressive. Bring a few here to me, please. Watch out for the bulls, they're not at all friendly.\n\nWe will get others to help too. This sounds like fun.", objectives = "" }
WordHunterWoW_QuestEN[61412] = { title = "An Early End", description = "Within the Hall of Chains lie more constructs that are nearly complete. As we speak, the Margrave's forces work fervently to graft the last pieces of flesh to their horrific visages.\n\nIf they are allowed to finish their work, then the destruction we have wrought thus far will make little difference in the final conflict. Our flank will be overrun by a fresh wave of horrors, and the day will be lost.\n\nThat must not come to pass. Destroy any of these abominations you encounter.", objectives = "" }
WordHunterWoW_QuestEN[61421] = { title = "Champion: Blisswing", description = "", objectives = "" }
WordHunterWoW_QuestEN[61422] = { title = "Champion: Duskleaf", description = "", objectives = "" }
WordHunterWoW_QuestEN[61423] = { title = "Champion: Karynmwylyann", description = "", objectives = "" }
WordHunterWoW_QuestEN[61424] = { title = "Champion: Chalkyth", description = "", objectives = "" }
WordHunterWoW_QuestEN[61425] = { title = "Champion: Lloth'wellyn", description = "", objectives = "" }
WordHunterWoW_QuestEN[61426] = { title = "Champion: Yira'lya", description = "", objectives = "" }
WordHunterWoW_QuestEN[61436] = { title = "Field Trip", description = "Now that you have the catalyst, you need only bring it to Mortimer in Maldraxxus. Our last correspondence indicates that his laboratory is still in-tact within the former House of Plagues.\n\nExercise caution in your journey--what remains of the house is fraught with danger, and Mortimer himself has earned a less than pristine reputation among his peers.", objectives = "" }
WordHunterWoW_QuestEN[61473] = { title = "Sourcing Your Own Materials", description = "I can aid you in crafting many pieces of equipment for your soulbinds.\n\nThough they may only equip one at a time, each piece grants a new ability that they may not have without it.\n\nThis time you must source your own materials from around the Shadowlands. When you have collected them, return to me and we can create the footpads!", objectives = "" }
WordHunterWoW_QuestEN[61475] = { title = "The Heart of the Forest", description = "I knew we were gonna get along! Welcome to our covenant. Well, almost.\n\nThere's just a few details left. Little things. You know. Oaths to be made, blood pacts to sort out, firstborns to be promised.\n\n<Moonberry snorts a laugh.>\n\nI'm just kidding!\n\nWell, not about the oaths part. We take those seriously around here.\n\nI'll meet you at the camp outside the Heart of the Forest!", objectives = "" }
WordHunterWoW_QuestEN[61478] = { title = "Humble Beginnings", description = "With Humility's Guard whole once more, you may be able to coax Athanos back into the arena.\n\nTravel to Aspirant's Crucible, where your journey began so long ago. Seek Forgelite Sophone--she guides all those who seek an encounter with Athanos.\n\nPresent the spear to her. She will know your intent and instruct you further.", objectives = "" }
WordHunterWoW_QuestEN[61479] = { title = "The Boon of Shapes", description = "<Moonberry looks serious.>\n\nMortal though you are, you have chosen to become one of our champions. While you uphold our cause, we are obligated to extend hospitality to you within our sacred hall and grant you certain boons.\n\nAs a member of the Court of Night, I can bestow our powers on chosen mortals.\n\n{name}, {class} of Azeroth,  I bid you welcome to the first tree, Tirna Achiad, the Heart of the Forest.\n\nPlease, follow me.", objectives = "" }
WordHunterWoW_QuestEN[61485] = { title = "I'll Only Say This Once", description = "At last, we are fully prepared to enact the baroness's plan.\n\nNow that you have arrived, I will recount our roles one final time. Then we will seize our fate.\n\nListen closely.", objectives = "" }
WordHunterWoW_QuestEN[61486] = { title = "The Banshee's Champion", description = "I... we... I mean... he's...\n\n<The young courier gulps.>\n\nWe found him. We found the Blightcaller.\n\nI was on patrol like I'd done a hundred times before only there he was sitting on the front porch of that old house with those terrible dogs and I swear he smirked at me and stared with those fiery red eyes and--\n\n<The young courier wipes his brow.>\n\nHe's at the Marris Stead. Our forces have him surrounded, but, uh...\n\nYou should probably gather your friends. I don't think he plans to surrender.", objectives = "" }
WordHunterWoW_QuestEN[61488] = { title = "The Banshee's Champion", description = "<The messenger appears visibly shaken.>\n\nWord has reached us of... well, I'm not quite sure how to put it...\n\nThe Blightcaller has been found.\n\nHorde forces have been scouring Azeroth for any sign of him. Determined to make him answer for his crimes.\n\nOne of our Argent patrols has found him. Not hiding in some distant land. Just... waiting at his old homestead.\n\nWe have him surrounded, but, uh, I confess I don't like our odds.\n\nPerhaps you could gather your allies and bring him to justice.", objectives = "" }
WordHunterWoW_QuestEN[61489] = { title = "Of Hearsay and Heresy", description = "Echthra has taken residence in one of the few remaining structures in the former House of Eyes in Maldraxxus.\n\nBring the anointment oil to her, and she should allow you to capture her memory. Take caution, for she is well-known both as a master marksman and--perhaps more notably--for her quick trigger finger.\n\nGood luck, Maw Walker.", objectives = "" }
WordHunterWoW_QuestEN[61490] = { title = "War of Information", description = "Ah, the anointment oil. I had expected one of Adrestes' recruits.\n\nNo matter. You seek my memory for your trials, yes? I am afraid mere oil will not suffice.\n\nWith our house gone, we are left to fend for ourselves. Though this tower offers some protection, we are left cornered to any who may desire our end.\n\nInformation is the key to survival. Use my anointed talisman to give me eyes across all the realms...even in Bastion. Follow the list precisely--no questions.\n\nThen can we resolve payment.", objectives = "" }
WordHunterWoW_QuestEN[61492] = { title = "The Princeguard", description = "Renathal carries himself well, but hides great pain. His wounds from Denathrius have not healed.\n\nHe is vulnerable.\n\nHe intends to send you to secure his old fortress of Darkwall Tower with banners and rely on his own strength to deter enemies. This is a poor tactical choice.\n\nTake this small reserve of anima with you and revive Chelra the Bladewall. She was last seen at Darkwall. Revive her and she can aid you in taking the tower.", objectives = "" }
WordHunterWoW_QuestEN[61496] = { title = "A Familiar Energy", description = "<The soul looks at you, thankful but curious.>\n\nI saw another living mortal in the Maw. He had the same... aura as you. Almost as if you were kin... no. Allies. Adventurers, bound by shared acts of courage.\n\nThat broker had him in her refuge. As for why, I cannot say.\n\nPerhaps you should find out.", objectives = "" }
WordHunterWoW_QuestEN[61509] = { title = "Shinies of Bastion", description = "Chordy is bored, boooored!\n\nYou want to go look for luckydos? Go on adventure with Chordy?\n\nWe go to land of wing people, go look for valuable luckydos there.\n\nReady?", objectives = "" }
WordHunterWoW_QuestEN[61510] = { title = "A Bountiful Haul", description = "Chordy want to go on adventure! You want to go too, yes?\n\nI scavenge, weapons, armor, and valuable luckydos! Though, luckydos seem to be in short supply these days.\n\nWe go to land of tree people! If we search together, we'll find many luckydos!", objectives = "" }
WordHunterWoW_QuestEN[61511] = { title = "Things They Leave Behind", description = "Chordy bored. Chordy want to go on adventure! You want to go too, yes?\n\nPale people in tall buildings have many shinies and luckydos. We go there and find some for ourselves!\n\nYou ready to go?", objectives = "" }
WordHunterWoW_QuestEN[61518] = { title = "Follow Me", description = "Assuming the others are in position, we are prepared to steal the necropolis.\n\nYou and I must push forward to rendezvous with Ansid. Khaliiq will regroup with Vyn once their tasks are complete.\n\nCome along, {name}, and stay near. I will shroud the both of us in shadow, so long as you are at my side.", objectives = "" }
WordHunterWoW_QuestEN[61522] = { title = "Corpse Run", description = "There's work that needs doing 'round here. Mmmm hmmm.\n\nSpotted a big ol' carcass nearby. I aim to salvage it for parts. \n\nFigure you could come along, help me drag it to Rathan. He'd like that. Mmmm hmmm. \n\nReckon I could even carry you there and back. You don't look too big.\n\nReady to get going?", objectives = "" }
WordHunterWoW_QuestEN[61523] = { title = "Corpse Run", description = "There's work that needs doing 'round here. Mmmm hmmm.\n\nSpotted a big ol' carcass nearby. I aim to salvage it for parts. \n\nFigure you could come along, help me drag it to Rathan. He'd like that. Mmmm hmmm. \n\nReckon I could even carry you there and back. You don't look too big.\n\nReady to get going?", objectives = "" }
WordHunterWoW_QuestEN[61541] = { title = "The Forge of Bonds", description = "{name}, are you ready for another gift?\n\nThe next boon we grant thee is one of bonds. As you have bound yourself to us, we shall bind to you. In the binding of souls, we become something greater.\n\n<Moonberry leans in close.>\n\nSounds scary, huh? Don't worry! You and your soulbind will both strengthen each other.\n\nWhen I asked for volunteers, many fae stepped forward. I picked someone I just know you're going to like. And this will be a boon for her, too.\n\nGo to Flutterby. She'll help you both.", objectives = "" }
WordHunterWoW_QuestEN[61542] = { title = "The Boon of Binding", description = "<Flutterby clasps her hands before her and assumes an air of tranquility.>\n\nSoulbinding is not an irrevocable act. However, such a bond must be carefully considered before it is made.\n\nYou and your soulbind will know each other's hearts and minds. Your hopes and fears; your dreams and memories; all will be shared between you. \n\nAs long as the bond exists, you are intertwined; always together even when apart.\n\nOnce complete, your connection will transcend physical space and empower you both.", objectives = "" }
WordHunterWoW_QuestEN[61548] = { title = "Set Me Free", description = "Ansid has been captured and imprisoned by the foundry's guards.\n\nIt seems they were expecting us, completely shattering the element of surprise. My baroness would be disappointed in my lack of foresight.\n\nThis plan cannot succeed without Ansid. One of these soldiers is bound to possess the key to his cage.\n\nShould you find it, we may yet carry out my baroness's will.", objectives = "" }
WordHunterWoW_QuestEN[61550] = { title = "Strengthening the Bond", description = "I know how you feel... and what you have endured for the sake of your world. \n\nYou now know of my own triumphs and tragedies as well.\n\nOur bond will grow stronger over time. But for now, let us see what it has granted us.\n\nArdenweald has needs of us. We must do everything in our power to save it.", objectives = "" }
WordHunterWoW_QuestEN[61551] = { title = "Crush 'Em All", description = "The mooring platform will be our best launching point to access the necropolis above. But one more fight remains before us.\n\nEnforcer Borgulla oversees all of the work efforts that take place here. We'll need to eliminate her if we are to proceed unhindered.\n\nShe is a formidable foe. It appears Ansid has kept some of his explosives on his person. Let us utilize this advantage.", objectives = "" }
WordHunterWoW_QuestEN[61552] = { title = "The Hunt Watches", description = "The Wild Hunt protects. Many eyes watch for danger. Many ears listen for secrets.\n\nWatcher Vesperbloom directs the eyes and ears of the forest.\n\nSeek out our new growth, then turn to her for guidance.", objectives = "" }
WordHunterWoW_QuestEN[61553] = { title = "Know Where to Strike", description = "It is the Wild Hunt's duty to hunt down those who would harm our charges and to ensure the security of our borders. But as the crisis has grown, so have our duties to Queen and Grove.\n\nThis is where I come in. It is my duty to be aware of all that goes on within the endless forest. It is my charge to help deploy our resources, so that we may aid our queen.\n\nAllow me to demonstrate...", objectives = "" }
WordHunterWoW_QuestEN[61557] = { title = "An Echo in the Darkness", description = "{name}, I... I am beset by dark visions. A power emanating from within Torghast.\n\nA familiar sensation. One I have not felt since...\n\nCome to Oribos. Do not delay.", objectives = "" }
WordHunterWoW_QuestEN[61558] = { title = "The Highlord's Vision", description = "<Thrall's brow is furrowed.>\n\nWe were speaking with the Highlord when he was struck by a jolt of agony.\n\nHe said he could see something stirring in the Maw. Inside the Jailer's tower.\n\nThe pain seems to be getting worse. We need to find out what he's sensing.", objectives = "" }
WordHunterWoW_QuestEN[61559] = { title = "A Mourneblade Born", description = "While his father was missing, I cared for Anduin like a son. To see him like that, at the mercy of Sylvanas...\n\n<Bolvar's eyes flare with fire.>\n\nSomething must be done.\n\nTake a moment. Let me know when you are ready to discuss what comes next.", objectives = "" }
WordHunterWoW_QuestEN[61567] = { title = "Grave Intent", description = "My spies have identified several astral projectors that Margrave Gharmal uses to rally their troops in the Stitchyard.\n\nI do not wish for a swarm of frenzied constructs to descend upon us during the final confrontation. Surely you see the wisdom in cutting their fervor.\n\nSee to it that these projectors are destroyed. We believe them to be along the yard's perimeter.", objectives = "" }
WordHunterWoW_QuestEN[61569] = { title = "Keys to the Ruin", description = "At last, our target is within reach.\n\nThe necropolis rests above us, moored to this platform by a necrotic restraining bolt.\n\nTwigin can fly you to the apex of the necropolis. It will be ours to command once you insert this keystone.\n\nWe will prepare for our departure. Rejoin us when you are done.\n\nVictory will soon be ours.", objectives = "" }
WordHunterWoW_QuestEN[61586] = { title = "Machinations of War", description = "With Bastion as our ally, we have the strength to crush Gharmal and the House of Constructs.\n\nWe'll gather the supplies for the attack, but our soldiers need a great champion to follow into battle.\n\nProve to them that you are the champion they seek.", objectives = "" }
WordHunterWoW_QuestEN[61594] = { title = "This Way Out", description = "We are fully prepared to launch the necropolis. We must hurry before Margrave Gharmal tries to interfere.\n\nSpeak with Vyn when you are prepared, but we mustn't waste time.\n\nWe will cast our shadow upon all of Maldraxxus.", objectives = "" }
WordHunterWoW_QuestEN[61616] = { title = "The Ember Court", description = "We've got everything we need to host our first real Ember Court whenever you're ready, Maw Walker.\n\nTake a moment to finalize everything, and then we'll open court!\n\nRemember, we're trying to impress Cryptkeeper Kassir and convince him that we know what we're doing, so make sure you choose the refreshments and entertainment we hired for him!\n\nOnce everything's ready, let me know and I'll open the court!", objectives = "" }
WordHunterWoW_QuestEN[61635] = { title = "Troubled Souls", description = "News of our work here has spread, new souls have arrived seeking to join us!\n\nTake their requests for new construct bodies. We'll see if we can build them new constructs too!", objectives = "" }
WordHunterWoW_QuestEN[61636] = { title = "PH - UNUSED", description = "You have proven your dedication to not only your soulbinds and their training, but to the ways of the kyrian.\n\nStand proudly in your accomplishments, but know that there is no end to what you can learn.\n\nYour accomplishments have not gone unnoticed. The Archon requests your presence.", objectives = "" }
WordHunterWoW_QuestEN[61637] = { title = "Unity", description = "A unique construct has chosen to join us, but its unethical creation leaves it most unsettled.\n\nThe fusing of fragmented Kyrian souls within this construct, gives it pain and suffering. We must find a way to harmonize these souls so they can live together in peace.\n\nCreate the Bindings of Wellbeing and bring ease to the Soulfused Construct.", objectives = "" }
WordHunterWoW_QuestEN[61638] = { title = "Iron Solution", description = "News of our work here has spread, new souls have arrived seeking to join us!\n\nTake their requests for new construct bodies. We'll see if we can build them new constructs too!", objectives = "" }
WordHunterWoW_QuestEN[61697] = { title = "A New Age", description = "With the final empowerment in place, our renewed Crest of Ascension stands bolstered by the might of not just Bastion, but all covenants.\n\nSoon new Ascended will grace these halls once more as aspirants finish their long-awaited trials.\n\nNone of this would be possible without your aid, Maw Walker. The honor of activating the Crest at last is yours.", objectives = "" }
WordHunterWoW_QuestEN[61701] = { title = "Searching the Grove", description = "It is clear that a struggle took place here. I fear that Kivarr may have been taken by the Drust.\n\nI scouted the surrounding area before you arrived. Eventide Grove has been overrun.\n\nThe Drust cannot have taken her far. We may yet be able to find her. I just pray that we are not too late...", objectives = "" }
WordHunterWoW_QuestEN[61702] = { title = "A Swift Intervention", description = "The Drust just took Kivarr away. They said they were going to sacrifice her in one of their rituals!\n\nIf we hurry, you may still be able to save her! I've seen where the Drust keep their sacrificial altar... it's scary, but I can take you there!\n\nThere's no time to waste! Follow me!", objectives = "" }
WordHunterWoW_QuestEN[61703] = { title = "Nox Root", description = "In order to perform the ritual, I will need some nox root from Darkreach.\n\nIt is a unique plant that only grows within soil that has been corrupted by Drust magic.\n\nDarkreach lies to the west, not far from my den. What was once a peaceful, verdant grove is now filled with blight and ruin.\n\nI will travel to the Heart of the Forest to prepare the ritual. Meet me there when you have gathered the nox root.", objectives = "" }
WordHunterWoW_QuestEN[61704] = { title = "Ember Court: Guest RSVPs", description = "Prince Renathal will wish to invite certain guests to each Ember Court.\n\nIn the future, we'll be able to adjust the guest list to make it easier to please everyone in attendance. But, we should follow the Prince's lead on this first one.\n\nWork with Lord Garridan and Lady Ilinca to ensure that Cryptkeeper Kassir is able to attend and returns his RSVP.\n\nIf you haven't met Cryptkeeper Kassir yet in your adventures, you may need to introduce yourself before he'll listen to you.", objectives = "" }
WordHunterWoW_QuestEN[61705] = { title = "Ember Court: Refreshments", description = "We should always serve refreshments in the Ember Court, tailoring our choice of refreshment type to the preferences of our guests.\n\nLuckily, I know our first guest well. Like Theotar, he prefers it to be Formal.\n\nWork with Picky Stefan to acquire everything we need to throw a fancy tea party.", objectives = "" }
WordHunterWoW_QuestEN[61706] = { title = "Ember Court: Entertainment", description = "Everyone loves entertainment!\n\nOur first guest is from the Halls of Atonement, so he will certainly appreciate a presentation of the powerful rituals the Accuser is capable of.\n\nWork with Hips to acquire everything we need to host atoning rituals at the Ember Court.", objectives = "" }
WordHunterWoW_QuestEN[61707] = { title = "Crumbled Reality", description = "As the drought and devourers eat our buildin's, the structures lose their hold on reality. Thing is, it ain't a clean process. Some of that debris is still infused with anima.\n\nWhen your out, be a stoneback an' bring us whatever infused debris you can find.\n\nSee, we can recycle it into new structures as you hero types go and get the anima flowin' again.\n\nBring it here an we'll get it sorted.", objectives = "" }
WordHunterWoW_QuestEN[61709] = { title = "Witch's Satchel", description = "I sent Ara'lon to steal a witch's satchel from the Drust... a dangerous task from which he has yet to return.\n\nThe Drust's nightscreamers carry many reagents we need to perform the ritual. We cannot proceed without one.\n\nYou must go to the Oaken Assembly to procure one of their satchels... and find Ara'lon, if you can.", objectives = "" }
WordHunterWoW_QuestEN[61710] = { title = "The Broken Spear", description = "<The shattered remains of a sylvari spear litter the ground. You recognize the spear as belonging to Ara'lon.\n\nThis confirms that Ara'lon was here. Unfortunately, he is nowhere to be found.\n\nLord Herne will want to know of your discovery.>", objectives = "" }
WordHunterWoW_QuestEN[61711] = { title = "Ritual of Purification", description = "I have finished making preparations for the ritual. The moment of truth has come.\n\nThe Drust fetish that Ulfar gave you will channel the ritual's power into Gweyir. It should counteract the curse that imprisons her mind.\n \nThis will not be pleasant. It may not even work. But this is the only chance we have to free her.", objectives = "" }
WordHunterWoW_QuestEN[61713] = { title = "Blueprint: Charm of Quickness", description = "<You have discovered plans for a charm that seems to make your soulbinds fleet of foot in the Path of Ascension.\n\nDactylis should be able to help you with crafting this charm.>", objectives = "" }
WordHunterWoW_QuestEN[61714] = { title = "Gilded Abacus", description = "<A beautifully crafted abacus rests in your hands. Its frame glimmers and shines in the light, its beads smooth auric orbs.\n\nYour steward will appreciate this as not only a useful gift, but an exquisite one.>", objectives = "" }
WordHunterWoW_QuestEN[61715] = { title = "Request of the Highlord", description = "The information you uncovered in Maldraxxus should quell the drums of war between the Necrolords and the Kyrian.\n\nAnd this message from the Primus... extraordinary!\n\nI would advise you to enlist Highlord Fordragon's counsel, but he appears preoccupied. Visitors from your world have come to seek him out. Quite insistently, I might add.\n\nThe nuances of mortal interaction elude me. But it seems the nature of their dialogue was rather... intense.\n\nPerhaps you can assist the Highlord with this matter.", objectives = "" }
WordHunterWoW_QuestEN[61716] = { title = "A Glimpse into Darkness", description = "When I put the Lich King's crown upon my head, I wanted the world to believe I was dead. Even my daughter, Taelia. I... thought a lie would be kinder than the truth.\n\nBut she is no longer the little girl I left in Kul Tiras. I see my choice was a selfish one.\n\n<Bolvar pauses.>\n\nShe and Lady Menethil have asked me to peer into the Maw to see if our allies yet live. It is a dangerous request, but one I cannot refuse.\n\nHelp me focus on the broken helm. Together, we may find a glimpse of truth.", objectives = "" }
WordHunterWoW_QuestEN[61729] = { title = "Adventurer: Rahel", description = "", objectives = "" }
WordHunterWoW_QuestEN[61730] = { title = "The Captive King", description = "King Anduin has not been found inside Torghast. I fear we could spend eternity searching those endless corridors to no avail.\n\nWe must know what fate has befallen him. To peer into the tower represents a grave risk, yet we have little choice.\n\nStand with me, {name}. We will use the broken Helm of Domination to see into that hellish place.\n\nPerhaps together we can hold back the hungry darkness.", objectives = "" }
WordHunterWoW_QuestEN[61732] = { title = "Old Habits Never Die", description = "Your redistribution of anima has been commendable so far.\n\nBut venthyr are still venthyr. They may spend eons educating souls on the folly of greed and hoarding, but they often fail to acknowledge the return of that trait in themselves, given enough time.\n\nMy scouts have witnessed a number of venthyr siphoning the anima you have redistributed and hoarding it within their estates and dwellings. \n\nSearch these places and recover this hoarded anima so that we might put it to better use.", objectives = "" }
WordHunterWoW_QuestEN[61733] = { title = "Big Bag of Creepers", description = "Right. You've been a polished bit of gray so far and it's appreciated from the bottom up for sure.\n\nWell, now I got a task for 'ou that would help all of us dredgers put that anima you obtained to good use.\n\nCreepers.\n\nNot just any creepers, but 'em mire creepers. 'Ey got a look about 'em and a taste about 'em that just sings when you put it to good use.\n\nAs you go trippin' around Revendreth, grab any creepers ya find an' stick 'em in this here sack. I'll pay ya.", objectives = "" }
WordHunterWoW_QuestEN[61734] = { title = "Census of Sins", description = "The Curator once knew the contents and locations of every sinstone in Revendreth dating back to the founding of this realm.\n\nSadly, her time in the Maw disrupted those essential parts of her vast intellect and we can no longer rely upon her for such knowledge. At least, not for a while. And so it falls to me to rebuild a 'living' archive.\n\nAs you venture into Revendreth I would ask that you recover the contents and location of certain sinstones. This will help us orient our archive.", objectives = "" }
WordHunterWoW_QuestEN[61735] = { title = "Awaken Our Allies", description = "I have need of your services.\n\nI have identified a collection of stoneborn throughout Revendreth whom may be swayed to our cause, or were already members of our cause before returning to their stone slumber.\n\nYou have provided us with the anima we needed, now it is time to put it to use. Seek out our allies and awaken them. I have fashioned an anima container for easier transport to aid in this endeavor. \n\nWe need an army if we are to face an army.", objectives = "" }
WordHunterWoW_QuestEN[61736] = { title = "Stolen Away", description = "There is much you need to be told, {name}.\n\nThe Scourge has returned. With the Helm of Domination shattered, their evil runs rampant. Unchecked.\n\nWhat's worse, Sylvanas Windrunner has sent her agents into the very heart of our kingdoms to take those who thwarted her efforts in the war.\n\nSpeak to Whitemane. She can tell you the rest.", objectives = "" }
WordHunterWoW_QuestEN[61737] = { title = "Stolen Away", description = "There is much you need to be told, {name}.\n\nThe Scourge has returned. With the Helm of Domination shattered, their evil runs rampant. Unchecked.\n\nWhat's worse, Sylvanas Windrunner has sent her agents into the very heart of our kingdoms to take those who thwarted her efforts in the war.\n\nSpeak to Nazgrim. He can tell you the rest.", objectives = "" }
WordHunterWoW_QuestEN[61738] = { title = "Ember Court: Lost Chalice Band", description = "Hips was smart to send you my way. The Lost Chalice Band plays the best music this side of the Maw!\n\nThe band is not quite ready to tour yet, however.\n\nThe musicians are all safe in the crypt behind me, but their instruments have been confiscated by our obnoxious neighborhood authorities!\n\nNoise complaints and all that.\n\nHelp me get those back, and perhaps recruit a few groupies and roadies along the way to help out, and we shall throw the best concert your court has ever seen!", objectives = "" }
WordHunterWoW_QuestEN[61739] = { title = "The Wayward Baron", description = "It has come to my attention that you seek to uncover a plot by the baron Kel'Thuzad. \n\nThat upstart has been a thorn in my side since he arrived at the House of Rituals. Not only did he pilfer my rightfully earned title, he has since shut me out of the house's dealings.\n\nI have yet to find evidence that would mar Sin'dane's adoration for her new baron, and thus I offer an arrangement. I grant you access to the House of Rituals, and in return you help me bring down Kel'Thuzad.\n\nDo we have an accord?", objectives = "" }
WordHunterWoW_QuestEN[61740] = { title = "Playing Favorites", description = "We will have to construct an illusion to allow you entry into the House of Rituals. However, not just any illusion will do. In order to join Kel'Thuzad's inner circle, we require something... specific.\n\nWe're going to need a body.\n\nFortunately for us, one of the baron's favorite acolytes is performing a ritual outside of the house itself. You'll need to fight your way to her, but of that I'm sure you're capable.", objectives = "" }
WordHunterWoW_QuestEN[61741] = { title = "Pilfered Power", description = "The illusion ritual will require a substantive amount of anima to complete. Since such a resource isn't simply lying around these days, we will need to take some.\n\nThe abominations from the House of Constructs recently arrived with a delivery of anima-rich spoils from the raid on Bastion. \n\nUse the maldracite crystal I've included in the parcel to extract enough anima for our ritual.", objectives = "" }
WordHunterWoW_QuestEN[61742] = { title = "A Fitting Guise", description = "The ritual to complete your disguise should be quite simple with the assistance of my oculus. Even a {class} like you should be able to manage it.\n\nWhen you are ready, simply hold the empowered crystal above Nelesis's corpse. My oculus will do the rest.", objectives = "" }
WordHunterWoW_QuestEN[61743] = { title = "The Pupil Returns", description = "Now that you have your disguise--and I have assurance of your loyalty--it is time you reported to your new master.\n\nFind Kel'Thuzad within the Vault of Souls. Do whatever tasks he requires of you, but keep your eyes open for anything untoward.\n\nMy oculus will continue to accompany you so that I can provide guidance when the time is right.\n\nWe will uncover this new baron's true intentions.", objectives = "" }
WordHunterWoW_QuestEN[61744] = { title = "The Baron's Plan", description = "You have done well in my service, Nelesis. When the time has come to take my rightful place, you will be well rewarded.\n\nUntil then, I will require your utmost devotion and secrecy.\n\nOur preparations are almost complete. Come, walk with me, and I will show you the splendor of our works.", objectives = "" }
WordHunterWoW_QuestEN[61745] = { title = "Mistress of Tomes", description = "The kyrian will no doubt make a worthy sacrifice for our ritual, but I am not entirely versed with the magics of his kind. I have requested that the Baroness Ninadar assemble a list of appropriate literature, so that I can ensure my ritual will have the desired effect.\n\nAs you know, the baroness enjoys exploiting her title, so expect to be faced with some manner of mundane tasks in exchange for her cooperation. \n\nReturn when you have procured the tomes, acolyte.", objectives = "" }
WordHunterWoW_QuestEN[61746] = { title = "Cantrip Collections", description = "One of the... more regrettable duties of the Mistress of Tomes is the collation and maintenance of our scroll library. Unfortunately, many of our acolytes are less than prompt when it comes to returning items they have borrowed, which requires me to seek them out and retrieve them myself.\n\nOf course, this is far too menial a task for a baroness, but that is why lackeys like you exist.\n\nGo, and retrieve my scrolls. Feel free to use whatever persuasive means you have at your disposal.", objectives = "" }
WordHunterWoW_QuestEN[61747] = { title = "Errant Enchantments", description = "The House of Rituals is a place of constant study. Every day, new incantations and formulae are concocted to further the arts of necromancy. \n\nIt can be difficult to keep track of such innovation. To aid in cataloguing our progress, our sorcerers have applied the use of enchanted quills and parchment. Unfortunately, if not properly stored, these implements tend to run amok. \n\nOf course, they were not properly stored.  Find the implements and return them to where they belong.", objectives = "" }
WordHunterWoW_QuestEN[61748] = { title = "The Hall of Tomes", description = "Very well, you can have your list. The volumes you seek can be found in the Hall of Tomes.\n\nNow, run back to your master like a good little pet.", objectives = "" }
WordHunterWoW_QuestEN[61749] = { title = "Necessary Ingredients", description = "As you are well aware, a ritual of this complexity requires several reagents. I have asked that Carver Jor'dan prepare what I'll need.\n\nSeek him out in the Reagentry, and provide whatever assistance he requests.", objectives = "" }
WordHunterWoW_QuestEN[61750] = { title = "Heart of the Forest", description = "The baron requests a veilwing's heart, but procuring one is going to be something of a problem. \n\n<Jor'dan gestures to the disarray nearby.>\n\nAs you can plainly see, one of our sorcerers proved incapable of restraining the beast. I regret to inform you that our only specimen has escaped.\n\nIt cannot have gone far, though. If you follow its tracks you should be able to catch up with it and retrieve the heart yourself.\n\nI assure you the baron will not be able to perform his ritual without it.", objectives = "" }
WordHunterWoW_QuestEN[61751] = { title = "Cage Free Spores", description = "I will need your assistance with the collection of one other reagent for your master. These spore clusters he requests--while normally a trivial matter--will require a bit of work.\n\nYou see, as the veilwing rampaged throughout the Reagentry, it toppled and broke several nearby cages hosting the blightrays from which we harvest the clusters.\n\nYou will have to collect them through more... conventional means. \n\nThe clusters are fragile, however, so try not to damage them while subduing the creatures.", objectives = "" }
WordHunterWoW_QuestEN[61752] = { title = "The Final Reagent", description = "I have gathered most of the remaining reagents on your master's list. All that remains is the special shipment he requested from Oribos.\n\nThe brokers have yet to deliver the shipment. When it arrives, your master will have all he needs to complete his ritual.", objectives = "" }
WordHunterWoW_QuestEN[61753] = { title = "Explosive Schemes", description = "The brokers deal in objects most exotic and profound. If Kel'Thuzad requires reagents from them, his ritual must be outside the normal scope of the House of Rituals.\n\nThis mysterious reagent could be the key to unlocking Kel'Thuzad's plan. We must get a hold of this delivery from Oribos. \n\nI have taken the liberty of concocting an alchemical bomb. Use it to ambush the caravan and retrieve whatever they are transporting.", objectives = "" }
WordHunterWoW_QuestEN[61754] = { title = "No Crate Unturned", description = "That explosion will likely bring onlookers from the House of Rituals. We must act quickly.\n\nSearch through the debris for anything that looks out of the ordinary. It is likely that Kel'Thuzad's mystery reagent won't be hard to spot.", objectives = "" }
WordHunterWoW_QuestEN[61755] = { title = "Blinding the Brokers", description = "We cannot allow Kel'Thuzad to discover who stopped his shipment. \n\nNone must be left to tell the tale of what transpired here.", objectives = "" }
WordHunterWoW_QuestEN[61756] = { title = "Designed to Fail", description = "The pieces are all coming together. The kyrian, the Paths of the First Ones, and runes of domination? \n\nKel'Thuzad is looking to breach the Maw!\n\nWe cannot allow this to happen! The Maw has been locked away from the Shadowlands for good reason. Opening that floodgate could be catastrophic!\n\nThe baron is too powerful to confront headlong, so we will stop his ritual instead. Return to him with his reagents. I have made some \"modifications\" that should provide a calamitous end to his scheme.", objectives = "" }
WordHunterWoW_QuestEN[61757] = { title = "Caught in the Act", description = "Well then, since it was you who managed to procure the missing reagent, I find it only fair that you assist me with the final ritual! \n\nI can guarantee that this incantation will see you promoted to a full sorcerer of the house!\n\nThe preparations are already made. We can begin as soon as you are ready.", objectives = "" }
WordHunterWoW_QuestEN[61758] = { title = "Improvised Implements", description = "There must be some way we can get ourselves out of these cells. \n\nI don't see anything I can use over here. Search your cell for anything that can facilitate our escape.", objectives = "" }
WordHunterWoW_QuestEN[61759] = { title = "A Helpful Hand", description = "It takes but a simple act of necromancy to animate a hand. Unfortunately, since you will be in closest proximity, you must be the one to command it.\n\nWhen you are ready, I will reanimate the hand. Once you have control, use it to pull the lever at the end of the hall. \n\nCouldn't be simpler, right?", objectives = "" }
WordHunterWoW_QuestEN[61760] = { title = "The Traitor Unmasked", description = "We must waste no time in warning the margrave of Kel'Thuzad's treachery. His reckless toying with forbidden powers could bring ruin to the house and beyond!\n\nLet us put an end to this!", objectives = "" }
WordHunterWoW_QuestEN[61761] = { title = "The Better Part of Valor", description = "We now have no choice but to make a strategic retreat. Kel'Thuzad is far too fortified within the necropolis, and if Ninadar is his ally, then the House of Rituals is firmly in his grasp.\n\nIt will take nothing short of an army to save the margrave now.", objectives = "" }
WordHunterWoW_QuestEN[61762] = { title = "Making a Smarter Dredger", description = "If he be hostin' fancy courts with you and Temel, this dredger's gotta be special...\n\nSmarter. Stronger. Quicker to apologize when they accidentally knock over the refreshments table and spill anima all over some poor duchess...\n\nI got an idea! Broker bloke at the Night Market was tryin' to sell me some important drinks. Kaja'Extreme or somethin'.\n\nSays it bigguns the brain, yeah? That's just what we need! \n\nTake these Scorchshrooms, that broker loves them, but note he rotates his costs each week.", objectives = "" }
WordHunterWoW_QuestEN[61763] = { title = "Dredging up an Assistant", description = "Here we go, onto the dredging part.\n\nJust like we made that biggun here earlier!\n\nI mean we don't need the stone of binding or three other dredgers, but you'll still be throwing stuff into the muck!\n\nSo it's the same. \n\nYou head to the shore with this here Kaja-Infused Dredger Mix I whipped up for you.\n\nToss it into that muck pool and let's meet that new dredger butler of yours!", objectives = "" }
WordHunterWoW_QuestEN[61764] = { title = "Dredging up a Name", description = "Oi, why aren't you addressing me by my proper name? Wait, I don't remember my name, proper or other. Does this mean I have amnesias? Oh no, I don't have a name, please, help!", objectives = "" }
WordHunterWoW_QuestEN[61765] = { title = "Words of Warding", description = "The towering citadel in the distance is protected by perilous walls, but its greatest dangers cannot be seen with mortal eyes.\n\nThe Mawsworn have placed invisible runes of warding throughout Perdition Hold. These traps have caught many intruders unaware.\n\nThe runes can be dispelled, but only if you can see them. I believe one of their soulcloaks should give you the sight you require.\n\nGood luck.", objectives = "" }
WordHunterWoW_QuestEN[61766] = { title = "Homegrown Help", description = "Every good party herald needs an assistant. Which is why I have you!\n\nBut every good party herald's assistant... also needs an assistant.\n\nWhich is why I procured permission from the prince for you to create your own dredger butler. We can start him on security while we cozy up to the guests and procure the necessary reading materials to train him on the social protocols of the different realms. He'll be entertaining the whole court in no time. \n\nNo, don't thank me. You've earned this!", objectives = "" }
WordHunterWoW_QuestEN[61767] = { title = "A Perilous Journey", description = "Mograine has rallied the House of the Chosen to strike at Margrave Gharmal and his House of Constructs. They grow in strength with each passing day--this may be our only chance.\n\nWe will join them on the field of battle. We will have justice for the fallen at my temple, as well as Mograine's own fallen kin.\n\nRendezvous at Spider's Watch within Maldraxxus' northern reaches. We will move from there.", objectives = "" }
WordHunterWoW_QuestEN[61768] = { title = "Stronger Together", description = "We are to meet Baroness Draka aboard the Zerekriss above this position. Trust our allies' judgment in the battle ahead--true courage is knowing when to rely on the wisdom of others.\n\nThe plan is simple. Clear out our flanks to ensure Gharmal's forces do not interfere with our true goal, then assault the Margrave himself.\n\nIf we fail, we fail in the name of justice.", objectives = "" }
WordHunterWoW_QuestEN[61769] = { title = "Fight and Flight", description = "Alexandros and Emeni will lead the Chosen assault on the western gate. \n\nYou and Xandria will direct your forces at the eastern gate. Secure the area and eliminate any resistance. \n\nOnce both flanks are secured we can attack Gharmal directly.", objectives = "" }
WordHunterWoW_QuestEN[61770] = { title = "The Butchers of Bastion", description = "Did these fiends show my kin mercy when they attacked Bastion? When they tore my brothers and sisters limb from limb and used them to create more of these... these things?!\n\nNo! The butchers of Bastion made clear their hearts that day!\n\nThey deserve only the eternal darkness that awaits them. Ensure they see it!", objectives = "" }
WordHunterWoW_QuestEN[61771] = { title = "Justice from Above", description = "Our forces above cannot fully descend upon this area while the Margrave's crystals cover the sky in destructive blasts.\n\nThe Margrave's foul butchers work even now to extract the remaining anima from the kyrian they abducted in their assault on Bastion. We must advance at once.\n\nI shall imbue you with the flames of courage so that you may mark the crystals. Once marked, I will destroy them from afar.", objectives = "" }
WordHunterWoW_QuestEN[61772] = { title = "Dark Developments", description = "<The torn design document appears to be written by the late Surgeon Stitchflesh.>\n\n...the kyrian flesh improves strength, obedience, and dexterity twofold! Such potential!\n\nNow, if subject number one-three-five succeeds in a proper wing transplant at last...\n\n<It continues on for some time. You should bring this to Artemede.>", objectives = "" }
WordHunterWoW_QuestEN[61773] = { title = "Descended", description = "Though we have stopped the creation of more juggernauts, one of their most vile creations yet draws breath. It was born of one of the most pained souls they took from my temple.\n\nAs I flew above their ranks I could hear their surgeons chanting its name above the din of combat--Woeblade. It is an affront to all the kyrian stand for, an atrocity beyond any other.\n\nMark it with the flames of courage when you engage, and we will help you destroy it.", objectives = "" }
WordHunterWoW_QuestEN[61774] = { title = "Burn Before Reading", description = "The scroll you recovered details all manner of horrific ways to 'integrate' fallen kyrian into Gharmal's abomination constructs.\n\nIt is also incomplete. There must be more of these among Stitchflesh's remaining followers.\n\nI saw a number of surgeons and their lackeys retreat into the Hall of Chains just ahead as we arrived. I suspect they hold more of these scrolls.\n\nWe must ensure they are never read again.", objectives = "" }
WordHunterWoW_QuestEN[61775] = { title = "An Early End", description = "Within the Hall of Chains lie more abominations that are nearly complete. As we speak the Margrave's forces work fervently to graft the last pieces of flesh to their horrific visages.\n\nIf they are allowed to finish their work, the constructs we have destroyed so far will mean little in the final conflict. Our flank will be overrun by a fresh wave of horrors, and the day will be lost.\n\nThat must not come to pass. Destroy any abominations you come across.", objectives = "" }
WordHunterWoW_QuestEN[61776] = { title = "Trouble on the Western Front", description = "Alexandros and our Maldraxxi allies need reinforcement at the western gate on the Margrave's opposite flank. They are barely holding on!\n\nOur forces will reinforce our position here and push forward towards Gharmal. We must make haste to Mograine--without both flanks we cannot hope to achieve victory.", objectives = "" }
WordHunterWoW_QuestEN[61777] = { title = "Charging The Blade", description = "We can't advance with those juggernauts bombarding our position! I led a strike against the nearest, but conventional weapons do nothing against their imbued hides.\n\nThankfully, I have an idea.\n\nYour old runeblade can't deal with them as it stands, but if you could purge Gharmal's empowered masses and absorb their essence into the blade...", objectives = "" }
WordHunterWoW_QuestEN[61778] = { title = "Aerial Advantage", description = "Gharmal's rocs dominate the skies above, striking at our forces as we advance. The Zerekriss can't get into position until they are cleared out!\n\nI would take care of them myself, but I'm not much of a flier. Don't have the balance for it!\n\nTake my riding hook and latch onto a roc. Once you're riding, just start hitting it 'til the job is done.", objectives = "" }
WordHunterWoW_QuestEN[61779] = { title = "Grave Intent", description = "My spies have identified several astral projectors that Margrave Gharmal uses to rally his troops in the Stitchyard.\n\nI do not wish for a swarm of frenzied constructs to descend upon us during the final confrontation. Surely you see the wisdom in cutting their fervor.\n\nSee to it that these projectors are destroyed. We believe them to be along the yard's perimeter.", objectives = "" }
WordHunterWoW_QuestEN[61780] = { title = "Power of the Chosen", description = "The Zerekriss is nearly in position. Now is the time to strike!\n\nWe must force Gharmal into the open together. Join me on my roc, and we will unleash your runeblade's power on the juggernauts.\n\nThe Margrave will be unable to ignore their deaths. Once he leaves his blighted tower, we can finish him once and for all.", objectives = "" }
WordHunterWoW_QuestEN[61781] = { title = "The End is Now", description = "Our forces have control of the House of Constructs, thanks to your intervention.\n\nNow, all that remains is the fall of the instigator themselves--Margrave Gharmal.\n\nThis battle has been long in the making, {name}. I am at your side without hesitation.\n\nLet us go to this monster. We will join Xandria to see him slain.", objectives = "" }
WordHunterWoW_QuestEN[61782] = { title = "Pursuit of Justice", description = "Draka stands ready to unleash the power of the Zerekriss upon Gharmal. We need only buy her time to focus its weapon.\n\nWhat we do now, we do for all of us. Bastion and Maldraxxus have both lost many to these fiends.\n\nHe will not be defeated easily, but united our forces will finally bring him to justice!", objectives = "" }
WordHunterWoW_QuestEN[61785] = { title = "An Expected Visitor", description = "One Alexandros Mograine of Maldraxxus is meeting with the Paragon of Courage in Archon's Rise. Xandria has requested you join them.\n\nThe two worked together recently to repel a nascent secondary assault on the Temple of Courage. Xandria seems to trust him well enough, so we have granted him access to the hold...for now.\n\nI suspect they will not stay here long. You should make haste.", objectives = "" }
WordHunterWoW_QuestEN[61786] = { title = "Adventurer: Stonehead", description = "", objectives = "" }
WordHunterWoW_QuestEN[61788] = { title = "Adventurer: Simone", description = "", objectives = "" }
WordHunterWoW_QuestEN[61789] = { title = "Adventurer: Lost Sybille", description = "", objectives = "" }
WordHunterWoW_QuestEN[61790] = { title = "Adventurer: Vulca", description = "", objectives = "" }
WordHunterWoW_QuestEN[61792] = { title = "Adventurer: Bogdan", description = "", objectives = "" }
WordHunterWoW_QuestEN[61839] = { title = "Nipping at the Undergrowth", description = "<The small gorger nips at your heels hungry and seeking your protection. Maybe it will like some of the plants here?>", objectives = "" }
WordHunterWoW_QuestEN[61840] = { title = "Vineroot on the Menu", description = "<Again the small gorger shows up and you can clearly see is looking for more Endmire Vineroot.>", objectives = "" }
WordHunterWoW_QuestEN[61842] = { title = "Vineroot Will Not Do", description = "<Clearly bigger, the gorger looks at a vineroot you point to and you can see the hint of menace in its eye at being offered the root again. It looks longingly at the devourer mites nearby.>", objectives = "" }
WordHunterWoW_QuestEN[61844] = { title = "Hungry Hungry Gorger", description = "<The gorger spawn bounded up to you, but was clearly looking at the devourer mites the entire time.>", objectives = "" }
WordHunterWoW_QuestEN[61845] = { title = "Edict of Doom: Devourers", description = "The infusion of anima within Revendreth has led to a resurgence in devourer infestations. These eaters of the world must be slain.\n\nBy order of Prince Renathal and the rightful Court of Harvesters, this edict decrees the doom upon these aberrations.\n\nComplete this quota of destruction within Revendreth and receive a reward equal to your efforts.", objectives = "" }
WordHunterWoW_QuestEN[61846] = { title = "Edict of Doom: Dredbats", description = "The recent suffusion of anima in the region has led to an increase in dredbats being animated far and above any intended volume.\n\nBy order of Prince Renathal and the true Court of Harvesters an edict of doom is declared on dredbats within Revendreth. \n\nAvoid those used for transport or assigned to specific duties, but slay any in the less tamed regions of the realm and a reward shall be proffered.", objectives = "" }
WordHunterWoW_QuestEN[61847] = { title = "Overdue Purging", description = "There are many duties of a stoneborn that have been forsaken by the plans of Denathrius. \n\nOne such duty is the elimination of manifestations. The process venthyr use to extract anima from souls is not clean, and often leads to unresolved issues made manifest. \n\nThese entities are dangerous if left unchecked, and increase in number thanks to your revivication of anima to these droughted lands.\n\nWhile you patrol Revendreth, destroy any manifestations you encounter and I shall provide you recompense.", objectives = "" }
WordHunterWoW_QuestEN[61848] = { title = "Edict of Doom: Sinstone Golems", description = "By order of the true Court of Harvesters an edict of doom is issued for any Sinstone Golems that have coalesced into dangerous sizes within the realm. \n\nThese entities are the manifestation of unresolved sins of those souls who failed their redemption and were condemned to the Maw. With the recent suffusion of anima to the region they have grown dangerously strong.\n\nExpunge them from existence and recompense shall be provided.", objectives = "" }
WordHunterWoW_QuestEN[61849] = { title = "Take the Bite Out of 'Em", description = "Right. So you got a quota of venthyr you need offed and I got a mean need for some payback.\n\nSee, you may not think it to look at me but 'em venthyr loooove to chew on me specifically. Not sure what dark habit followed them across the veil but I just was a squishy bag of indulgence for far too long.\n\nAs you go about offin' 'em venthyr for your normal... motivations... I'd ask you to bring me a bunch of fangs off 'em you off, as it were. \n\nI'll pay for payback!", objectives = "" }
WordHunterWoW_QuestEN[61851] = { title = "Shades of Muck", description = "Yeah, this here muck pool's got everythin' we need to make your dredger butler.\n\nWe'll make this one special just for you. Made to specifications, as the fangs say.\n\nFirst up, you gotta choose its color. Us dredgers comes in all kind of different shades of muck.\n\nTake a peek at some me fellow dredgers and let me know what color we should dredge up for your butler.\n\nWe can recolor a dredger after-the-fact, but it ain't pleasant.\n\n<Rendle shudders at the thought.>", objectives = "" }
WordHunterWoW_QuestEN[61852] = { title = "Adventurer: Guardian Kota", description = "", objectives = "" }
WordHunterWoW_QuestEN[61853] = { title = "Adventurer: Te'zan", description = "", objectives = "" }
WordHunterWoW_QuestEN[61854] = { title = "Adventurer: Master Sha'lor", description = "", objectives = "" }
WordHunterWoW_QuestEN[61855] = { title = "Adventurer: Qadarin", description = "", objectives = "" }
WordHunterWoW_QuestEN[61856] = { title = "Adventurer: Watcher Vesperbloom", description = "", objectives = "" }
WordHunterWoW_QuestEN[61857] = { title = "Adventurer: Groonoomcrooek", description = "", objectives = "" }
WordHunterWoW_QuestEN[61859] = { title = "Adventurer: Nemea", description = "", objectives = "" }
WordHunterWoW_QuestEN[61860] = { title = "Adventurer: Pelodis", description = "", objectives = "" }
WordHunterWoW_QuestEN[61861] = { title = "Adventurer: Sika", description = "", objectives = "" }
WordHunterWoW_QuestEN[61862] = { title = "Adventurer: Clora", description = "", objectives = "" }
WordHunterWoW_QuestEN[61863] = { title = "Adventurer: Apolon", description = "", objectives = "" }
WordHunterWoW_QuestEN[61864] = { title = "Adventurer: Bron", description = "", objectives = "" }
WordHunterWoW_QuestEN[61865] = { title = "Adventurer: Disciple Kosmas", description = "", objectives = "" }
WordHunterWoW_QuestEN[61869] = { title = "Search the Place", description = "Zerekriss is ours... along with everything it contains.\n\nThe Primus was personally involved in the design of this necropolis. It was truly a sight to witness his hands shape the form of this vessel.\n\nIt would be wise to search the room. Perhaps he kept some tools here that might be of use to us.", objectives = "" }
WordHunterWoW_QuestEN[61871] = { title = "To Current Matters", description = "Ye've done good here, champion. MOTHER and I will be figurin' out what te do next.\n\nYe best get back te matters at hand, and do what ye can te empower that necklace o' yours.\n\nI've got ways te reach ye once MOTHER and I have fixed things up here.", objectives = "" }
WordHunterWoW_QuestEN[61872] = { title = "To Current Matters", description = "Ye've done good here, champion. MOTHER and I will be figurin' out what te do next.\n\nYe best get back te matters at hand, and do what ye can te empower that necklace o' yours.\n\nI've got ways te reach ye once MOTHER and I have fixed things up here.", objectives = "" }
WordHunterWoW_QuestEN[61874] = { title = "Shadowlands: A Chilling Summons", description = "The time has come, {class}.\n\nHighlord Bolvar Fordragon requests your presence atop Icecrown Citadel. Meet me in Orgrimmar, and I will take you to him.\n\nI would not keep him waiting.", objectives = "" }
WordHunterWoW_QuestEN[61875] = { title = "Doing the Dew", description = "The Thistledrop is magnificent creature. The roots go deep into the earth where they drink of waters most ancient. With these waters they collect the very essence of the land into a drop of dew that enables our artisans to craft powerful armaments.\n\nHelp us gather the dew and you will be well rewarded.\n\nHurry, before it evaporates!", objectives = "" }
WordHunterWoW_QuestEN[61876] = { title = "Take Heart", description = "Mograine and I spoke at length when he visited Bastion. He suggested that should we manage to kill Gharmal, his heart could be used to empower the Crest of Ascension.\n\nThe Margrave bears the power to shape form in ways few beings can. Though his results are grim, if we could harness that power our Ascended would be stronger than ever before.\n\nIt is not our way, but our way is changing, I think. Perhaps this is a step on our new path.", objectives = "" }
WordHunterWoW_QuestEN[61877] = { title = "Return to the Hold", description = "Let us ferry the heart to Elysian Hold swiftly.\n\nThere are many in the Shadowlands who would strike at us to take its power for their own. Keep your eyes open, Maw Walker.\n\nWe return to our kin victorious this day.", objectives = "" }
WordHunterWoW_QuestEN[61878] = { title = "Crest of Greatness", description = "Once you are ready, all you must do is place the heart within the sphere here on the Crest of Ascension.\n\nMikanikos's handiwork will ensure that its energy is channeled properly to aid in our ascension rituals, and its power should help protect the Crest against any further attack.\n\nMay the House of Constructs never set foot in our realm again.", objectives = "" }
WordHunterWoW_QuestEN[61880] = { title = "Honored Attendance", description = "It is my humble honor to be the Ember Court's first guest.\n\nPlease inform Prince Renathal and all of your other compatriots that I will certainly attend whenever you wish to open the gates.", objectives = "" }
WordHunterWoW_QuestEN[61882] = { title = "Formal Entertainment", description = "The Accuser will be pleased that you have chosen such humble and formal entertainment for the first Ember Court.\n\nI look forward to the occasion.", objectives = "" }
WordHunterWoW_QuestEN[61884] = { title = "Formal Refreshments", description = "Tubbins's tea ready soon. Go tell Theotar and friends.\n\nTubbins is best!", objectives = "" }
WordHunterWoW_QuestEN[61892] = { title = "Ember Court Ambassador", description = "Expanding your influence is quite simple.\n\nFind someone. Ask them what they want. Give it to them.\n\nCongratulations. You now have influence with them.\n\nIf we wish to engage the other realms and win them over to our side, we must do the same on a larger scale.\n\nSo go to the other realms. Give them what they want. Expand our influence.", objectives = "" }
WordHunterWoW_QuestEN[61893] = { title = "Ember Court Ambassador", description = "Expanding your influence is quite simple.\n\nFind someone. Ask them what they want. Give it to them.\n\nCongratulations. You now have influence with them.\n\nIf we wish to engage the other realms and win them over to our side, we must do the same on a larger scale.\n\nSo go to the other realms. Give them what they want. Expand our influence.", objectives = "" }
WordHunterWoW_QuestEN[61894] = { title = "Ember Court Ambassador", description = "Expanding your influence is quite simple.\n\nFind someone. Ask them what they want. Give it to them.\n\nCongratulations. You now have influence with them.\n\nIf we wish to engage the other realms and win them over to our side, we must do the same on a larger scale.\n\nSo go to the other realms. Give them what they want. Expand our influence.", objectives = "" }
WordHunterWoW_QuestEN[61895] = { title = "Ember Court Ambassador", description = "Expanding your influence is quite simple.\n\nFind someone. Ask them what they want. Give it to them.\n\nCongratulations. You now have influence with them.\n\nIf we wish to engage the other realms and win them over to our side, we must do the same on a larger scale.\n\nSo go to the other realms. Give them what they want. Expand our influence.", objectives = "" }
WordHunterWoW_QuestEN[61896] = { title = "Undercover Security", description = "Do you know why the venthyr carve stoneborn into different shapes?\n\nBecause diversity in form allows for diversity in strategy. Our different shapes give us different purpose.\n\nWe need a new shape to solidify our court defenses.\n\nWith the right training and tools, venthyr guards could be hidden in plain sight--posed as greeters.\n\nAble to be among the guests without raising concerns, they'd be the first to respond to active threats.", objectives = "" }
WordHunterWoW_QuestEN[61898] = { title = "Small Bites", description = "The reviews are in, {name}. Our menu is too Revendreth-centric!\n\nAll the best courts have exotic appetizers, small plates, and other specialties that guests can look forward to every time they come.\n\nAnd for a court like ours, which boasts frequent guests from other realms, we simply must do better!\n\nDo not worry, after tireless research, I have drafted a very particular list of ingredients for you to find me.\n\nBring them to me, and I will serve our guests eternity on a platter!", objectives = "" }
WordHunterWoW_QuestEN[61899] = { title = "Anima Tastings", description = "You started a trend, {name}!\n\nYour constant gallivanting around the different realms of the Shadowlands has inspired a new flair for the exotic among Revendreth's elite. If it's from outside Revendreth, the venthyr want to try it.\n\nAnd I know just what the next big thing will be: anima tastings!\n\nThink about it: we--and by 'we' I mean 'you'--bring back fresh anima from all the different realms you travel to.\n\nThen socialites get to sip it and pretend it tastes like wherever you got it from!", objectives = "" }
WordHunterWoW_QuestEN[61900] = { title = "Comfy Chairs", description = "I want guests to sit.\n\nStanding is hard. I know 'cause I stand a lot.\n\nGuest should sit and be comfy.\n\nI make comfy chairs for all guests to sit.\n\nGuests be happy, stay longer!", objectives = "" }
WordHunterWoW_QuestEN[61943] = { title = "Court Influencer", description = "", objectives = "" }
WordHunterWoW_QuestEN[61944] = { title = "Discerning Taste", description = "", objectives = "" }
WordHunterWoW_QuestEN[61945] = { title = "The Professionals", description = "Smart move bringing in the specialists, {name}.\n\nOnce you get into this week's Ember Court, be sure to let the specialists know what you want them to do.\n\nBreakfist down in the dredger pools can smash or clean things to make the court more Messy or Clean for you.\n\nCrooked Crick in the refreshments area can adjust Decadence.\n\nLady Ilinca in the embassy area can adjust Formality.\n\nCosmin the Illusionist on stage can adjust Excitement.\n\nWing Commander Vulpek at the front gates can adjust Danger.", objectives = "" }
WordHunterWoW_QuestEN[61950] = { title = "Hunting the Wilds", description = "The supply of attuned anima is running low again. I'm surprised that we've managed to stretch our resources so far without a resupply.\n\nYou've proven yourself proficient at tracking down what is needed, perhaps you could assist us once again?\n\nThe runestags that roam Ardenweald's forests are particularly suffused with the power of the wilds, anima retrieved from them will be optimal for our needs.\n\nGood hunting!", objectives = "" }
WordHunterWoW_QuestEN[61957] = { title = "Champion: Ashraka", description = "", objectives = "" }
WordHunterWoW_QuestEN[61958] = { title = "Champion: Gorgelimb", description = "", objectives = "" }
WordHunterWoW_QuestEN[61959] = { title = "Champion: Talethi", description = "", objectives = "" }
WordHunterWoW_QuestEN[61960] = { title = "Champion: Xertora", description = "", objectives = "" }
WordHunterWoW_QuestEN[61961] = { title = "Champion: Rattlebag", description = "", objectives = "" }
WordHunterWoW_QuestEN[61962] = { title = "Champion: Velkein", description = "", objectives = "" }
WordHunterWoW_QuestEN[61963] = { title = "Called to the Hunt", description = "The Wild Hunt is made up of fae who have dedicated their lives to the protection of Ardenweald and its denizens. Each member has skill sharp as a blade and sense unlike no other.\n\nWe have spoken to a duo, an evoker and a huntress, who will permit us to capture their memories for training if we help them on a particular hunt.\n\nMeet Alderyn in Claw's Edge. He is one you seek.", objectives = "" }
WordHunterWoW_QuestEN[61965] = { title = "Piercing the Shell", description = "Our quarry is one of the gorm, native creatures who were once helpful beasts of the realm, until the drought drove them mad.\n\nThis particular beast has not only grown to a frightening size, but also has a shell so strong that none of our weapons or arrows have managed to pierce it.\n\nThis spear you bring, infused with the anima of Bastion, could be the exact weapon we need to pierce the gorm's armor and put him down.\n\nMy sister went ahead to scout. Let's not linger.", objectives = "" }
WordHunterWoW_QuestEN[61968] = { title = "Just Wing It", description = "For untold ages, the humble Ardenmoth has supplied the scales for the creation of armor for the Wild Hunt. \n\nNow, with our attention divided between the threats to the realm and the anima drought, it has become increasingly difficult for our foragers to find the perfect scales that we require.\n\nOnly the scales of the highest quality are suitable. If you should obtain any in your travels and return with them, I shall ensure you are well rewarded.", objectives = "" }
WordHunterWoW_QuestEN[61981] = { title = "Replenish the Reservoir", description = "Right, here's the gig: we need anima.\n\nNot just a bit or a pinch, but a lot. See, anythin' worth doin' can't be done without anima. Not in the Shadowlands. Not if we are gonna fix this mess Denathrius got us in.\n\nSo, we need your increasin'ly resourceful self to beg, borrow, steal, nick, burglarize, pulverize, pirate-ize, earn, swindle, or otherwise become the source of a great charity of any anima you can get.\n\nBring it to me, an' I'll stock our coffers, as it were, so you can put it to use.", objectives = "" }
WordHunterWoW_QuestEN[61982] = { title = "Replenish the Reservoir", description = "Hail, Maw Walker.\n\nAs our influence over Bastion grows, so too does our need for our most precious resource--anima.\n\nWe must replenish our reserves. Scour the realms for all that you can find and return here with the anima. \n\nWith our precious reserves replenished, we can direct the anima wherever it is needed most.\n\nGo in service, {class}.", objectives = "" }
WordHunterWoW_QuestEN[61983] = { title = "Replenish the Reservoir", description = "We require your strength, Maw Walker.\n\nThe houses of our enemies grow stronger by the hour. In order to press the attack we must find new sources of anima to bolster our reserves.\n\nSearch the realms for this precious resource and bring it back here to the Sanctum. Let none deny you!\n\nWith your help the rival houses shall fall, one by one, and we will emerge victorious!", objectives = "" }
WordHunterWoW_QuestEN[61984] = { title = "Replenish the Reservoir", description = "Greetings, Maw Walker.\n\nThe Tirna Achiad, Heart of Ardenweald, flourishes in our care, yet more anima is needed for our Sanctum.\n\nThe cycle of rebirth, our purpose, must continue.\n\nTo help our Queen, we must acquire more. Will you help us replenish the reservoir?", objectives = "" }
WordHunterWoW_QuestEN[61985] = { title = "Wake The Sleepers", description = "The land speaks to me, {name}. Ardenweald is a realm of cycles, but it has never faced an anima drought such as this.\n\nWe will need the aid of all who reside here if we are to make it through this crisis.\n\nMany souls slumber within the forests and hills. If they can provide us some of their anima, we may be able to endure a little longer. Should you encounter any of the souls in your travels, please awaken them and send them to me.", objectives = "" }
WordHunterWoW_QuestEN[61996] = { title = "Say The Magic Words", description = "Ever since I cast my first spell, I've not been able to get enough of magic!\n\nIt's not as hard as all those liches say it is. You focus your thoughts, say the words, and magic starts happening!\n\nThere are tomes documenting ancient spells stored in the Archivam of Revendreth. Help me gather them so I can learn some new spells!", objectives = "" }
WordHunterWoW_QuestEN[62000] = { title = "Choosing Your Purpose", description = "Each covenant is vital to the Shadowlands. Though they have been isolated and divided as of late, the Purpose depends on the success of their efforts.\n\nAll of the covenants must bolster their strength to face the threat of the Banished One. But your contributions cannot be divided. They must be focused upon a single path. Other mortals may make a different choice.\n\nSpeak to your potential allies. Then make your choice at the map of the Shadowlands before me.", objectives = "" }
WordHunterWoW_QuestEN[62041] = { title = "In A Bad Light", description = "I've heard about the chaos in Revendreth. Reports of exiles driven mad and burned in the Desiccation. \n\nThe very thought of all that suffering fills me with the urge to do something about it.\n\nIf you are headed there, please let me accompany you. I simply must help as many as I can!", objectives = "" }
WordHunterWoW_QuestEN[62043] = { title = "Prove Your Worth", description = "You must prove your worth to us again {name}.\n\nWe have not forgotten your betrayal.\n\nYet you say you seek penance. This task will start to demonstrate that you are serious about earning back our trust.", objectives = "" }
WordHunterWoW_QuestEN[62044] = { title = "Standing Toe To Toe", description = "<The gorger is clearly bigger, it gestures with its head towards one of the other gorgers as if urging you to attack it.>", objectives = "" }
WordHunterWoW_QuestEN[62045] = { title = "Ready for More", description = "<Again the gorger is strutting ready for more fighting, staring down the the closest gorger.>", objectives = "" }
WordHunterWoW_QuestEN[62046] = { title = "A New Pack", description = "<The gorger is more than fully grown, rivaling most of the other devourers in the area. It clearly wants to stay with you, but it appears to be uneasy straying too far from the world eaters. Maybe if you take one down together it will not hold as much sway over the gorger.>", objectives = "" }
WordHunterWoW_QuestEN[62052] = { title = "Exiled by Paranoia", description = "The liches of the House of Rituals were an instrumental piece in the Maldraxxi attack on Bastion. They are not currenty our allies, and it would be difficult to convince one to let us capture their memory for our training purposes.\n\nWe have made contact with a necromancer who has a score to settle with one of the liches. Find her and she will aid you in capturing this memory.", objectives = "" }
WordHunterWoW_QuestEN[62053] = { title = "Necromantic Power", description = "My old master, Thran'tiok, is the epitome of paranoia. She believes everybody will turn on her, and it led to my exilement from not only her service, but the House of Rituals as a whole.\n\nI had no intent to cross her... but that has changed.\n\nTake the crystal casing you have built and slay my old colleagues to infuse it with necromantic energy. It shall lead you to Thran'tiok's phylactery, which should be exactly what we both seek.", objectives = "" }
WordHunterWoW_QuestEN[62054] = { title = "Castle Nathria: Getting a Head", description = "We need to show Denathrius that we mean business. His dredger... pet... should do the trick.\n\nBring me his head. Four times should do it. Dredgers are curious creatures.", objectives = "" }
WordHunterWoW_QuestEN[62055] = { title = "Castle Nathria: Getting a Head", description = "We need to show Denathrius that we mean business. His dredger... pet... should do the trick.\n\nBring me his head. Four times should do it. Dredgers are curious creatures.", objectives = "" }
WordHunterWoW_QuestEN[62056] = { title = "Castle Nathria: Getting a Head", description = "We need to show Denathrius that we mean business. His dredger... pet... should do the trick.\n\nBring me his head. Four times should do it. Dredgers are curious creatures.", objectives = "" }
WordHunterWoW_QuestEN[62057] = { title = "Those Who Hunger", description = "I've heard reports that the number of gorm sightings have risen greatly the past few days.\n\nNormally they're simple decomposers, playing their part in the great cycle, but in great numbers the gorm can be aggressive. If left unchecked, their ravenous hunger will cause untold destruction.\n\nThe Wild Hunt has called for a gorm hunt. Meet your quota and you will be well-rewarded.", objectives = "" }
WordHunterWoW_QuestEN[62059] = { title = "Prove Your Worth", description = "You must prove your worth to us again {name}.\n\nWe have not forgotten your betrayal.\n\nYet we know you seek penance. This task should prove your willingness to rejoin our ranks.", objectives = "" }
WordHunterWoW_QuestEN[62060] = { title = "Prove Your Worth", description = "You must prove your worth to us again {name}.\n\nWe have not forgotten your betrayal.\n\nYet we know you seek penance. This task should prove your willingness to rejoin our ranks.", objectives = "" }
WordHunterWoW_QuestEN[62061] = { title = "Prove Your Worth", description = "You must prove your worth to us again {name}.\n\nWe have not forgotten your betrayal.\n\nYet we know you seek penance. This task should prove your willingness to rejoin our ranks.", objectives = "" }
WordHunterWoW_QuestEN[62071] = { title = "RRP Test Quest", description = "RRP Test Quest", objectives = "" }
WordHunterWoW_QuestEN[62072] = { title = "Familiar Faces", description = "<You arrive alone at the precipice of a strange city, knowing the leaders of Azeroth remain trapped in the Maw.\n\nWherever you are, it is clearly very, very far from home.\n\nIt appears your arrival has been noticed.>", objectives = "" }
WordHunterWoW_QuestEN[62074] = { title = "Professions - Reuse", description = "You've found what appears to be a memory of sorts. Perhaps it's another of the Runecarver's stolen memories.", objectives = "" }
WordHunterWoW_QuestEN[62077] = { title = "To the Chase", description = "You have been to the Maw and seen the Jailer, yes? His forces threaten the entire Shadowlands.\n\nThe covenants of Shadowlands are trying to fight back against the Jailer. They could use your aid.\n\nTal-Inara, the voice of the Arbiter, wishes to speak with you. She will help you with your Purpose.\n\nMake haste.", objectives = "" }
WordHunterWoW_QuestEN[62081] = { title = "Return Those Animacones!", description = "Reports say that once again the spriggan are proving to be a nuisance, {name}.\n\nWord is that a bunch of them broke into the stores at the Heart of the Forest and made off with a huge store of animacones.\n\nNeedless to say, we need those animacones back.\n\nThe report says the spriggan group split up as they were making their escape, so any one you see is as likely to be carrying the animacones as the next. \n\nGood luck.", objectives = "" }
WordHunterWoW_QuestEN[62085] = { title = "...Why Me?", description = "<The dense, chunky liquid inside the vessel emits a horrendous odor.\n\nThe initials O.K. are etched into the side. It seems someone stole Overseer Kalvaros' canteen.>", objectives = "" }
WordHunterWoW_QuestEN[62086] = { title = "Professions - Reuse", description = "You've found what appears to be a memory of sorts. Perhaps it's another of the Runecarver's stolen memories.", objectives = "" }
WordHunterWoW_QuestEN[62088] = { title = "Professions - Reuse", description = "You've found what appears to be a memory of sorts. Perhaps it's another of the Runecarver's stolen memories.", objectives = "" }
