WordHunterWoW_QuestEN[62155] = { title = "Runestone Roundup", description = "Stone is a rare material in Ardenweald. Yet, I've heard tales that those who were masked by the Drust have small stones upon them.\n\nI'd like you to retrieve some of these stones for the Wild Hunt, so that we may better understand their link to our enemy.\nFace the masked and collect the stones from their deceased forms and I'll compensate you for your efforts.\n\nIt's a gruesome task, but one that must be done.", objectives = "" }
WordHunterWoW_QuestEN[62157] = { title = "Scouting from a Safe Distance", description = "The resurgence of the Scourge is troubling enough, but there are also reports that the Cult of the Damned has risen anew as well.\n\nIf true, then that bodes ill for us all. We cannot allow the cultists' machinations to continue unchecked.\n\nI suggest we engage in some reconnaissance.", objectives = "" }
WordHunterWoW_QuestEN[62159] = { title = "Aiding the Shadowlands", description = "There is much to do within the Shadowlands. Many areas are suffering from the anima drought.\n\nThe choice of who to help first is yours. Where will you go?", objectives = "" }
WordHunterWoW_QuestEN[62160] = { title = "A Bundle of Lilies", description = "This grove needs something special, something to make it really stand out.\n\nI have a plan, but first I need flowers.\n\nNot just any flowers, but Night Lillies. They have a sweet scent that evokes starlit nights spent standing on a hilltop overlooking the majesty of the land.\n\nAs you go exploring Ardenweald, look to the waterways for Night Lillies growing in the waterways and collect them.\nI will pay you for your efforts, of course.", objectives = "" }
WordHunterWoW_QuestEN[62161] = { title = "Blood from a Bone", description = "I want nothing more than to make for Revendreth immediately... but it seems they have their own challenges to face.\n\nAll know of the mark we left on Bastion. The venthyr are sure to be wary of allowing us into their realm.\n\nOnce again, we must turn to you. Your renown across the Shadowlands has earned you the trust of many. Now, we need the trust of Revendreth.", objectives = "" }
WordHunterWoW_QuestEN[62162] = { title = "A Message from the Justicar", description = "Justicar Trueheart has sent a personal request for your immediate assistance, {name}.\n\nThe frozen winds of Icecrown await your return.", objectives = "" }
WordHunterWoW_QuestEN[62163] = { title = "A Message from the Justicar", description = "Justicar Trueheart has sent a personal request for your immediate assistance, {name}.\n\nThe frozen winds of Icecrown await your return.", objectives = "" }
WordHunterWoW_QuestEN[62165] = { title = "Tal-Inara's Call", description = "Your presence is needed within the Enclave.\n\nIt is time for you to choose a covenant to ally yourself with.", objectives = "" }
WordHunterWoW_QuestEN[62166] = { title = "Tal-Inara's Call", description = "Your presence is needed within the Enclave.\n\nIt is time for you to choose a covenant to ally yourself with.", objectives = "" }
WordHunterWoW_QuestEN[62169] = { title = "Eyes to the Sky", description = "The House of Eyes still reels from Akarek's demise. They search for direction. For purpose.\n\nPerhaps you can help them find it. Continue to gain the trust of the Eyes. Their skills will be invaluable to our cause.", objectives = "" }
WordHunterWoW_QuestEN[62170] = { title = "You'll Never Walk Alone", description = "<You have stumbled upon some messy notes. Some of the lines seem incomprehensible while others seem melodic.>\n\nLike wind and rain, discord storms my mind, tossing and blowing.\n...\nI must find the golden skies.\n...\nRemember, walk on, heart full of hope, and you'll never walk alone.\n\n<It seems as though an aspirant cannot find their way home. You should inform someone at Hero's Rest.>", objectives = "" }
WordHunterWoW_QuestEN[62172] = { title = "Shortsleeved Doublet", description = "Is that a slightly worn doublet for me!", objectives = "" }
WordHunterWoW_QuestEN[62173] = { title = "Long Sleeved Doublet", description = "<Your dredger reaches out enthusiastically for the long sleeved doublet.>", objectives = "" }
WordHunterWoW_QuestEN[62174] = { title = "A Proper Cover", description = "<Your dredger butler eyes you as if not sure if you are giving him the coif, or just asking him to hold it for you.>", objectives = "" }
WordHunterWoW_QuestEN[62175] = { title = "Looking Fabulous", description = "Who is this? Oh, look at those flowing locks...", objectives = "" }
WordHunterWoW_QuestEN[62176] = { title = "The Spikey Look", description = "That creature has a very distinct look...", objectives = "" }
WordHunterWoW_QuestEN[62177] = { title = "A Memorable Look", description = "Oh, I have seen this dredger before!", objectives = "" }
WordHunterWoW_QuestEN[62178] = { title = "Black Muck Dye", description = "Another muck dye!", objectives = "" }
WordHunterWoW_QuestEN[62179] = { title = "Blue Muck Dye", description = "Isn't muck so versatile!", objectives = "" }
WordHunterWoW_QuestEN[62180] = { title = "Green Muck Dye", description = "There are so many muck colors, how do you choose just one?", objectives = "" }
WordHunterWoW_QuestEN[62181] = { title = "Bubbling Red Muck Dye", description = "Is that one still bubbling?", objectives = "" }
WordHunterWoW_QuestEN[62185] = { title = "Fighting for Attention", description = "Maintaining a watchful eye on the Cult of the Damned has proven challenging... and perilous.\n\nSeveral of our hippogryph riders recently ran afoul of the cult's winged terrors. Though a few were able to escape, the others were captured and brought to Aldur'thar.\n\nDo what you can to free them from their captors. We cannot afford to lose any more of our forces.", objectives = "" }
WordHunterWoW_QuestEN[62186] = { title = "Swollen Anima Seed", description = "The masked sylvar set aside a single seed laden with anima; for what purpose, you can only imagine. Droman Tashmur would appreciate the return of such a precious resource.", objectives = "" }
WordHunterWoW_QuestEN[62187] = { title = "Satchel of Culexwood", description = "This lost satchel is filled with wood given by the nearby Culex trees. Fluttercatch would surely appreciate its return.", objectives = "" }
WordHunterWoW_QuestEN[62188] = { title = "Catch A Star", description = "I require your aid on a... delicate matter, {name}.\n\nStarfly Wings form a vital ingredient for some of our creations and our supply is exhausted.\nThey are tiny things, very fragile, and I am ill able to handle them delicately.\n\nCould you obtain the Starflies for me? They must be caught alive in order for their wings to not spoil and we desperately need them. \n\nI'll ensure that you are compensated for your time, of course.", objectives = "" }
WordHunterWoW_QuestEN[62189] = { title = "Parasol Components", description = "Sheets of fine cloth, wooden parasol ribs, wooden dowels and metal braces, everything you would need to put together new parasols. These are worth a lot of gold in the Ember Ward. Mats would certainly reward you handsomely if you brought him this cache.", objectives = "" }
WordHunterWoW_QuestEN[62190] = { title = "It's a Dirty Job", description = "We gotta fix up this muck pool before we go makin' that dredger butler of yours.\n\nLooks like the anima shortage caused all sorts of problems for this pool.\n\nThem muck pools gotta have plenty of filth and fiber in 'em to grow good dredgers.\n\nBut between them devourers and nasty elementals formin' from all that wild muck, I can't get close enough to feed it!\n\nHelp me out and throw some of that filthy rubble into the pool, yeah?", objectives = "" }
WordHunterWoW_QuestEN[62194] = { title = "Fighting Words", description = "Throughout the Shadowlands, there is so much magic to learn!\n\nA threat in Bastion has put many of their ancient teachings in danger. I wish to study their scrolls before they are lost forever. We must travel there and safeguard what we can!\n\nHelp me fight back the Forsworn at the Temple of Humility and save the scrolls within.", objectives = "" }
WordHunterWoW_QuestEN[62195] = { title = "The Last Word", description = "Inquisitor Darksion was an aspiring practitioner of the arcane arts before Denathrius locked her away.\n\nI've heard she will share her knowledge with anyone that releases her from imprisonment.\n\nI want to learn all she knows! We must free her!", objectives = "" }
WordHunterWoW_QuestEN[62205] = { title = "Venthyr Ettiquette", description = "Is that Theotar's new book?", objectives = "" }
WordHunterWoW_QuestEN[62206] = { title = "Ardenweald Etiquette", description = "Ooh, I am beginning to like these books.", objectives = "" }
WordHunterWoW_QuestEN[62207] = { title = "Bastion Etiquette", description = "That looks like a 'big' book.", objectives = "" }
WordHunterWoW_QuestEN[62208] = { title = "Maldraxxi Protocols", description = "It looks shorter than the others, but... are those bullets?", objectives = "" }
WordHunterWoW_QuestEN[62213] = { title = "A Brokered Deal", description = "Hey, {name}. I've found a lucrative business proposition that'll help me... us... greatly! See, Au'narim is willing to give us supplies if we can help him recover from a trade deal that went sideways.\n\nApparently, several of his cohorts never returned from a job. He needs us to follow their path and recover the item they failed to deliver. Simple, right?\n\nTo ensure we don't have any mishaps, I've taken the liberty of acquiring a few items that may be of help to us.\n\nSo, you in?", objectives = "" }
WordHunterWoW_QuestEN[62214] = { title = "Forces of Perdition", description = "Survival requires that we keep our enemies in check, Maw Walker.\n\nWith Gorgoa overflowing, the Mawsworn continue to gain strength.\n\nPerdition Hold has been fortified with fresh troops. We cannot allow the Mawsworn to bolster their ranks any further.\n\nMake your way into Perdition Hold and decimate their forces. When the work is done, you may return to me for your reward.", objectives = "" }
WordHunterWoW_QuestEN[62216] = { title = "Training Program", description = "Sergeant Krashj is an adequate drill master, but these recruits need proper training with a real warrior. Someone who has been bloodied on the battlefield. Someone like me!\n\nAnd I know just the fight that will whip these troops into shape.\n\nLet's go teach them a thing or three.", objectives = "" }
WordHunterWoW_QuestEN[62217] = { title = "Field Training", description = "Though it was not by our hand, Maldraxxus has dealt a great injustice to the kyrian of Bastion. We must do all that we can to make amends.\n\nThe Forsworn menace continues to be a thorn in their side. Sounds like the perfect opportunity to both show our support and for our recruits to gain some combat experience.", objectives = "" }
WordHunterWoW_QuestEN[62218] = { title = "A Fountain for Fae", description = "Nuuminuuru spends their days protecting and taking care of many faeries throughout Ardenweald. They have expressed concern about some faeries in their care whom they have not seen in some time.\n\nReport to Nuuminuuru and see if you can help them find their scattered sprites.", objectives = "" }
WordHunterWoW_QuestEN[62219] = { title = "Fanciful Distractions", description = "Ever chasing their fleets of fancy, my faerie friends are seldom seen.\n\nTheir mercurial natures oft lead them astray, tracing them paths to distraction and dismay.\n\nSeek my friends, insist they return to my roots, and both you and they may receive recompense.", objectives = "" }
WordHunterWoW_QuestEN[62221] = { title = "My Own Death Pony!", description = "That is such a beautiful death pony, ever since I saw my first one I have dreamed of ...", objectives = "" }
WordHunterWoW_QuestEN[62222] = { title = "On Silver Wings", description = "What do you intend for me to do with that thing?", objectives = "" }
WordHunterWoW_QuestEN[62223] = { title = "Ascension Calling: Mikanikos", description = "<While this scroll mimics Kleia's invitation to the Path of Ascension, it is very clearly written in Sika's hand.\n\nIt details an invitation for Mikanikos to participate in the Path, along with Bron.\n\nPerhaps you should bring this to Mikanikos.>", objectives = "" }
WordHunterWoW_QuestEN[62224] = { title = "A Thread Of Hope", description = "The Court of Night is akin to a thirsty flower, it quickly draws up its nutrients. If well supplied it will bloom and if its supply is depleted, it withers.\n\nOur roots are beginning to dry, we need more anima!\n\nI've sent workers out to place silk lined catchers along the roads and paths that cross Ardenweald. These catchers will collect a tiny bit of anima, not much but enough for what we need.\n\nSeek them out and return the Anima Infused Silk to us.", objectives = "" }
WordHunterWoW_QuestEN[62225] = { title = "Bursting the Bubble", description = "<The words of the shadowy herald are dark and foreboding. Whatever \"the Banished One\" intends to accomplish, it must not come to pass.\n\nSomething foul bubbles within the cauldrons nearby. Judging by the care with which the cultists are tending to them, their contents must be crucial to their plans.\n\nSeveral barrels containing what appears to be a new type of plague have been left unattended. Perhaps they can serve as instruments for sabotage.>", objectives = "" }
WordHunterWoW_QuestEN[62232] = { title = "Arboreal Tactics", description = "The spriggan of Ardenweald have always been a nuisance. But under Mueh'zala's influence, they could grow into a threat that looms over all of the Shadowlands.\n\nLet's test these troops against a real opponent.", objectives = "" }
WordHunterWoW_QuestEN[62234] = { title = "Power of the Colossus", description = "I have another task for you, Maw Walker.\n\nDeep within Perdition Hold, there lurks a menacing mechanization known as the Soulsteel Colossus. It must be destroyed before it wreaks havoc upon us.\n\nTravel to the Hold, and then across the bridge into the Altar of Domination. There, casting its vast shadow upon The Maw, you will find the Soulsteel Colossus.\n\nShatter the colossus and bring me its power source as proof of your victory.", objectives = "" }
WordHunterWoW_QuestEN[62237] = { title = "Mysterious Soul Mirror", description = "<A shimmering soul mirror draws your attention on Devos's corpse.\n\nPeculiar that she would keep one on her person. Perhaps Thenios will want to see this.>", objectives = "" }
WordHunterWoW_QuestEN[62238] = { title = "Soul Led Astray", description = "Uther was a being of justice on your world. I am sure it was quite surprising for you to see his fate here, following a leader who embodies what he stood against in life.\n\nI believe you should witness this memory firsthand. Take it to my soul mirror. View the memories within.", objectives = "" }
WordHunterWoW_QuestEN[62239] = { title = "Rodent Removal", description = "<The weapon buzzes with a dark, static energy. Whatever this Mawsworn was testing, it appears to have been somewhat successful on the nearby rodents.\n\nFurther investigation may yield additional information.>", objectives = "" }
WordHunterWoW_QuestEN[62244] = { title = "Digging Around", description = "The thin pale ones of Revendreth have been hoarding anima. \n\nI've heard they've been hiding it away, digging holes in the woods and just leaving it there. Anyone could come along and take it.\n\nI say that should be us!\n\nLet's go get some anima.", objectives = "" }
WordHunterWoW_QuestEN[62246] = { title = "A Fallen Friend", description = "A bracelet delicately woven with living vines falls from Vivanna's wrist as she is slain. In the vines is written, \n\n\"Until Winter's end.\n\n-Flwngyrr\"", objectives = "" }
WordHunterWoW_QuestEN[62250] = { title = "A New Adventure Awaits", description = "{name}! You're needed in the present. Things have... well, you should just come back to see.\n\nI would finish what you're doing then head back. I can't keep you in the past for much longer!", objectives = "" }
WordHunterWoW_QuestEN[62256] = { title = "Asset Extraction", description = "Hey, it's my good pal {name}! Listen, I'm in a bit of a bind here. I've been trying to negotiate a deal with the broker Au'larrynar and he needs a little something, a job done before he'll accept.\n\nThe deal is he had an associate who went missing with a rare item. He's asked that I... we... locate and return the missing property.\n\nThe associate was last seen in Ardenweald. I know, strange place, way too bright for me. But, I... we... really need this deal to go through! \n\nSo, you ready to go?", objectives = "" }
WordHunterWoW_QuestEN[62259] = { title = "Anima-Laden Dreamcatcher", description = "You stumble upon an enchanted dreamcatcher, placed so remotely that it has managed to collect a significant amount of anima without being harvested. Droman Dawnblossom in nearby Dreamsong Fenn would surely appreciate its safe return.", objectives = "" }
WordHunterWoW_QuestEN[62261] = { title = "Grinder", description = "It's tough keeping these hands of mine razor sharp. With all the hacking and cleaving, they can grow dull so quickly! What's a girl to do?\n\nThe House of the Chosen makes some very fine quality sharpening stones. I doubt they will just hand them over, but I'm sure my blades can persuade them otherwise.\n\nHow about we pay them a visit and see how many stones they can spare?", objectives = "" }
WordHunterWoW_QuestEN[62262] = { title = "Fungal Feeding", description = "Just as I was making progress on our alternative defense research, my spore samples ran dry!\n\nThe mushrooms I was using can only be found in a particularly unpleasant location to the southeast. To collect an appropriately sized sample, you'll have to--how do I put this--feed them. \n\nDon't ask me why, but apparently, they mature fastest with a nice, rotting corpse nearby.\n\nTry luring a few undead to our fungal friends. That should give 'em all the nutrients they need to grow big and strong.", objectives = "" }
WordHunterWoW_QuestEN[62263] = { title = "Go Beyond!", description = "Ah, you're just in time. I've made quite the discovery.\n\nI've managed to make a connection even further out than I ever have before.\n\nHow did I do it, you ask? Hard work, that's how! But you knew that. You're almost as hardworking as I am. That's what you're here for!\n\nUp for an even more exciting adventure?", objectives = "" }
WordHunterWoW_QuestEN[62265] = { title = "A New Adventure Awaits", description = "{name}! You're needed in the present. Things have... well, you should just come back to see.\n\nI would finish what you're doing then head back. I can't keep you in the past for much longer!", objectives = "" }
WordHunterWoW_QuestEN[62275] = { title = "Bastion", description = "After being set back by a surprise attack by Maldraxxus forces and an army of their own fallen kin known as the Forsworn, the Ascended stand to lose control of Bastion if they are not given aid.", objectives = "" }
WordHunterWoW_QuestEN[62276] = { title = "Drink to the Dead", description = "The Forsworn are ravaging the temples of Bastion, and the aspirants are leaving behind their supplies as they flee.\n\nAll those wonderful bottles of nectar falling into the hands of the Forsworn? I think not! \n\nThere's no way we can save all of the aspirants, but we can keep the Forsworn from taking those supplies. Besides... we could all use something to drink around here.", objectives = "" }
WordHunterWoW_QuestEN[62277] = { title = "Ardenweald", description = "Ardenweald still faces threats from the Drust, as well as other nefarious forces.\n\nThe Winter Queen could use your aid in fending off the forces that seek to destroy Ardenweald.", objectives = "" }
WordHunterWoW_QuestEN[62278] = { title = "Maldraxxus", description = "With the houses in shambles, the loyal army of the Primus struggles to hold their ground in Maldraxxus.\n\nThey need help to tip the scales in their favor.", objectives = "" }
WordHunterWoW_QuestEN[62279] = { title = "Revendreth", description = "Chaos rules Revendreth in the wake of Sire Denathrius's betrayal. \n\nThey are in dire need of your aid!", objectives = "" }
WordHunterWoW_QuestEN[62289] = { title = "Observing Conflict", description = "Your kind seems to lead an inherently contentious existence, mortal. Members of my cartel have a keen interest in observing your combat prowess in action.\n\nIt is apparent that conflicts between you and your rivals can break out anywhere, even in the realms of Death. Much could be learned from observing such engagements.\n\nCan I count on your participation?", objectives = "" }
WordHunterWoW_QuestEN[62294] = { title = "One Lich's Trash...", description = "It is said that one person's trash, is another's treasure. When it comes to relics, the adage is particularly true.\n\nThe House of Rituals is notoriously secretive, which means any knowledge we can glean from them will be all the sweeter.\n\nIf we sift through their detritus, I'm sure there are all sorts of treasures we will find.", objectives = "" }
WordHunterWoW_QuestEN[62295] = { title = "Cleaning Out the Vault", description = "The Scourge's rampant aggression has proven difficult to predict, even for us.\n\nBy the time we knew they were upon us, it was too late.\n\nWith our forces spread thin, we are left with what you see before you.\n\nEnter the vault. Slay our enemies where they stand.\n\nSoon the Shadow Vault will be ours once more.", objectives = "" }
WordHunterWoW_QuestEN[62296] = { title = "Into the Unknown", description = "Come to pay old Marasmius a visit? I have a special task for you.\n\nOne of my shoots has found a strange place, a place even I've never seen before.\n\nI'm not entirely sure what's in there or if it's even safe. But that's what my trusty mushroomancers are for!\n\nWhat do you say, {name}? Up for an adventure?", objectives = "" }
WordHunterWoW_QuestEN[62297] = { title = "A Fatal Failure", description = "Acolyte, we could use a hand here!\n\nIt seems one of your fellow pupils botched their ritual in spectacular fashion. Now destructive necromantic energies are running rampant throughout the house.\n\nThis threat must be dealt with. Can you assist?", objectives = "" }
WordHunterWoW_QuestEN[62298] = { title = "Classic 20-49", description = "", objectives = "" }
WordHunterWoW_QuestEN[62301] = { title = "Classic 50", description = "", objectives = "" }
WordHunterWoW_QuestEN[62304] = { title = "Round 1", description = "", objectives = "" }
WordHunterWoW_QuestEN[62305] = { title = "Round 2", description = "", objectives = "" }
WordHunterWoW_QuestEN[62307] = { title = "Round 3", description = "", objectives = "" }
WordHunterWoW_QuestEN[62308] = { title = "Mantle of Mastery", description = "You have done much to establish yourself as a promising acolyte. Your superiors have made it known that you are ready to be tested for your ritualist's mantle. \n\nWhen you are ready, begin the Ritual of Ancient Summoning to call forth an elder spirit of Maldraxxus. Conquer the spirit, and prove your mettle!", objectives = "" }
WordHunterWoW_QuestEN[62309] = { title = "Adventurer: Secutor Mevix", description = "", objectives = "" }
WordHunterWoW_QuestEN[62312] = { title = "Adventurer: Gunn Gorgebone", description = "", objectives = "" }
WordHunterWoW_QuestEN[62313] = { title = "Adventurer: Rencissa the Dynamo", description = "", objectives = "" }
WordHunterWoW_QuestEN[62314] = { title = "Adventurer: Khaliiq", description = "", objectives = "" }
WordHunterWoW_QuestEN[62315] = { title = "Adventurer: Plaguey", description = "", objectives = "" }
WordHunterWoW_QuestEN[62316] = { title = "Adventurer: Rathan", description = "", objectives = "" }
WordHunterWoW_QuestEN[62317] = { title = "Casting Doubt", description = "<A note has been left here for Kel'Thuzad. It does not appear that he has read it.>\n\nBaron, I do not trust your new favorite acolyte. Something has been off about them ever since they returned from their ritual with the Kyrian remains.\n\nYour work is too important to allow such discrepancies. The acolyte should be disposed of.\n\nFaithfully,\n\nSorcerer Vutral", objectives = "" }
WordHunterWoW_QuestEN[62320] = { title = "Regalia de Rigueur", description = "Ah, if it isn't Kel'Thuzad's favorite acolyte? I simply cannot understand how a baron like him would surround himself with such... homely company.\n\nWhen was the last time you even chanced at a looking glass? Those faded robes do your station no justice.\n\nI would take it upon myself to update your drab apparel, if I weren't sufferring such a shortage on the house's preferred amethystine tint.\n\nYou could always fetch some yourself. The sorcerers usually have some stashed among their tomes and altars.", objectives = "" }
WordHunterWoW_QuestEN[62321] = { title = "Round 1", description = "", objectives = "" }
WordHunterWoW_QuestEN[62322] = { title = "Round 2", description = "", objectives = "" }
WordHunterWoW_QuestEN[62323] = { title = "Round 3", description = "", objectives = "" }
WordHunterWoW_QuestEN[62324] = { title = "Round 1", description = "", objectives = "" }
WordHunterWoW_QuestEN[62325] = { title = "Round 2", description = "", objectives = "" }
WordHunterWoW_QuestEN[62347] = { title = "Shadowlands (50-59) E", description = "", objectives = "" }
WordHunterWoW_QuestEN[62353] = { title = "Shadowlands (50-59) E", description = "", objectives = "" }
WordHunterWoW_QuestEN[62359] = { title = "Shadowlands (50-59) E", description = "", objectives = "" }
WordHunterWoW_QuestEN[62361] = { title = "Introductions are in Order", description = "Now yous is all set with yer new dredger, go ahead call on them and officially introduce yerself.", objectives = "" }
WordHunterWoW_QuestEN[62362] = { title = "Volatile Reactions", description = "The living slime within Maldraxxus naturally produces a powerful catalyst used in many of the House of Eyes's poisons. There is always a need for the substance.\n\nIt would be of great help if you could retrieve some for us.", objectives = "" }
WordHunterWoW_QuestEN[62363] = { title = "Heavy Lifting", description = "The stronger members of the House of the Chosen tend to take a fairly specific form. No doubt you've seen the larger warriors in the house?\n\nThey are the greatest threat in their collective force. Thin them out.", objectives = "" }
WordHunterWoW_QuestEN[62364] = { title = "Dire Learning", description = "Necromancers and liches often use powerful tomes to assist in their rituals. Now that the House of Rituals has expanded their reach, the tomes can be found anywhere where their members are active.\n\nFind these books and destroy them. It won't end their vile experiments but it should at least delay them.", objectives = "" }
WordHunterWoW_QuestEN[62365] = { title = "Careful Creations", description = "What better way to stop our enemies in their tracks than to use their own experiments against them?\n\nLucky for us, some of our... friends have left a few samples unattended. And I know just where to test it...\n\nAs menacing as they may be, those abominations down there are delicate creations.\n\nIt would be a shame if you were to get your hands on some of their equipment and disrupt the process...", objectives = "" }
WordHunterWoW_QuestEN[62366] = { title = "Round 3", description = "", objectives = "" }
WordHunterWoW_QuestEN[62367] = { title = "Round 1", description = "", objectives = "" }
WordHunterWoW_QuestEN[62368] = { title = "Rebuild Our Trust", description = "Well {name}, it seems you are serious about earning your way back into our good graces.\n\nIt seems you are serious about this penance. This task should prove your willingness to rejoin our ranks.", objectives = "" }
WordHunterWoW_QuestEN[62371] = { title = "Tirna Scithe: A Warning Silence", description = "The songs of Tirna Scithe have faded as the grove wanes, yet there is now silence. Droman Oulfarran's voice has not been heard in some time. The trees whisper of penumbral shadows, discordant songs, and dying roots. All is not well.\n\nFriend of Ardenweald, travel to Root-home. Delve into the Mists. Remove that which threatens us.", objectives = "" }
WordHunterWoW_QuestEN[62373] = { title = "Round 2", description = "", objectives = "" }
WordHunterWoW_QuestEN[62374] = { title = "Round 3", description = "", objectives = "" }
WordHunterWoW_QuestEN[62382] = { title = "Into the Unknown", description = "Come to pay old Marasmius a visit? I have a special task for you.\n\nOne of my shoots has found a strange place, a place even I've never seen before.\n\nI'm not entirely sure what's in there or if it's even safe. But that's what my trusty mushroomancers are for!\n\nWhat do you say, {name}? Up for an adventure?", objectives = "" }
WordHunterWoW_QuestEN[62385] = { title = "Round 1", description = "", objectives = "" }
WordHunterWoW_QuestEN[62386] = { title = "Round 2", description = "", objectives = "" }
WordHunterWoW_QuestEN[62387] = { title = "Round 3", description = "", objectives = "" }
WordHunterWoW_QuestEN[62388] = { title = "House of Rituals", description = "The Ritualists are the ones behind this war. Every act of treason has been committed under their orders.\n\nWe cannot defeat their sorcery with strength of arms alone. Victory will hinge on our knowledge of what they are plotting.\n\nContinue to bolster our forces. I will look for a way to infiltrate the House of Rituals.", objectives = "" }
WordHunterWoW_QuestEN[62389] = { title = "Rebuild Our Trust", description = "So you have taken the first step to reclaiming our trust.\n\nNow you must prove that was not another false start in our relationship. \n\nThis final task should prove your willingness to rejoin our ranks.", objectives = "" }
WordHunterWoW_QuestEN[62390] = { title = "Body Count", description = "I am acquainted with a few fleshcrafters who work outside of the House of Constructs. If we can find reagents for them, they can supply our war effort with constructs.\n\nThe House of Constructs has plenty of excess body parts. Find them and bring them back here.", objectives = "" }
WordHunterWoW_QuestEN[62391] = { title = "Mobilize Maldraxxus", description = "It will be difficult to reach Kel'Thuzad while he is in his necropolis.\n\nGo now. It will take time for us to muster an army that can pierce his defenses.", objectives = "" }
WordHunterWoW_QuestEN[62392] = { title = "Rebuild Our Trust", description = "You return as requested. Impressive, maybe you have indeed turned a new leaf.\n\nI wish to see you complete one more task for us. To prove your dedication to this transition. \n\nNot that we doubt you, but you must understand your previous behavior gives us reason to doubt that dedication.", objectives = "" }
WordHunterWoW_QuestEN[62393] = { title = "Rebuild Our Trust", description = "You still have the same strength you had before it seems.\n\nThe question is - do you have any loyalty left within you?\n\nI have one more task so you can demonstrate that loyalty again.", objectives = "" }
WordHunterWoW_QuestEN[62394] = { title = "House In Decline", description = "Our forces are gathering.\n\nSoon it will be time to move against the House of Rituals.\n\nSee what you can do to continue strengthening our position.", objectives = "" }
WordHunterWoW_QuestEN[62400] = { title = "Go Beyond!", description = "Ah, you're just in time. I've made quite the discovery.\n\nI've managed to make a connection even further out than I ever have before.\n\nHow did I do it, you ask? Hard work, that's how! But you knew that. You're almost as hardworking as I am. That's what you're here for!\n\nUp for an even more exciting adventure?", objectives = "" }
WordHunterWoW_QuestEN[62401] = { title = "Strange Scourgestones", description = "The Lich King's minions once carried scourgestones given to them by their dark master. \n\nNew ones have been found on the corpses of the undead. We do not know their purpose... but they have been touched by even more sinister magic.\n\nAs you slay the Scourge across Icecrown, keep your eyes open for such stones. If you bring them back to me, I shall turn them over to the confessors for study.", objectives = "" }
WordHunterWoW_QuestEN[62402] = { title = "Timewalking Campaigns", description = "", objectives = "" }
WordHunterWoW_QuestEN[62403] = { title = "Boared to Death", description = "The boars around Maldraxxus have a peculiar trait. Their tusks absorb liquid. Depending on where it has been, these bones may contain a powerful compound of poisons or other alchemical rarities.\n\nIt takes a trained eye to tell what the bone is made of, so just bring back a large amount of them. From there I will see if any of them are valuable.", objectives = "" }
WordHunterWoW_QuestEN[62406] = { title = "Staff of the Primus", description = "The Staff of the Primus. The final piece of our leader's regalia.\n\nI can't deny the pride I feel in restoring this hall. You should feel the same sense of accomplishment.\n\nThe statue awaits you, {name}. Bring glory to this realm.", objectives = "" }
WordHunterWoW_QuestEN[62407] = { title = "Herbicidal Tendencies", description = "My gas is the most potent in all of Maldraxxus, but I've heard some of the others saying that it's not the strongest in the Shadowlands. \n\nThey claim there are some plants in Ardenweald with a bloom that is far more pungent than my gas. Nonsense!\n\nLet's go and check these plants out. If their stench is as strong as the stories claim, I might even be able to mix them in with my own gas!", objectives = "" }
WordHunterWoW_QuestEN[62414] = { title = "Burying Suspicion", description = "It will do us no good to disguise yourself as Nelesis if word reaches Kel'Thuzad that she was slain. \n\nYou must ensure that no one who sees you enter the cave survives.", objectives = "" }
WordHunterWoW_QuestEN[62417] = { title = "Go Beyond!", description = "Ah, you're just in time. I've made quite the discovery.\n\nI've managed to make a connection even further out than I ever have before.\n\nHow did I do it, you ask? Hard work, that's how! But you knew that. You're almost as hardworking as I am. That's what you're here for!\n\nUp for an even more exciting adventure?", objectives = "" }
WordHunterWoW_QuestEN[62420] = { title = "Snapper Soul", description = "<The Snapper Soul is determined. The shape of the dragon turtle will be yours to call upon.>", objectives = "" }
WordHunterWoW_QuestEN[62421] = { title = "Gulper Soul", description = "<The Gulper Soul is patient and calm. The shape of the Gulper will be yours to call upon.>", objectives = "" }
WordHunterWoW_QuestEN[62422] = { title = "Ardenmoth Soul", description = "<The Ardenmoth is plentiful in Ardenweald. Delicate looking creatures, they have hidden strength. Their magic can soothe the most tortured soul... or send the unwary into an eternal sleep. The shape of the moth will be yours to call upon.>", objectives = "" }
WordHunterWoW_QuestEN[62423] = { title = "Ursine Soul", description = "<The Ursine Soul is stalwart and brave. The shape of the bear will be yours to call upon.>", objectives = "" }
WordHunterWoW_QuestEN[62424] = { title = "Crane Soul", description = "<The Crane Soul dances with grace. The shape of the crane will be yours to call upon.>", objectives = "" }
WordHunterWoW_QuestEN[62425] = { title = "Veilwing Soul", description = "<Graceful, dangerous, powerful. No creature in Ardenweald is more respected for its fierce defense of its family or territory than the veilwing. \n\nYou have defeated a foe who endangered not only Ardenweald, but all of the Shadowlands. For this, Champion of Ardenweald, you have earned a special boon - the ability to call upon the essence of the veilwing and take their shape.>", objectives = "" }
WordHunterWoW_QuestEN[62426] = { title = "Gryphon Soul", description = "<The Gryphon Soul is agile and swift. The shape of the gryphon will be yours to call upon.>", objectives = "" }
WordHunterWoW_QuestEN[62427] = { title = "Hippogryph Soul", description = "<The Hippogryph Soul is intelligent and valiant. The shape of the hippogryph will be yours to call upon.>", objectives = "" }
WordHunterWoW_QuestEN[62428] = { title = "Equine Soul", description = "<The Equine Soul is free-spirited and loyal. The shape of a horned horse will be yours to call upon.>", objectives = "" }
WordHunterWoW_QuestEN[62429] = { title = "Leonine Soul", description = "<The Leonine sine Soul is powerful and brave. The shape of the lion will be yours to call upon.>", objectives = "" }
WordHunterWoW_QuestEN[62430] = { title = "Moose Soul", description = "<The Moose Soul endures and protects. The shape of the moose will be yours to call upon.>", objectives = "" }
WordHunterWoW_QuestEN[62431] = { title = "Shadowstalker Soul", description = "<The Shadowstalker Soul is cunning and careful. The shape of the Shadowstalker will be yours to call upon.>", objectives = "" }
WordHunterWoW_QuestEN[62432] = { title = "Owlcat Soul", description = "<The Owlcat Soul is a curious trickster, a beast of many parts working together in a playful balance, always seeking the next challenge. The shape of the owlcat will be yours to call upon.>", objectives = "" }
WordHunterWoW_QuestEN[62433] = { title = "Raptor Soul", description = "<The Raptor Soul is loyal and fierce. The shape of the raptor will be yours to call upon.>", objectives = "" }
WordHunterWoW_QuestEN[62434] = { title = "Runestag Soul", description = "<The Runestag Soul is calm and enduring. The shape of the Runestag will be yours to call upon.>", objectives = "" }
WordHunterWoW_QuestEN[62435] = { title = "Stag Soul", description = "<The Stag Soul is noble and mighty. The shape of the stag will be yours to call upon.>", objectives = "" }
WordHunterWoW_QuestEN[62436] = { title = "Shrieker Soul", description = "<The Shrieker Soul is swift and fierce. The shape of the veil shrieker will be yours to call upon.>", objectives = "" }
WordHunterWoW_QuestEN[62437] = { title = "Tiger Soul", description = "<The Tiger Soul is proud and strong. The shape of the tiger will be yours to call upon.>", objectives = "" }
WordHunterWoW_QuestEN[62438] = { title = "Lupine Soul", description = "<The Lupine Soul is a fierce and free-spirited protector. The shape of the wolf will be yours to call upon.>", objectives = "" }
WordHunterWoW_QuestEN[62439] = { title = "Wolfhawk Soul", description = "<The Wolfhawk Soul is cunning hunter. The shape of the wolfhawk will be yours to call upon.>", objectives = "" }
WordHunterWoW_QuestEN[62440] = { title = "Wyvern Soul", description = "<The Wyvern Soul is proud and determined. The shape of the wyvern will be yours to call upon.>", objectives = "" }
WordHunterWoW_QuestEN[62441] = { title = "Fair Exchange for a Soul", description = "While we work away here in the Conservatory, we must not forget to support the rest of the covenant.\n\nI am needed here, but you can range far, even though your legs are short. \n\nPlease, help our covenant recover the anima we need. I can then dedicate my time to preparing another spirit for you to restore.", objectives = "" }
WordHunterWoW_QuestEN[62442] = { title = "Aid the Covenant", description = "I hear amazing things about the realm beyond this garden, but honestly I am too old to wish to place myself in danger.\n\nYou are young and vibrant! Head out across the realm, and return to me with the stories of your adventures!.", objectives = "" }
WordHunterWoW_QuestEN[62443] = { title = "Aid the Covenant", description = "I hear amazing things about the realm beyond this garden, but honestly I am too old to wish to place myself in danger.\n\nYou are young and vibrant! Head out across the realm, and return to me with the stories of your adventures!.", objectives = "" }
WordHunterWoW_QuestEN[62444] = { title = "Aid the Covenant", description = "I hear amazing things about the realm beyond this garden, but honestly I am too old to wish to place myself in danger.\n\nYou are young and vibrant! Head out across the realm, and return to me with the stories of your adventures!", objectives = "" }
WordHunterWoW_QuestEN[62445] = { title = "A Spirit's Pride", description = "I seek to understand more about the prideful beings in this realm.\n\nIf you could place one in a wildseed, as you did for me, I could observe the restoration process.", objectives = "" }
WordHunterWoW_QuestEN[62447] = { title = "A Rare and Unusual Spirit", description = "I have a mystery for you, {name}!\n\nWho doesn't savor a good mystery? \n\nWe have found a spirit unlike any other, one who does not respond to being placed in a wildseed.\n\nEach of us who touched it experienced a dream in which we saw you battling a great beast. Only when you defeated it did the spirit begin on its path to rebirth. \n\nWe think we know the beast.\n\nAre you up for discovering if these dreams were a portent?", objectives = "" }
WordHunterWoW_QuestEN[62448] = { title = "Securing the House", description = "Your journey into the Maw was impressive, but it will take even more phenomenal feats to earn the loyalty of the Maldraxxi.\n\nIncrease your renown among our ranks, Maw Walker. The Maldraxxi are dedicated soldiers, but they will not follow just anyone into battle. Let your deeds prove your worth to them.", objectives = "" }
WordHunterWoW_QuestEN[62449] = { title = "A Spirit's Duty", description = "I seek to understand more about the Dutiful beings in this realm.\n\nIf you could place one in a wildseed, as you did for me, I could observe the restoration process.", objectives = "" }
WordHunterWoW_QuestEN[62450] = { title = "A Spirit's Heart", description = "I seek to understand more about the Untamed beings in this realm.\n\nIf you could place one in a wildseed, as you did for me, I could observe the restoration process.", objectives = "" }
WordHunterWoW_QuestEN[62452] = { title = "A Spirit's Might", description = "I seek to understand more about the Martial beings in this realm.\n\nIf you could place one in a wildseed, as you did for me, I could observe the restoration process.", objectives = "" }
WordHunterWoW_QuestEN[62453] = { title = "Into the Unknown", description = "Come to pay old Marasmius a visit? I have a special task for you.\n\nOne of my shoots has found a strange place, a place even I've never seen before.\n\nI'm not entirely sure what's in there or if it's even safe. But that's what my trusty mushroomancers are for!\n\nWhat do you say, {name}? Up for an adventure?", objectives = "" }
WordHunterWoW_QuestEN[62454] = { title = "A Rare and Unusual Spirit", description = "I awaken. I exist once more. And yet...\n\nThere is an emptiness within. A lingering tether to a home that no longer exists. So much wonder... so much splendor... lost.\n\nNow I have no purpose. No fate. No path.\n\nWill you teach me of this place, awakener? I sense there is much to be understood. Many secrets. Many truths.\n\nIn so doing, perhaps a new fate will emerge.", objectives = "" }
WordHunterWoW_QuestEN[62456] = { title = "De Other Side: Dealin' Wit' Da Boss", description = "Ay, mon. Long time no see!\n\nI be havin' a bit of trouble wit' me boss, Mueh'zala. Now, now... don't you worry. Your ol' friend Bwonsamdi got dis whole ting under control!\n\nI just be needin' some help gatherin' me mojo back from a few ungrateful business partners.\n\nYou bring me da mojo, and we goin' ta take care of ol' Mueh'zala once and for all!", objectives = "" }
WordHunterWoW_QuestEN[62458] = { title = "De Other Side", description = "Ay, dere {name}! Ya be just da {class} I've been lookin' for!\n\nIt be your ol' pal Bwonsamdi reachin' out ta ya from De Other Side! I be havin' a little problem over here wit' de boss...\n\nYa be lookin' mighty bored just standin' around here in Ardenweald. Why don't ya come to De Other Side and help out an ol' friend? Bwonsamdi promise he gonna make it worth ya while!\n\nYa might want ta bring a few more adventurers wit' ya... just ta be safe.", objectives = "" }
WordHunterWoW_QuestEN[62459] = { title = "Go Beyond!", description = "Ah, you're just in time. I've made quite the discovery.\n\nI've managed to make a connection even further out than I ever have before.\n\nHow did I do it, you ask? Hard work, that's how! But you knew that. You're almost as hardworking as I am. That's what you're here for!\n\nUp for an even more exciting adventure?", objectives = "" }
WordHunterWoW_QuestEN[62461] = { title = "Stalking the Warrens", description = "So, they are creating magical beasts deep within the Warrens. Their power is... substantial.\n\nMaw Walker, I must trust in you to handle this. While I can provide insight, in combat I must admit your prowess exceeds my own.\n\nHunt the beasts that they train to hunt us. Show the Mawsworn that we too can bare fangs.", objectives = "" }
WordHunterWoW_QuestEN[62462] = { title = "WANTED: The Key of Eyes", description = "I seek a mercenary of unparalleled might to venture into the House of Eyes and procure the \"Key of Eyes\".\n\nAbove average compensation is assured for the one who can both deliver the key and regale me with the story of its previous owner's demise. \n\nBe warned that the grounds once belonging to the House of Eyes are extremely dangerous and lone exploration is highly discouraged.", objectives = "" }
WordHunterWoW_QuestEN[62465] = { title = "Go Beyond!", description = "Ah, you're just in time. I've made quite the discovery.\n\nI've managed to make a connection even further out than I ever have before.\n\nHow did I do it, you ask? Hard work, that's how! But you knew that. You're almost as hardworking as I am. That's what you're here for!\n\nUp for an even more exciting adventure?", objectives = "" }
WordHunterWoW_QuestEN[62466] = { title = "Go Beyond!", description = "Ah, you're just in time. I've made quite the discovery.\n\nI've managed to make a connection even further out than I ever have before.\n\nHow did I do it, you ask? Hard work, that's how! But you knew that. You're almost as hardworking as I am. That's what you're here for!\n\nUp for an even more exciting adventure?", objectives = "" }
WordHunterWoW_QuestEN[62467] = { title = "Seed of a Thought", description = "Within wildseeds, spirits slumber and grow. But so too can catalysts, when seeds take the place of spirits.\n\nSeed Merchant Daybreak trades in such seeds. She can supply you with the ones you seek. Choose one to plant within a wildseed.\n\nThe forest holds its breath and awaits your choice.", objectives = "" }
WordHunterWoW_QuestEN[62473] = { title = "What's Old is New", description = "These damn Scourge make me sick!\n\n<Brollen spits on the ground.>\n\nThey're only good fer one thing--bein' dead!\n\nHead tae the valley southwest o' here. Plenty o' gear fer the pickin' over there!\n\nGather up what ye can. I'll make do with what ye find.", objectives = "" }
WordHunterWoW_QuestEN[62477] = { title = "Blueprint: Skystrider Glider", description = "<You have discovered plans for a single use glider, invented by Dresaelus.\n\nDactylis should be able to help you with crafting this kit.>", objectives = "" }
WordHunterWoW_QuestEN[62483] = { title = "Steward Mail Pouch", description = "<The pouch is well constructed, with plenty of room for scrolls and a division to keep letters flat. The stitching is clean, and the strap is adjustable to fit your steward's size.\n\nYou are certain your steward will love it.>", objectives = "" }
WordHunterWoW_QuestEN[62484] = { title = "Werk In Progress", description = "We received an... unusual delivery recently. I'm still in a bit of shock.\n\nSome sort of flying contraption released a huge crate just overhead, parachute and all. If it weren't for the wind it would have landed nearby. Instead, it drifted down the hill below.\n\nThey left a note too. It would have been lost had it not been wrapped around a sizeable rock.\n\n<Darkrider Arly massages a spot on her forehead.>\n\nI don't know what it is, but if it'll help clear out the area, I'm all for it.", objectives = "" }
WordHunterWoW_QuestEN[62486] = { title = "Blueprint: Empyrean Refreshment", description = "<You have discovered plans for a table of refreshing snacks that would be quite useful while out adventuring.\n\nDactylis should be able to help you with the crafting.>", objectives = "" }
WordHunterWoW_QuestEN[62536] = { title = "The Lost of Teldrassil", description = "I learned that Sylvanas burned Teldrassil. I felt my heart break for the night elves.\n\nAnd that was only the beginning. We know now that the souls lost that day did not go to their intended rest.\n\nBut you have the power to begin to correct that, Maw Walker.\n\nIf you find yourself in the Maw, look for any of those lost.\n\nPlease, bring them home.", objectives = "" }
WordHunterWoW_QuestEN[62544] = { title = "From a Dark Place", description = "You rescued some of the night elves from the Maw before. While the danger is still great, I must ask you to do it again.\n\nI have to believe that we can save them. As many of them as possible.\n\nPlease, go and see if you can recover any more lost souls.", objectives = "" }
WordHunterWoW_QuestEN[62546] = { title = "No Wisp Left Behind", description = "More of the Kaldorei souls still languish in the Maw.\n\nI ask you once again, Maw Walker, to find them.\n\nHelp correct this wrong.", objectives = "" }
WordHunterWoW_QuestEN[62549] = { title = "No Wisp Left Behind", description = "More of the Kaldorei souls still languish in the Maw.\n\nI ask you once again, Maw Walker, to find them.\n\nHelp correct this wrong.", objectives = "" }
WordHunterWoW_QuestEN[62553] = { title = "Delaying Their Efforts", description = "The Scourge continue to replenish their weapons of war from blighted grounds. Stopping their workers slows their production, but a decisive blow to their stockpiles would be far more effective.\n\nTake these and head to the area southeast of here. Plant the bombs, then make a quick exit.\n\nWeakening their supply lines should provide us ample time to retaliate.", objectives = "" }
WordHunterWoW_QuestEN[62555] = { title = "A Touch of Humility", description = "With the Temple of Humility under our control, its power shall flow back into the Crest of Ascension once more.\n\nJoin me below so that we may witness it together. Mikanikos has ensured it will become even more magnificent as its power grows.", objectives = "" }
WordHunterWoW_QuestEN[62557] = { title = "Our Realm Reclaimed", description = "Though Forsworn still fight across Bastion, the Temple of Loyalty is ours, and with it our realm.\n\nWe will have to stay diligent to maintain control of all of the temples, and much remains to be decided with the fate of our fallen brethren, but today is a day of great victory.\n\nJoin me at the Crest of Ascension, and witness its final empowerment.", objectives = "" }
WordHunterWoW_QuestEN[62560] = { title = "Growing in Power", description = "Wonderful news, {name}!\n\nYou have gathered enough Anima. The Queen is now able to empower the Heart of the Forest!", objectives = "" }
WordHunterWoW_QuestEN[62561] = { title = "My Heart is Full", description = "{name}! Can you believe it? We have enough Anima that the Winter Queen can fully restore the Heart of the Forest!\n\nYou've done so much for us!", objectives = "" }
WordHunterWoW_QuestEN[62563] = { title = "Back Again!", description = "Gorgantus just won't give up!\n\nWe've defeated her several times already, but the scavengers salvage the body, fix her up and send her right back in here!\n\nShe thinks this time she will defeat us... prove her wrong.", objectives = "" }
WordHunterWoW_QuestEN[62567] = { title = "Adventurers Wanted: Chromie's Call", description = "Chromie is seeking veteran adventurers to embark on expeditions through time and space.\n\nThis is your opportunity to experience the legendary adventures of the past--today!\n\nSpeak with Chromie near the Stormwind Embassy for more information.", objectives = "" }
WordHunterWoW_QuestEN[62568] = { title = "Adventurers Wanted: Chromie's Call", description = "Chromie is seeking veteran adventurers to embark on expeditions through time and space.\n\nThis is your opportunity to experience the legendary adventures of the past--today!\n\nSpeak with Chromie near the Orgrimmar Embassy for more information.", objectives = "" }
WordHunterWoW_QuestEN[62569] = { title = "The Jailer's Grasp", description = "By peering into the Maw, Bolvar drew the Jailer's attention.\n\nHis worst fears have come to pass.\n\nYou must help me break the link, {name}! The fragment of the Helm is the key!", objectives = "" }
WordHunterWoW_QuestEN[62584] = { title = "Frontline Resupply", description = "This forward camp relies heavily on our supply line from the tournament grounds. A recent shipment was attacked while in transit through the valley below us.\n\nSalvage what you can, and if possible, eliminate the threat so this does not happen again.", objectives = "" }
WordHunterWoW_QuestEN[62587] = { title = "In Search of Inner Calm", description = "I have always had dreams.\n\nSpecial dreams you could say.\n\nAny place of tranquility or calm can come to me in a dream.\n\nEven those that may have danger nearby, as calm can be found anywhere, if you know how.\n\nNow I dream of your world, your Azeroth. \n\nI cannot travel to your realm. Help me connect to my latest dream through your eyes.\n\nI have dreamed of a high place. A very high place. Do you know it?", objectives = "" }
WordHunterWoW_QuestEN[62588] = { title = "In Search of Inner Calm", description = "You return.\n\nThis pleases me. \n\nMore places of tranquility have come to me in dreams.\n\nI see a sandy beach, Sunsets. \n\nI cannot travel to your realm. Help me connect to my latest dream through your eyes.", objectives = "" }
WordHunterWoW_QuestEN[62589] = { title = "In Search of Inner Calm", description = "I am glad you wish to continue your meditations.\n\nIt will help you be more centered.\n\nI have had another dream. A warm dream of a cold place.\n\nIt is wrapped in white. Do you know of it?\n\nVenture there and experience the vista I saw in my dream.", objectives = "" }
WordHunterWoW_QuestEN[62590] = { title = "In Search of Inner Calm", description = "Thank you for returning.\n\nI have had another dream. Another vision of your realm.\n\nIn this dream the sky danced above me. \n\nOn the edge of a cliff, in a northern land. \n\nSuch a sight to behold. \n\nYou must experience it for yourself.", objectives = "" }
WordHunterWoW_QuestEN[62591] = { title = "In Search of Inner Calm", description = "We have already experienced so much together.\n\nI am grateful to have a companion on this voyage of discovery.\n\nYou walk where I can only project.\n\nYou touch that which I can only see.\n\nI have had another dream.\n\nAnother coast. A statue. \n\nA large statue of a little one. \n\nGo, seek out the view from my dream.", objectives = "" }
WordHunterWoW_QuestEN[62592] = { title = "Master of Inner Calm", description = "You have come a long way.\n\nYou are almost prepared to access your inner calm anywhere.\n\nJust one more journey under my guidance. \n\nIt is a short one. Peace was here in this garden all along.\n\nOne more location of calm to experience.\n\nThen you shall shed your spiritual shackles. \n\nI shall be proud.", objectives = "" }
WordHunterWoW_QuestEN[62594] = { title = "The Safety of Others", description = "If we do not contain this threat, it will only continue to spread.\n\nDo whatever you can, {name}.\n\nWe must not allow these lands to be overrun by the Scourge.", objectives = "" }
WordHunterWoW_QuestEN[62595] = { title = "The Safety of Others", description = "If we do not contain this threat, it will only continue to spread.\n\nDo whatever you can, {name}.\n\nWe must not allow these lands to be overrun by the Scourge!", objectives = "" }
WordHunterWoW_QuestEN[62597] = { title = "Bonesmith Heirmir", description = "<Alexandros Mograine left you a very straightforward letter of introduction for a certain Bonesmith Heirmir in Maldraxxus.\n\nWhat aid might she be able to offer the Ember Court?>", objectives = "" }
WordHunterWoW_QuestEN[62598] = { title = "Forgelite Sophone", description = "<Polemarch Adrestes left you a very formal letter of introduction for Forgelite Sophone in Bastion.\n\nWhat aid might she be able to offer the Ember Court?>", objectives = "" }
WordHunterWoW_QuestEN[62599] = { title = "Gormsmith Cavina", description = "<Hunt-Captain Korayn left you a terse letter of introduction to Gormsmith Cavina in Ardenweald.\n\nWhat aid might he be able to offer the Ember Court?>", objectives = "" }
WordHunterWoW_QuestEN[62600] = { title = "Finding Inner Peace", description = "This is a lovely spot don't you think?\n\nI knew the myths of Ardenweald. \n\nEven glimpsed it in dream.\n\nYet it swells with tranquility unimagined. \n\nCalm is what my kind live for. Even in chaos.\n\nYou can always find calm. I can show you if you would like? \n\nI can sense a nearby convergence of calm. That will provide a suitable demonstration.", objectives = "" }
WordHunterWoW_QuestEN[62601] = { title = "Forgy", description = "<Rendle left you a crumpled envelope addressed to Forgy in Darkhaven. On the outside of the envelope are very specific orders to tell Forgy that Rendle sent you.\n\nWhat aid might Forgy be able to offer the Ember Court?>", objectives = "" }
WordHunterWoW_QuestEN[62603] = { title = "A Rare and Unusual Spirit", description = "I'm glad to see you again, friend!\n\nWe have found another inert spirit gripped by dark dreams. Nasty stuff! \n\nIn this dream, a noble figure that once embodied loyalty has been consumed by their own doubts, leading them down a dark path.\n\nIf you were to defeat the fallen paragon, I bet we'll be able to revive this poor spirit.\n\nWill you help us once more, {name}?", objectives = "" }
WordHunterWoW_QuestEN[62605] = { title = "Broker Business", description = "<A web covered box of assorted scholar supplies lays haphazardly on the ground. The make seems Broker in origin. Perhaps the owner is nearby.>", objectives = "" }
WordHunterWoW_QuestEN[62606] = { title = "A Blackthorn Blend", description = "Ah, just the mushroomancer I wanted to see! Mind getting me some clay?\n\nThere's all kinds of different soil, you know. It's not all just dirt! And clay... clay is something special. You ever try growing through clay? Oh, I guess not.\n\nIt's hard work to break down, but once you do the flavor is incomparable! My roots are looking forward to the challenge.\n\nBlackthorn Grove has a particularly bitter and complex clay that is just what I'm craving. I'm sure they won't mind if you ask them for some.", objectives = "" }
WordHunterWoW_QuestEN[62607] = { title = "Glittering Gritty Goodness", description = "Well, hello there! Fancy helping me out today?\n\nYou ever been to Shimmerbough? Ever wonder why it's called that? I was there when it was named, you know.\n\nLots of people think it's the trees or the water, and they're right. But the secret to the shimmering is in the silt. The soil soaks and gains excess anima from the water, until the ground itself practically sparkles.\n\nI could really go for some shimmersilt right now. Would you let an old mushroom relive his youth?", objectives = "" }
WordHunterWoW_QuestEN[62608] = { title = "A Royal Treat", description = "So nice to see you again. I've got a special request for you.\n\nThe Winter Queen herself used to tend directly to groves, in the early times. Everything she touched burst with life and power. Even the ground she walked on.\n\nOver time, the Queen's Garden came to be known as the Garden of Night, for the Queen had not tended to her garden in so long.\n\nBut the ground is still potent with her power. It's the finest meal I've ever had. I know this is indulgent, but you and I both know I deserve it!", objectives = "" }
WordHunterWoW_QuestEN[62609] = { title = "Necrolord Arsenal", description = "<Bonesmith Heimir begins reading the letter you hand her.>\n\nHmm. Mograine usually has more sense than this...\n\n<Bonesmith Heimir finishes the letter and shreds it with her bony fingers.>\n\nAn order's an order. I'll arrange for a shipment of raw materials and forging equipment to be delivered to your court.\n\nWhile you wait, Mograine asks that you clear out some of our enemies to help cover for my absence.\n\nIt was in the letter. Shame it's all shredded up so you can't read it.", objectives = "" }
WordHunterWoW_QuestEN[62610] = { title = "Hyphae Patrol: The Stalks", description = "<Marasmius sighs.> \n\nThey're at it again, up in the Stalks.\n\nSeems like we didn't give them enough of a thrashing the first time, eh? What say you and I team up again and teach those younglings a lesson they won't forget?\n\nLet me know when you're ready and we'll get 'em, just like before!", objectives = "" }
WordHunterWoW_QuestEN[62611] = { title = "Hyphae Patrol: Heartwood Grove", description = "Those masked fiends have taken over Heartwood Grove, and I mean to stop their plans.\n\nHeartwood Grove was so beautiful before. And now, it's... No matter. We're going to fix this, you and me. Right now.\n\nCome, join me in battle. We'll give those monsters a thrashing that will make their masters think twice before desecrating that sacred place again!", objectives = "" }
WordHunterWoW_QuestEN[62612] = { title = "Venthyr Arsenal", description = "<Forgy reads the letter you hand him.>\n\nAh, Rendle sent you. Should've said so.\n\nNo problem. I'll get you everything you need to be bashing skulls at that court.\n\nGonna need some help convincing my boss for the time off, though.\n\nReal stick in the muck, yeah?\n\nSay you take care of some of the troubles around here, tell everyone it's for me--that'll do it.", objectives = "" }
WordHunterWoW_QuestEN[62613] = { title = "Kyrian Arsenal", description = "<Forgelite Sophone reads the letter you hand her.>\n\nI see.\n\nWherever I may serve, I will go.\n\nAre you willing to do the same? Will you serve Bastion where it has need?", objectives = "" }
WordHunterWoW_QuestEN[62614] = { title = "Hyphae Patrol: Eventide Grove", description = "I hope you're ready to fight.\n\nThe Drust are bolstering their forces in Eventide Grove. Most of Ardenweald doesn't remember them, but I do. You have to completely root them out to be rid of their presence, or they'll grow right back, tougher than ever.\n\nCome with me. We're going to exterminate every last one of them. Let me know when you're ready.", objectives = "" }
WordHunterWoW_QuestEN[62615] = { title = "Hyphae Patrol: Gossamer Cliffs", description = "Bad news from the Gossamer Cliffs. We need to help.\n\nThe varmints terrorizing the poor silk striders have become more cruel and aggressive lately. The silk striders are important to Ardenweald; more important than almost anyone else knows. We can't lose any more.\n\nLet me know when you're ready to go and we'll scare those gits away for good!", objectives = "" }
WordHunterWoW_QuestEN[62616] = { title = "Night Fae Arsenal", description = "<Gormsmith Cavina reads the letter you hand him.>\n\nI'm not surprised the Hunt-Captain sent you to me. I am the finest gormsmith in all of Ardenweald, afterall.\n\nHer orders are clear and I'm happy to help.\n\nWe'll need you to take on some extra patrols to make up for the lost time and resources.\n\nSound fair?", objectives = "" }
WordHunterWoW_QuestEN[62619] = { title = "A Meandering Story", description = "<A quick glance at this heavy tome reveals flowery language and a plot that doesn't seem to go anyplace. At least not in the first few chapters.\n\nThere is some dirt on the cover, but the damage isn't too bad. This book doesn't seem to have found itself in too much trouble-- a bit like its plot.\n\nArchivist Dreyden would probably be pleased to have his book back.>", objectives = "" }
WordHunterWoW_QuestEN[62620] = { title = "A Wandering Tale", description = "<This book might have a point, but the author is taking every possible detour along the way. Or maybe it's about the journey and not the destination...\n\nIn any case, Archivist Dreyden would probably be pleased to have his book back.>", objectives = "" }
WordHunterWoW_QuestEN[62621] = { title = "An Escapist Novel", description = "<Action, adventure, thrills, chills... This book has it all! Penned by a mortal soul who led an amazing life, this book is a page-turner. \n\nBut is it true? Could one person fight conspiracies, ancient evils, vast enemy armies, demons and even gods in a single lifetime?\n\nOn further reflection, it could be true, but what is a \"duck\" this book speaks of? That part sounds fake.\n\nStill... it was a good story. Archivist Dreyden would probably be pleased to have his book back.>", objectives = "" }
WordHunterWoW_QuestEN[62622] = { title = "A Travel Journal", description = "<This book appears to be a travelogue of this book's personal journey around Ardenweald! And self-written and published no less!\n\nFlipping towards the end you see yourself enter the picture as a villain, unjustly attacking the book and opening it. \n\nYou read \"This book appears to be a travelogue of this book's personal journey around Ardenweald! And Self-written and-\"\n\nYou hurriedly close the book, feeling queasy. It should go back to Archivist Dreyden.>", objectives = "" }
WordHunterWoW_QuestEN[62623] = { title = "A Naughty Story", description = "<You have held this book for less than five minutes and it has already escaped once, bitten you twice and somehow managed to steal some gold.\n\nThis is not what you were expecting from a \"Naughty Story\" but then again, maybe you should have.\n\nYou bind the book closed so it will hopefully cause a minimum of mischief. Time to bring it to Archivist Dreyden.>", objectives = "" }
WordHunterWoW_QuestEN[62624] = { title = "The Queen's Conservatory", description = "I have heard that you are aiding us in restoring our sanctum, {name}. \n\nThere is a very special magical grove that we know as The Queen's Conservatory. \n\nWithin this magical sanctuary we nurture the spirits of old deities back to life. But its magic has waned with the anima drought. \n\nIt is in need of your help.\n\nIt would mean the world to us if you could start the restoration process by acquiring the resources we need.", objectives = "" }
WordHunterWoW_QuestEN[62625] = { title = "A Rare and Unusual Spirit", description = "It's a joy to see the progress you've made in the restoration of the conservatory, {name}!\n\nBut there's still more work to be done.\n\nWe have found another inert spirit. A dark dream is preventing its awakening.\n\nIn this dream, the spirit is caught in the midst of a feud between ancient beings. Both are a bit on the unsavory side, but one is much, much worse than the other!\n\nIf you were to defeat the Father of Sleep, it should nudge the spirit from its slumber. Will you help?", objectives = "" }
WordHunterWoW_QuestEN[62627] = { title = "All Spirits Great and Small", description = "This is a most curious place.\n\nSo much energy of rebirth. A fusion of different forms of magic. Not what I expected.\n\nI too was committed to rebirth among my kind. This magic is both known to me, and like nothing I have seen before. Yet it all serves to balance. \n\nIt is not just great spirits of import that help to maintain the cosmic balance.\n\nEven the smallest of creatures can play a role. \n\nI can show you if you like? Visit the remains of one such creature, and we shall rekindle its spirit.", objectives = "" }
WordHunterWoW_QuestEN[62629] = { title = "All Spirits Great and Small", description = "The time has come for us to rekindle another animal spirit.\n\nThis one was lost to fire and raiding in a distant land.\n\nGo. Commune with the creature's remains. Release its spirit so that it may return here.", objectives = "" }
WordHunterWoW_QuestEN[62630] = { title = "All Spirits Great and Small", description = "The time has come for us to rekindle another animal spirit.\n\nWhile appearing normal to you, and to the great winged creature that ate it, this creature was in fact somewhat special among its kind. \n\nYou should travel to its grisly resting place and commune with its spirit so that it may join us in the conservatory.", objectives = "" }
WordHunterWoW_QuestEN[62653] = { title = "Stop the Inquisition", description = "The Lord Chamberlain's inquisitors still torment the poor souls trapped under their care.\n\nYou must put a stop to their wicked deeds!\n\nSpeak with Archivist Fane, whom you worked with before to defeat an inquisitor, to acquire the sinstone of another inquisitor in the halls.\n\nWith their sinstone, you will be able to shatter that inquisitor's defenses and lead the charge to defeat them.\n\nBring friends, {name}. Many of the inquisitors are far too dangerous to approach alone.", objectives = "" }
WordHunterWoW_QuestEN[62654] = { title = "Maw Walker", description = "I believe now it is time for you to leave.\n\nYou are a Maw Walker, one who can activate the waystone between the Maw and the lands beyond. While your friends may not hold the same title, there is a way to send them through the gate. \n\nSouls can be connected. In theory, if you let someone attune themselves to your soul while you activate the waystone, you both should be able to leave. Even fleeting connections may produce some result.\n\nGo with your other two guests and see if my hypothesis is correct.", objectives = "" }
WordHunterWoW_QuestEN[62691] = { title = "A Calling in Revendreth", description = "We got a lot of problems out there, boss. Big ones, little ones, really smelly ones, it's a lot.\n\nIf we're gonna take on Denathrius, the first thing we gotta do is clean up right here in Revendreth.\n\nWe get things cleaned up, yeah? Then we get some new allies, and we probably get our hands on some anima to boot.\n\nIt's a call to action, it is. And it's important that we get started right away.\n\nGet on out there and get your boots muddy!", objectives = "" }
WordHunterWoW_QuestEN[62692] = { title = "A Calling in Bastion", description = "Our forces are weakened by doubt and our temples are under assault. If we are to aid the rest of the Shadowlands, we must begin here, in Bastion.\n\nTravel the golden fields and root out evil wherever you may find it. In time, we will rebuild our forces and our anima stores, and stand tall once more.\n\nToday, you walk the path of courage--it is your calling. Show our people that doubt will not fester here.", objectives = "" }
WordHunterWoW_QuestEN[62693] = { title = "A Calling in Ardenweald", description = "Ardenweald is fractured, its roots strangled. Before we can begin to regrow our glades, we must unearth the evils that have festered here.\n\nWe call to you, today, to defend our forests. Take the weald paths through our lands, aiding our allies and defeating our enemies. With these actions, we will renew our forces, and rebuild our anima. In time, hope will blossom.\n\nOur trust is in you, our newest seedling.", objectives = "" }
WordHunterWoW_QuestEN[62694] = { title = "A Calling in Maldraxxus", description = "Today marks the beginning of our path to victory.\n\nEnemies surround us on all sides. Aid our troops on the battlefield and return with the resources we need to wage our war.\n\nOnce we have secured our home front, we can direct our efforts outwards.\n\nSuch is your calling. Failure is unacceptable.", objectives = "" }
WordHunterWoW_QuestEN[62695] = { title = "A Call to Service", description = "An opportunity has arisen that will be perfect for you to display your... prowess... to the denizens of Revendreth.\n\nSpeak with Rendle. That dredger is disturbingly effective when it comes to hatching schemes. He says he has a plan for you.", objectives = "" }
WordHunterWoW_QuestEN[62697] = { title = "A Call to Service", description = "<Laurel picks out a sad tune on her harp.>\n\nOur groves wilt and wither,\nand enemies wait at our gates!\nThe forest calls out in sorrow, \n\"Please help us before it's too late!\"\n\n<The melody becomes a call to arms.>\n\nO huntsman, now answer our calling!\nArdenweald is in need of your might!\nEnvoy Blodwyn will give you a mission,\nto ride with the Wild Hunt tonight!", objectives = "" }
WordHunterWoW_QuestEN[62698] = { title = "A Call to Service", description = "Elysian Hold requires anima to operate fully. We need as much as we can so it may serve our needs.\n\nOur temples are fraught with challenges. By heeding their call you will recover anima for use within the sanctum here.\n\nSpeak with Hermestes first, who will guide you on the path of courage.", objectives = "" }
WordHunterWoW_QuestEN[62700] = { title = "Ashes of the Tower", description = "Your first step towards obtaining the power is to retrieve... something. Yes, I believe it's coming back to me.", objectives = "" }
WordHunterWoW_QuestEN[62704] = { title = "The Threads of Fate", description = "It is my duty to observe the strands of fate. The wondrous possibilities that the Purpose lays before us.\n\nFate flows around you, mortal. It shifts. It changes. But I have stilled its movements to offer you... a choice.\n\nYou may journey through the Shadowlands in the same manner as those who came before you have done.\n\nOr you may choose a different path. One that lets you forge a bond with a covenant now, and move freely through the realms of Death to forge your own destiny.\n\nWhat say you, mortal?", objectives = "" }
WordHunterWoW_QuestEN[62707] = { title = "The Elysian Fields", description = "You must travel to Bastion, eternal home of the winged kyrian.\n\nDo not be fooled by their golden fields and shining spires--the kyrian have been weakened by the great anima drought, and face the brink of civil war against their own fallen brethren.\n\nThey will benefit greatly from your aid. Seek one known as Kalisthene in the crossroads called Hero's Rest. She will direct you further.\n\nPathscribe Roh-Avonavi in the Ring of Transference above can provide transport.", objectives = "" }
WordHunterWoW_QuestEN[62714] = { title = "A Gift for an Acolyte", description = "The materials you supplied were more than sufficient for my purposes. For that, you have my gratitude.\n\nI think I know how to make the best use of the excess.\n\nA dear friend of mine recently achieved the role of Acolyte in service to the Temple of Purity. You are new here, so I will spare you the details, but it is an honor to serve a temple before one reaches ascension.\n\nI want to celebrate her success with a gift. Will you take this parcel to Acolyte Amalthina?", objectives = "" }
WordHunterWoW_QuestEN[62715] = { title = "More Than A Gift", description = "You have no idea what you just delivered, do you?\n\n<She opens the parcel to reveal a wreath of Larion plumage.>\n\nI will explain, but first... I wish to return the favor.\n\nKlystere and I frequent a resting place to the north of here, along the path to the Temple of Courage. We planted a flower for our enjoyment, as we spend so much of our free time there.\n\nBring me this bloom, if you would be so kind. Then I will tell you about the significance of this gift.", objectives = "" }
WordHunterWoW_QuestEN[62716] = { title = "Re-Introductions", description = "Though you have chosen your path, the fate of the Shadowlands has yet to be determined.\n\nThe power of the Banished One grows. It falls to you, and others of your kind, to thwart him.\n\nThe Arbiter's Honored Voice, Tal-Inara, will aid you in choosing a covenant. Bolstering their strength offers our best chance at victory.\n\nLet the Purpose guide you, {name}. Always.", objectives = "" }
WordHunterWoW_QuestEN[62718] = { title = "Hero's Rest", description = "In light of the new arrivals to Bastion, Kalisthene has enabled the anima gateways to Hero's Rest once more!\n\nThose wishing to partake of breathtaking views, unparalleled steward service, and all manner of training and repair facilities should venture to this most remarkable of locations at their earliest convenience.\n\nSimply follow the path north and bear to the right at the crossroads.\n\nKalisthene will personally greet all new arrivals for this most joyous of occasions!", objectives = "" }
WordHunterWoW_QuestEN[62719] = { title = "The Final Pieces", description = "The final components you'll need to acquire are... vessels... rune vessels! Armor to hold the might that will be imbued.\n\nAnd... powers? No... missives? Yes! Missives will allow your item to enhance your own personal strengths. But they cannot be the same. No, the two must offer different benefits.\n\nAll of these can be obtained from souls with the correct crafting knowledge.\n\nAnd lastly, more of my memories. Memories of the runes, of the powers... of myself.", objectives = "" }
WordHunterWoW_QuestEN[62723] = { title = "Bolstering Bastion", description = "You are no aspirant, but I welcome any aid that Oribos might bring us in these dire times.\n\nPlease, aid our people in any way you can. With anima in low supply and the insidious Forsworn encroaching from all sides, there is no shortage of trials to overcome.\n\nDo this for us, and I will see to it myself that our almighty Archon hears of your deeds in service of the kyrian. Mark well my words, and follow the path.", objectives = "" }
WordHunterWoW_QuestEN[62725] = { title = "A Test of Guile", description = "A test of wits and guile.", objectives = "" }
WordHunterWoW_QuestEN[62729] = { title = "Return to Oribos", description = "You have proven yourself a worthy ally of Bastion in your time here, {name}. Though I wish you could remain here, there are other realms in the Shadowlands that require aid more.\n\nReturn to Oribos when you are able and seek out Tal-Inara. She will help you decide where to best next focus your efforts.\n\nArchon watch over you.", objectives = "" }
WordHunterWoW_QuestEN[62730] = { title = "Fruit of the Gods", description = "You like sweet fruit? \n\nStewards grow juiciest Purian. It special fruit! You find it many places in Bastion. It used for many things. \n\nEat for nourishment.\n\nGive to bells for blessings.\n\nGive to stewards for treasure.\n\nYou find, I show you how!", objectives = "" }
WordHunterWoW_QuestEN[62733] = { title = "The Sweetest Tribute", description = "Purian good to eat, yes, but better to give.\n\nYou find locked Silver Strongbox near steward statue. Give Ripe Purian fruit as tribute.\n\nThen get nice surprise!\n\nYou try?", objectives = "" }
WordHunterWoW_QuestEN[62738] = { title = "A Fresh Blade", description = "Though they were once unified in defending the Shadowlands, the houses of Maldraxxus have turned against each other.\n\nTheir armies clash within their realm and have even orchestrated an assault on Bastion. Now only the Necrolords remain loyal to the Primus.\n\nSpeak to Secutor Mevix at the Bleak Redoubt in Maldraxxus. His tactical skills will ensure you are sent where you are most needed.\n\nPathscribe Roh-Avonavi in the Ring of Transference above can provide you with transportation.", objectives = "" }
WordHunterWoW_QuestEN[62739] = { title = "Restoring Balance", description = "Ardenweald is crucial to the cycle of rebirth for nature spirits that enter their realm.\n\nUnfortunately, the anima drought has led to the loss of entire groves--souls that will never complete their cycle.\n\nNow foes seek to destroy what remains of the once tranquil forests, threatening the already beleaguered Court of Night. \n\nLady Moonberry of the Court has requested aid. Pathscribe Roh-Avonavi in the Ring of Transference above can provide transport.", objectives = "" }
WordHunterWoW_QuestEN[62740] = { title = "Dark Aspirations", description = "Prince Renathal has started a daring rebellion against his father, the nefarious Sire Denathrius who betrayed us all by pouring Revendreth's vast anima stores into the Maw.\n\nYou must travel to Revendreth and aid Renathal in his efforts. He is our best hope at restoring Revendreth to order.\n\nPathscribe Roh-Avonavi in the Ring of Transference above can provide transport.", objectives = "" }
WordHunterWoW_QuestEN[62748] = { title = "Rallying Maldraxxus", description = "We need all the help we can get! It's taking all we have to hold our ground against the other houses, let alone gain any ground against them.\n\nTruth be told, your blade will be welcome anywhere. There are no shortage of battles to be won, foes to be toppled, or weary soldiers to be relieved.\n\nHelp us regain control of Maldraxxus, and in the name of the Primus I will see you are amply rewarded.", objectives = "" }
WordHunterWoW_QuestEN[62761] = { title = "Return to Oribos", description = "I wouldn't be a tactician if I didn't recognize when the mission is complete.\n\nMuch remains to be done before Maldraxxus can stand tall once again, but that day will come thanks to your efforts. \n\nThere are other realms in need of your skills more than us. You should return to Oribos and see to it that they receive it.", objectives = "" }
WordHunterWoW_QuestEN[62763] = { title = "Support the Court", description = "Groves are under attack everywhere! There simply aren't enough of us to protect them all!\n\nYou just might be our only hope.\n\nWe must restore order, or more precious souls will be lost to us. Please, help anyone you can, anywhere you can. My heart cannot bear to see any more pain!\n\nI'll make sure the Winter Queen hears of your deeds, don't you worry!", objectives = "" }
WordHunterWoW_QuestEN[62776] = { title = "Return to Oribos", description = "I wish you could stay and relax here, maybe enjoy a play at the Star Lake Amphitheater, but there's simply no time!\n\nThere are other realms out there that need your help, too.\n\nYou will always be a friend of the Court, but I'm afraid you must return to Oribos. The Shadowlands needs you!", objectives = "" }
WordHunterWoW_QuestEN[62778] = { title = "Reinforcing Revendreth", description = "Denathrius must be stopped at all costs. However, we've no hope of taking him out while his forces still control much of Revendreth.\n\nIf you are here to aid us, then there is no shortage of work to be done. Disposing of my father's many allies being chief among that work, of course, but any aid you can provide will be of use.\n\nThere is too much at stake for all the Shadowlands if we fail. I will see to it that you are handsomely rewarded for your efforts.", objectives = "" }
WordHunterWoW_QuestEN[62779] = { title = "Return to Oribos", description = "I truly wish you could remain here and aid our cause--it is truly the most pressing manner in all the Shadowlands--but Revendreth alone cannot stand against the growing darkness.\n\nYou must return to Oribos and ensure the other realms do not falter in their commitments. Tal-Inara will be able to guide you appropriately.\n\nThank you once again for your aid, mortal. May our paths cross again.", objectives = "" }
WordHunterWoW_QuestEN[62785] = { title = "I Could Be A Contender", description = "Hold up there, brother. \n\nIf you are serious about fighting in the Arena you're going to need a manager. \nLucky for you, brother, I know a guy. He's just had some openings in his roster of fighters and you look like just the type of {class} he needs to fill his ranks.\n\nName is Louison, you can find him at the gate just east of here.\n\nTell him I sent ya, brother.", objectives = "" }
WordHunterWoW_QuestEN[62789] = { title = "Of Great Renown", description = "As you aid our sacred covenant across the Shadowlands, your connection to it shall grow ever stronger.\n\nYour Renown will afford you many benefits over time.\n\nSeek out Iona Skyblade at the front of the hold, near the Crest of Ascension. She will show you the glory of the path.", objectives = "" }
WordHunterWoW_QuestEN[62790] = { title = "The Path Provides", description = "All who follow the path are granted precious gifts by virtue of their connection with our covenant.\n\nThe strength of that bond, known as Renown, is reflected in the shining spires of Elysian Hold itself. Though you have yet to gain Renown, you will as you aid us across the Shadowlands.\n\nWhen you are ready, I will show you all that the path can provide.", objectives = "" }
WordHunterWoW_QuestEN[62791] = { title = "Our Most Precious Resource", description = "You have fulfilled your calling, Maw Walker, and brought peace to our realm.\n\nStay vigilant, for others will similarly call upon you in time.\n\nThe anima you have so dutifully recovered will be of great use in the hold. Bring it to Haephus at once. He will ensure it is kept safe until it is needed.\n\nGo in service.", objectives = "" }
WordHunterWoW_QuestEN[62792] = { title = "Into the Reservoir", description = "As the flow of anima withered within Bastion, our mighty Archon entrusted me with guarding our stores until they are needed.\n\nYou may deposit any anima you recover into the reservoir here. By my life, and by the glory of the Archon, I will ensure they are kept safe.", objectives = "" }
WordHunterWoW_QuestEN[62793] = { title = "It's All Coming Together", description = "Our brothers and sisters are spread thin fighting the Forsworn, maintaining order among aspirants waiting to ascend, and countless other duties.\n\nThe willing souls you recovered from the Maw will be a great boon to our capabilities in these dire times.\n\nGo to Haephus at once--he has long been searching for aid in activating some of our sanctum's most powerful features. It is time we saw Elysian Hold brought to its full potential.", objectives = "" }
WordHunterWoW_QuestEN[62794] = { title = "Enhancing the Hold", description = "As thanks for your efforts in recovering the anima and souls we now have available, you may decide which of Elysian Hold's features we upgrade first.\n\nOnce active, it shall expand our capabilities to help not only Bastion, but all the Shadowlands.\n\nDo not worry--as you continue to recover anima and willing souls we will activate them all in time. For now, a single upgrade must suffice.", objectives = "" }
WordHunterWoW_QuestEN[62795] = { title = "A Conduit for Good", description = "While the gifts your bond shall bring you are substantial, you may also empower yourself further through the use of conduits.\n\nConduits act to channel the energy of your soulbind into your form more directly, increasing your potential in a myriad of ways.\n\nUse the ones I have given you as a test of this power, but fear not--you will find others as you aid the Shadowlands.", objectives = "" }
WordHunterWoW_QuestEN[62796] = { title = "Return to Adrestes", description = "Baine suffers within Torghast, but at least we know that he yet lives.\n\nRushing to his rescue would prove disastrous without a plan of attack. I will see to preparing one.\n\nIn the meantime, I suggest you bring the souls you rescued to Elysian Hold.\n\nThe kyrian are vital to the Shadowlands. If Bastion remains in turmoil, then all might soon be lost.", objectives = "" }
WordHunterWoW_QuestEN[62797] = { title = "The Vessels of Metal", description = "You have the bearing of one familiar with the art of smithing. But perhaps you have more to learn.\n\nVessels that hold the power of the runes can be crafted by a hand such as yours. But this I cannot teach you.\n\nHmm, there is a way. I will entrust you with a memory of my recipes for the vessels. Take it to a master of your craft and they will show you the way.\n\nWhat's that? Do not worry. It is merely an echo of my memory. What you restored to me remains intact.", objectives = "" }
WordHunterWoW_QuestEN[62798] = { title = "The Vessels of Leather and Bone", description = "You have the bearing of one familiar with the art of leatherworking. But perhaps you have more to learn.\n\nVessels that hold the power of the runes can be crafted by a hand such as yours. But this I cannot teach you.\n\nHmm, there is a way. I will entrust you with a memory of my recipes for the vessels. Take it to a master of your craft and they will show you the way.\n\nWhat's that? Do not worry. It is merely an echo of my memory. What you restored to me remains intact.", objectives = "" }
WordHunterWoW_QuestEN[62799] = { title = "The Vessels of the Thread", description = "You have the bearing of one familiar with the art of thread work. But perhaps you have more to learn.\n\nVessels that hold the power of the runes can be crafted by a hand such as yours. But this I cannot teach you.\n\nHmm, there is a way. I will entrust you with a memory of my recipes for the vessels. Take it to a master of your craft and they will show you the way.\n\nWhat's that? Do not worry. It is merely an echo of my memory. What you restored to me remains intact.", objectives = "" }
WordHunterWoW_QuestEN[62800] = { title = "The Vessels of Jewels", description = "You have the bearing of a lapidary. Though familiar with the art of jewelcraft, perhaps there is yet more to learn.\n\nVessels that hold the power of the runes can be crafted by a hand such as yours. But this I cannot teach you.\n\nHmm, there is a way. I will entrust you with a memory of my recipes for the vessels. Take it to a master of your craft and they will show you the way.\n\nWhat's that? Do not worry. It is merely an echo of my memory. What you restored to me remains intact.", objectives = "" }
WordHunterWoW_QuestEN[62801] = { title = "The Call of Fate", description = "I am the Arbiter's fatescribe. It is my duty to observe the strands of destiny that the Purpose lays before us.\n\nFate flows through you, mortal, as you journey through the Shadowlands. And now it offers you... a choice.\n\nReturn to Oribos, {name}, that I might help guide your path.\n\nThe Purpose is our way.", objectives = "" }
WordHunterWoW_QuestEN[62804] = { title = "Filling the Tanks", description = "<The containment pack appears to be intact, albeit empty. Perhaps refilling it with the appropriate mixture of liquids will render it functional once more.\n\nSlaying the correct combination of slimes should provide all the fluid necessary.>", objectives = "" }
WordHunterWoW_QuestEN[62807] = { title = "Forest Refugees", description = "Some of those displaced by the fallen groves have made a home for themselves at the base of the Heart of the Forest.\n\nHibernal Hollow is fortunate. We have supplies, when they may not.\n\nIf you would, bring these to Flwngyrr. They care for the refugees there.", objectives = "" }
WordHunterWoW_QuestEN[62828] = { title = "[DNT] Door of Shadows", description = "", objectives = "" }
WordHunterWoW_QuestEN[62832] = { title = "Friends in Dark Places", description = "Even with all your aid, our sanctum will grow weaker without souls willing to help us.\n\nMany souls that may have been destined for Bastion are trapped within the Maw. If you can find a way to free them, they will help us restore Elysian Hold's power.\n\nSeek out what aid you can and do what we cannot, Maw Walker. Our very future may depend on it.", objectives = "" }
WordHunterWoW_QuestEN[62833] = { title = "A Hero of Great Renown", description = "As you gain renown across the Shadowlands, you will draw others to our cause. Some may provide resources; some may offer direct support.\n\nElspeth Larink will be responsible for putting their contributions to use. Speak with her to learn more.", objectives = "" }
WordHunterWoW_QuestEN[62834] = { title = "Glorious Ambition", description = "The renown you earn through your deeds can and will greatly benefit our covenant. Our ambition is not confined within the borders of Maldraxxus, after all.\n\nAllow me to demonstrate what we achieve as you gain renown.", objectives = "" }
WordHunterWoW_QuestEN[62835] = { title = "A Call to Service", description = "We may hold the Seat of the Primus, but it will do us no good without the anima to power it.\n\nAs you fight beside our troops on the battlefield, seek out opportunities to recover anima to support the war effort.\n\nSpeak with Sergeant Romark. He can offer you additional guidance.", objectives = "" }
WordHunterWoW_QuestEN[62836] = { title = "Signs of the Lion", description = "Thanks to your efforts, Thrall, Jaina Proudmoore, and Baine Bloodhoof are safe. Yet so long as the Jailer holds any hero of Azeroth, I fear he has power over us all.\n\nIt seems Anduin has been taken deeper into the tower than the others. Before I risk peering inside, you must make one last attempt to find him.\n\nYou say the Jailer spoke of honing a weapon. I fear we are running out of time.\n\nDo not relent, {name}. Search the twisting corridors of Torghast for any sign of the Young Lion.", objectives = "" }
WordHunterWoW_QuestEN[62837] = { title = "Hopeful News", description = "The terms of our bargain have been met. You may depart with the souls you acquired.\n\nPerhaps the fate of this \"Baine\" is of interest to you or your allies. I suggest you return to Oribos and consult them.\n\nNo need to rush. After all, those held within Torghast are tortured for centuries.\n\nKindly remember not to tell anyone about our arrangement. Discretion is key between business partners, after all.", objectives = "" }
WordHunterWoW_QuestEN[62839] = { title = "Anima is Strength", description = "You are victorious, Maw Walker. And with your success, our forces grow stronger.\n\nStay alert. Your strength will be called upon again soon enough.\n\nBring the anima you recovered to Akradia Moa at once. She will ensure its proper storage.", objectives = "" }
WordHunterWoW_QuestEN[62840] = { title = "Into the Reservoir", description = "With anima in short supply, Baroness Draka has tasked me with carefully managing our reserves as they are needed.\n\nYou may deposit any anima you recover into the reservoir here. Be assured that the Necrolords will defend it at all costs.", objectives = "" }
WordHunterWoW_QuestEN[62843] = { title = "The Soul Contact", description = "Your reputation precedes you, Maw Walker... braving the Maw and bringing Baron Mograine back in one piece...\n\nThat was most impressive!\n\nWith our dire shortage of souls, we'll need you to do that again. Bring us more willing souls so we can restore this sanctum's power!\n\nSeek out the broker who aided you before and ask if she will do so again. You may need her.", objectives = "" }
WordHunterWoW_QuestEN[62844] = { title = "Return to Draka", description = "Baine suffers within Torghast, but at least we know that he yet lives.\n\nRushing to his rescue would prove disastrous without a plan of attack. I will do what I can to prepare one.\n\nIn the meantime, you received a summons from Baroness Draka asking that you return to the Seat of the Primus.\n\nThe Necrolords are the key to saving the Shadowlands, {name}. I suggest you return to them as soon as you are able.", objectives = "" }
WordHunterWoW_QuestEN[62845] = { title = "Bringing It All Together", description = "With all of the houses against us, our forces are hard pressed to hold the line.\n\nThe souls you rescued from the Maw will help strengthen our position and bolster our defenses.\n\nBring them to Arkadia Moa. She will know how best to put them to use and empower our sanctum.", objectives = "" }
WordHunterWoW_QuestEN[62846] = { title = "Sanctum Improvements", description = "Your will to succeed is strong, Maw Walker. With the anima and the souls you have recovered, we can now begin to unlock our sanctum's true potential.\n\nAs we acquire more souls and more anima, we can gain even greater power from the Seat of the Primus. Remain relentless in your pursuit, and victory will be ours.", objectives = "" }
WordHunterWoW_QuestEN[62848] = { title = "Conduits, What Are They For?", description = "While the benefits of soulbinding are substantial, you may strengthen them further through the use of conduits.\n\nConduits act to channel the anima of our bond in a myriad of ways, vastly increasing both of our potential.\n\nLet us test out the ones I have given you. Fear not--many others like it can be found throughout the Shadowlands.", objectives = "" }
WordHunterWoW_QuestEN[62849] = { title = "Paragon of the Court of Harvesters", description = "Maw Walker. \n\nYour efforts have provided the Court of Harvesters a decisive edge in their ongoing conflict with the zealots and sycophants who cling to the lost cause of Sire Denathrius.\n\nIf you will join me in Darkhaven we can express our gratitude to you in a more... physical... way. \n\nWith treasure, of course.", objectives = "" }
WordHunterWoW_QuestEN[62850] = { title = "Paragon of the Ascended", description = "Maw Walker. \n\nYour efforts have provided the Ascended with a decisive edge in their goals.\n\nWe have rewards for you, and thanks.", objectives = "" }
WordHunterWoW_QuestEN[62851] = { title = "Paragon of the Undying Army", description = "Your continued advancement of the Undying Army objectives has earned you the continued respect of our forces. \n\nI have been authorized to provide you with a portion of recent spoils of war in gratitude. Please join me at the Seat of the Primus to collect these spoils at your earliest convenience.", objectives = "" }
WordHunterWoW_QuestEN[62852] = { title = "Paragon of the Wild Hunt", description = "Well met, {name}!\n\nYou have proven yourself to all of Ardenweald. We would grant you further rewards, for your valor and cunning on our behalf.\n\nMeet with me at the Heart of the Forest.", objectives = "" }
WordHunterWoW_QuestEN[62855] = { title = "Edict of the Eternal Ones", description = "Death appears to function differently for you, Maw Walker. Alas, you have shed some of your stygia.\n\nReturn to the place of your passing, and you shall find what you left behind.", objectives = "" }
WordHunterWoW_QuestEN[62856] = { title = "Building Your Renown", description = "As you aid the court in your travels across the Shadowlands, your connection to us shall grow ever stronger.\n\nIn time, you will be able to reap the benefits of your growing Renown.\n\nOne of my most trusted and loyal followers, Rahel, has been watching you for some time. She can report as to your standing and the Renown you have garnered with my people.\n\nSpeak to her and she might explain better how this Renown might be best put to work.", objectives = "" }
WordHunterWoW_QuestEN[62857] = { title = "The Court's Bounty", description = "Venthyr are drawn to new things, so we are going to make you the figurehead of our Sanctum. \n\nAs your Renown throughout the Shadowlands grows, we will grow with you, accumulating power and influence we otherwise would not have access to. \n\nIt will fall to me to track your Renown and quantify it as a resource. A true currency of Courts, if you will. \n\nObserve.", objectives = "" }
WordHunterWoW_QuestEN[62858] = { title = "Return Lost Souls", description = "Souls continue to pour into the Maw. As long as this is still happening, we need to save as many as possible!\n\nThe Jailer twists the cycle of life and rebirth. This cannot be allowed to continue! We must thwart his plans.\n\nReturn to the Maw and rescue those that you can.", objectives = "" }
WordHunterWoW_QuestEN[62859] = { title = "Return Lost Souls", description = "Souls continue to pour into the Maw. As long as this is still happening, we need to save as many as possible!\n\nThe Jailer twists the cycle of life and rebirth. This cannot be allowed to continue! We must thwart his plans.\n\nReturn to the Maw and rescue those that you can.", objectives = "" }
WordHunterWoW_QuestEN[62860] = { title = "Return Lost Souls", description = "Souls continue to pour into the Maw. As long as this is still happening, we need to save as many as possible!\n\nThe Jailer twists the cycle of life and rebirth. This cannot be allowed to continue! We must thwart his plans.\n\nReturn to the Maw and rescue those that you can.", objectives = "" }
WordHunterWoW_QuestEN[62861] = { title = "Return Lost Souls", description = "Souls continue to pour into the Maw, circumventing the natural order of the Shadowlands.\n\nThe Jailer denies these souls their rightful eternities. Only you, Maw Walker, can set things right.\n\nReturn to the Maw and save all that you can.", objectives = "" }
WordHunterWoW_QuestEN[62862] = { title = "Return Lost Souls", description = "Souls continue to pour into the Maw, circumventing the natural order of the Shadowlands.\n\nThe Jailer denies these souls their rightful eternities. Only you, Maw Walker, can set things right.\n\nReturn to the Maw and save all that you can.", objectives = "" }
WordHunterWoW_QuestEN[62863] = { title = "Return Lost Souls", description = "Souls continue to pour into the Maw, circumventing the natural order of the Shadowlands.\n\nThe Jailer denies these souls their rightful eternities. Only you, Maw Walker, can set things right.\n\nReturn to the Maw and save all that you can.", objectives = "" }
WordHunterWoW_QuestEN[62864] = { title = "Return Lost Souls", description = "Maw Walker, I'm sure you've seen firsthand the souls that continue to pour into the Maw. \n\nWe must act now to cut off the Jailer's power, denying him as many souls as possible. That power belongs to the Necrolords.\n\nI shall direct your efforts to save these souls, and help find them a place among the armies of Maldraxxus.\n\nReturn to the Maw and rescue those that you can.", objectives = "" }
WordHunterWoW_QuestEN[62865] = { title = "Return Lost Souls", description = "Maw Walker, I'm sure you've seen first hand the souls that continue to pour into the Maw. \n\nWe must act now to cut off the Jailer's power, denying him as many souls as possible. That power belongs to the Necrolords.\n\nI shall direct your efforts to save these souls, and help find them a place among the armies of Maldraxxus.\n\nReturn to the Maw and rescue those that you can.", objectives = "" }
WordHunterWoW_QuestEN[62866] = { title = "Return Lost Souls", description = "Maw Walker, I'm sure you've seen firsthand the souls that continue to pour into the Maw. \n\nWe must act now to cut off the Jailer's power, denying him as many souls as possible. That power belongs to the Necrolords.\n\nI shall direct your efforts to save these souls, and help find them a place among the armies of Maldraxxus.\n\nReturn to the Maw and rescue those that you can.", objectives = "" }
WordHunterWoW_QuestEN[62867] = { title = "Return Lost Souls", description = "Souls continue to pour into the Maw. \n\nTheir anima, our very lifeblood of the Shadowlands, is going with those souls to fuel the Jailer. You rescued me from the Maw. I see no reason you cannot pull more souls from that abyss. \n\nBring souls you rescue from the Maw to me and I shall see them put to better use. At least in Revendreth they have a chance of redemption.", objectives = "" }
WordHunterWoW_QuestEN[62868] = { title = "Return Lost Souls", description = "Souls continue to pour into the Maw. \n\nTheir anima, our very lifeblood of the Shadowlands, is going with those souls to fuel the Jailer. You rescued me from the Maw. I see no reason you cannot pull more souls from that abyss. \n\nBring souls you rescue from the Maw to me and I shall see them put to better use. At least in Revendreth they have a chance of redemption.", objectives = "" }
WordHunterWoW_QuestEN[62869] = { title = "Return Lost Souls", description = "Souls continue to pour into the Maw. \n\nTheir anima, our very lifeblood of the Shadowlands, is going with those souls to fuel the Jailer. You rescued me from the Maw. I see no reason you cannot pull more souls from that abyss. \n\nBring souls you rescue from the Maw to me and I shall see them put to better use. At least in Revendreth they have a chance of redemption.", objectives = "" }
WordHunterWoW_QuestEN[62870] = { title = "Souls for Sinfall", description = "Baine suffers within Torghast, but at least we know that he yet lives.\n\nRushing to his rescue would prove disastrous without a plan of attack. I will see to preparing one.\n\nIn the meantime, I suggest you bring the souls you rescued back to Sinfall. \n\nDenathrius's machinations have left the venthyr poorly provisioned, and Prince Renathal will require all the souls he can muster.", objectives = "" }
WordHunterWoW_QuestEN[62882] = { title = "Setting the Ground Rules", description = "Back to rescue more souls? How intrepid.\n\nThough I must say, your earlier escapade has drawn the Jailer's attention... and his ire. After all, none have successfully eluded him before. \n\nExcept for me.\n\nNow his forces are on high alert, hunting down any errant souls that the fabled Maw Walker may try to steal from him.\n\nIt has made things quite... inconvenient for me. If you and I are going to work together, we need to set a few ground rules.\n\nAnd you must be properly equipped.", objectives = "" }
WordHunterWoW_QuestEN[62883] = { title = "Keeper of Great Renown", description = "As you grow in renown across the Shadowlands, the Heart of the Forest shall grow with you. \n\nSeek out Laurel, our Keeper of Renown. She will acquaint you with the magic that we bestow upon our huntsmen and huntresses.", objectives = "" }
WordHunterWoW_QuestEN[62884] = { title = "The Forest Will Sing Your Name", description = "<Laurel picks out an intricate melody on deft fingers, and sings.>\n\nThe keeper of word and deed, am I, \nthe weaver of song and lore.\nBoons are granted as you grow in Renown,\nfulfilling the oaths we swore.\n\nEach deed that you do is a seed of strength,\nwhich will blossom in fabulous power.\nSpeak with me now and see what awaits,\nour magic is yours to discover!", objectives = "" }
WordHunterWoW_QuestEN[62890] = { title = "Who Shapes the Forest", description = "You have fulfilled your calling, Maw Walker, and brought calm to our forest.\n\nStay vigilant, for others will similarly call upon you in time.\n\nThe anima you have recovered will be of great use to the Heart of the Forest. Bring it to Zayhad. They will ensure it is safe until it is needed. You will find them deep in the roots of the Heart of the Forest.", objectives = "" }
WordHunterWoW_QuestEN[62891] = { title = "Into the Reservoir", description = "Groves wither, and our Queen weeps on barren soil. Anima, precious as water, now rare as snow. Our Queen gives of her own, shelters all beneath her boughs... but one tree does not a forest make.\n\nYour gift will be treasured and protected. Anima nourishes our roots, as hope nourishes our hearts. Ardenweald may yet flourish once more.", objectives = "" }
WordHunterWoW_QuestEN[62892] = { title = "Recover the Lost", description = "Anima and souls. Wind and rain. Ardenweald needs both to thrive.\n\nSouls meant for our boughs suffer in darkness. None escape the Maw... but you walk its shadows and return. You are their salvation.\n\nFlutterby shepherds the flock with care and compassion. Speak with her. Bring our lost souls home.", objectives = "" }
WordHunterWoW_QuestEN[62893] = { title = "Do What We Cannot", description = "Rumor has it that you've been to the Maw and back... and that you even made friends with a broker in there! \n\nSo many souls destined for Ardenweald are trapped in that dark realm. They need our help... and we need theirs! We can't cultivate the Heart of the Forest's magic without them.\n\nI know this is a lot to ask... but you may be our only hope of rescuing them. Please, venture into the Maw and do what we cannot. Ardenweald's future depends on it!", objectives = "" }
WordHunterWoW_QuestEN[62894] = { title = "Flutterback", description = "Baine suffers within Torghast, but at least we know that he yet lives.\n\nRushing to his rescue would prove disastrous without a plan of attack. I will see to preparing one.\n\nIn the meantime, I suggest you bring the souls you rescued back to Ardenweald.\n\nThey deserve respite after their harrowing ordeal in the Maw, and they will surely prove vital to the Night Fae's efforts.", objectives = "" }
WordHunterWoW_QuestEN[62895] = { title = "Track Selection", description = "", objectives = "" }
WordHunterWoW_QuestEN[62896] = { title = "Track Selection", description = "", objectives = "" }
WordHunterWoW_QuestEN[62897] = { title = "Recovered Souls", description = "Oh, I wonder what sorts of shapes these souls might take!\n\nWords can't express how grateful we are that you saved them. Not only have you brought an end to their torment, but they might be willing to aid us as well. \n\nGo speak with Zayhad. They haven't been able to tend the forest in a long while, but that might be about to change. This is all so exciting!", objectives = "" }
WordHunterWoW_QuestEN[62898] = { title = "The First New Growth", description = "Long have we lain dormant. With souls, with anima, we grow once more. \n\nA choice now awaits. How shall we grow? You may decide which flower blooms first.\n\nIn time, with more anima and willing souls, the whole garden will prosper. For now, a single blossom signals hope for the future.\n\nLady Moonberry will want to know of your choice. Seek her out once it is made.", objectives = "" }
WordHunterWoW_QuestEN[62899] = { title = "The Endless Forest", description = "Well, that's all I have for you! Whew! You've been on a whirlwind tour of things around here, haven't you? Up and down and slantways and even into the Maw! Your head must be practically spinning.\n\n<Flutterby giggles.>\n\nYou should check in with Lady Moonberry and let her know your training is complete!\n\nShe probably won't quiz you on what you've learned.\n\nProbably.", objectives = "" }
WordHunterWoW_QuestEN[62900] = { title = "A Conduit for Growth", description = "While our bond is powerful in and of itself, you can also enhance it through the use of conduits.\n\nConduits channel the anima between soulbinds in many different ways, increasing both of our potential in the process. They allow us to attune ourselves to each other's unique strengths.\n\nLet's use a few now. If they can further empower our bond, then they can aid us in protecting the forest.", objectives = "" }
WordHunterWoW_QuestEN[62902] = { title = "Anima is Power", description = "You did well, boss. Keep it up like that, right, and we just might 'ave a chance of survivin' this mess.\n\nKeep your eyes open, though. Word of success like this gets 'round and it's only a matter of time till uvvers come callin' for your 'elp.\n\nNow, right, all that anima you've recovered can be put to use 'round 'ere. Bring it down to Foreman Flatfinger. He'll ensure it stored away nice and secure.", objectives = "" }
WordHunterWoW_QuestEN[62903] = { title = "Into the Reservoir", description = "With anima in short supply these days, I've been entrusted to manage the reserves 'till they be needed.\n\nGo 'ead and deposit any anima you collect into the reservoir 'ere. \nBe assured, It'll be safe an' secure in me care.", objectives = "" }
WordHunterWoW_QuestEN[62904] = { title = "The Souls Plight", description = "Anima enables us to do many fings, but this sanctum can not function on anima alone. It'll require the combined effort of many souls workin' togeffer to unlock its full potential.\n\nThe Soul Warden is eager to be of service ever since you rescued 'im from the Maw. Your unique ability 'ta brin' souls from there will prove useful to him.\n\nWhy don't you go pay 'im a visit?", objectives = "" }
WordHunterWoW_QuestEN[62905] = { title = "Back into the Darkness", description = "Souls continue to pour into the Maw, and with them the anima that could help us.\n\nYou were able to rescue me from that place. Can I count on your strength to repeat the same trick?\nPlease, get us more willing souls so we can bolster this sanctum's power.\n\nSeek out what aid you can and do what we can't, Maw Walker. You are our last, best, hope.", objectives = "" }
WordHunterWoW_QuestEN[62914] = { title = "A Coalition of the Willing", description = "The good people of Revendreth continue to suffer under the oppression of Denathrius's loyalists. We must bolster our forces before we can move openly against our former Master.\n\nThe willing souls you recovered from the Maw will prove a boon in these trying times.\n\nGo to Foreman Flatfinger. He has been searching for assistance with building enhancements for our sanctum. Together, we will see Sinfall reach its full potential.", objectives = "" }
WordHunterWoW_QuestEN[62915] = { title = "Home Improvement", description = "I've been finkin' of a bit of ways we could improve the place, but since you brought in all of the anima and souls to do it, I fink you should be the one to decide which improvement we start on first.\n\nDon't get overwhelmed. As you bring in more anima and find more willin' souls, we'll be able to bring more capabilities to the place. For now, a single upgrade will fit the bill.", objectives = "" }
WordHunterWoW_QuestEN[62916] = { title = "Your Next Best Friend", description = "You looking for a new friend? Hoo-hoo!\n\nLots of stewards who are happy to be friend. Plus, current friend can take break! Maybe go to Cliffs of Respite, rest feet, eat cake...\n\n<Sika gets lost in a daydream.>\n\nHoo! Right!\n\nI call stewards. You make new friend!", objectives = "" }
WordHunterWoW_QuestEN[62917] = { title = "Shared Souls", description = "The power of the Harvesters flows through your mortal body. But you may wield even greater might by binding your soul to another.\n\nDoing so has no known drawbacks, but offers many advantages for both parties involved. \n\nThe Accuser will oversee the process. Meet her at the Forge of Bonds when you are ready.", objectives = "" }
WordHunterWoW_QuestEN[62918] = { title = "Binding Power", description = "The power of the Harvesters flows through your mortal body. But you may wield even greater might by binding your soul to another. \n\nTo soulbind with another is not an irrevocable bond. However, it is not to be entered into lightly.\nYou will experience one another's pasts. Your hopes, fears, dreams, your very memories--if any still linger. You will become kindred spirits in the truest sense.\n\nOnce complete, your connection will transcend physical space and make you stronger in more than mere brawn.", objectives = "" }
WordHunterWoW_QuestEN[62919] = { title = "Strengthening the Bond", description = "Do you feel it, too? Our connection is stronger than I imagined could be possible. \n\nI have been told that the bond will continue to grow over time, though we do have the ability to accelerate the process. \n\nSinfall needs our strength. Perhaps it is best we engage in this method now.", objectives = "" }
WordHunterWoW_QuestEN[62920] = { title = "A Conduit For Change", description = "While the powers from your bond are substantial, you may also strengthen the bond further through the use of conduits.\n\nConduits act to channel the energy of your soulbind into your form more directly, increasing your potential in many ways.\n\nUse the ones I have given you as a test of this power, but fear not--you will find others in your travels.", objectives = "" }
WordHunterWoW_QuestEN[62921] = { title = "Our True Purpose", description = "We are grateful for this partnership, Maw Walker. \n\nWith your help, Renathal will lead us into a new era, one that will see Revendreth reclaim its true purpose. \n\nReturn to him now so that the real work can begin.", objectives = "" }
WordHunterWoW_QuestEN[62928] = { title = "Blueprint: Ring of Warding", description = "<You have discovered plans for a defensive ward that may give your soulbinds an edge in the Path of Ascension.\n\nDactylis should be able to help you with crafting this piece of equipment.>", objectives = "" }
WordHunterWoW_QuestEN[62932] = { title = "Explore Torghast", description = "Baine is safe, but our other allies are still prisoners of the Jailer. They remain in grave peril.\n\nTorghast is a constantly changing place, shifting according to the will of its master. It may be impossible to track them through normal means.\n\nEnter its cell blocks and see what information you can find. Seek any clue that might lead us to our missing friends, and bring it back to me.", objectives = "" }
WordHunterWoW_QuestEN[62935] = { title = "Remnants of Hope", description = "I studied the key you brought back from Torghast, {name}.\n\nIt confirms that Jaina Proudmoore is still being held somewhere in the tower. However we do not know precisely where.\n\nCountless souls are captive inside that wretched place. A few may be intact, but many are shattered and broken.\n\nTake pity upon the remnants and free those you can. Perhaps they will be able to aid our search.", objectives = "" }
WordHunterWoW_QuestEN[62938] = { title = "Information for a Price", description = "We must continue our search for Jaina Proudmoore. I have a new strategy to suggest.\n\nSince arriving in Oribos, I have been approached by many of the brokers. Some ask questions, others offer help--for a price.\n\nYou have encountered others of their kind inside Torghast. They may possess information we can use, though I doubt they will part with it freely.\n\nSeek them out and appeal to their avarice. Offer to pay for whatever information they possess.", objectives = "" }
WordHunterWoW_QuestEN[62951] = { title = "Path of Ascension: Kleia", description = "Artemede has been personally training Kleia, running her through combat meditations and drills.\n\nShe has come far, and she is prepared to take on another trial in the Path of Ascension.\n\nReturn to the coliseum and guide her as her tactician so that she may reach victory.", objectives = "" }
WordHunterWoW_QuestEN[62952] = { title = "Path of Ascension: Pelagos", description = "Though combat is not his strong suit, Pelagos has been reading, meditating, and training to better himself on the Path.\n\nWe believe he is ready to seek victory.\n\nHe requests you by his side to help him strategize. He is stronger with the help of his friends.", objectives = "" }
WordHunterWoW_QuestEN[62953] = { title = "Path of Ascension: Mikanikos", description = "Mikanikos has been hard at work at the Eternal Forge, calibrating Bron and tuning his combat procedures.\n\nHe is confident in his recent changes, and requests permission to attempt another trial.\n\nEnter the Path with Mikanikos so that he may assess his goliath's strengths and weaknesses.", objectives = "" }
WordHunterWoW_QuestEN[62954] = { title = "Path of Ascension: Kalisthene", description = "Your soulbinds request your strategic mind in another trial.\n\nTheir sights this week are set on Kalisthene, that they may learn from the lessons her memory teaches.\n\nWhen you are able, report to Artemede to return to the Path of Ascension. Aid your soulbinds in defeating Kalisthene to prove their growth.", objectives = "" }
WordHunterWoW_QuestEN[62966] = { title = "Finding a Witness", description = "You have rescued two of our allies from Torghast, but Anduin and Thrall have yet to be found.\n\nThat tower's corridors are vast... seemingly endless. You could spend an eternity wandering those unholy halls.\n\nIn your expeditions, you have encountered many unfortunate prisoners. Perhaps one of them has seen or heard something that could guide our search.\n\nSeek out any captives that might have the information we need, {name}.", objectives = "" }
WordHunterWoW_QuestEN[62967] = { title = "Prison of the Forgotten", description = "I discovered an interesting item off the Warden you killed in the tower. \n\nBest not to ask how I know what you do and where you do it within the tower. Let's just say, I have my ways.\n\nBut this key could lead to something interesting within Torghast. Or something horrible. Most likely horrible.\n\nYou ought to explore a bit and see what it unlocks.", objectives = "" }
WordHunterWoW_QuestEN[62969] = { title = "Lest the Trail Go Cold", description = "From what the captive dredger told you, it seems Thrall has been taken deep into Torghast. The torments he is enduring must be unimaginable.\n\nWe need to learn where he is being held before the trail goes cold.\n\nThe tower is vast and perilous. Search where you are able. Bring back any clues you find.\n\nGo carefully, {name}. The Jailer's eye is upon you.", objectives = "" }
WordHunterWoW_QuestEN[62970] = { title = "Blueprint: Steward Mail Pouch", description = "<You have discovered plans for a steward sized pouch, perfect for carrying mail.\n\nDactylis should be able to help you with crafting this.>", objectives = "" }
WordHunterWoW_QuestEN[62971] = { title = "Blueprint: Gilded Abacus", description = "<You have discovered plans for a steward sized abacus, capable of calculating deposits and withdrawals at any distance.\n\nDactylis should be able to help you with crafting this.>", objectives = "" }
WordHunterWoW_QuestEN[62976] = { title = "Artisan Tool Belt", description = "<The tool belt has many pouches and loops, and is outfitted with many tools and materials. \n\nIt will allow your steward to not only assist you with crafting, but also carry common trade goods.>", objectives = "" }
WordHunterWoW_QuestEN[62981] = { title = "Blueprint: Artisan Tool Belt", description = "<You have discovered plans for a well made tool belt, a perfect gift for your favorite steward.\n\nDactylis should be able to help you with crafting this.>", objectives = "" }
WordHunterWoW_QuestEN[62984] = { title = "Blueprint: Medallion of Service", description = "<You have discovered a donation plan to earn Medallions of Service, the respected Kyrian symbol of commendation. By donating materials to your sanctum, you can receive Medallions to enter the Path.\n\nDactylis should be able to help you facilitate this.>", objectives = "" }
WordHunterWoW_QuestEN[62985] = { title = "Dredging up a New Look", description = "If ye look around the muck pool I am sure you will find an armor dye. It might be nice to have the option to dye me belt a different color.", objectives = "" }
WordHunterWoW_QuestEN[62986] = { title = "Blueprint: Vesper of Calling", description = "<You have discovered plans for a single use chime, capable of summoning courier Hermestes anywhere in the Shadowlands.\n\nDactylis should be able to help you with crafting this chime.>", objectives = "" }
WordHunterWoW_QuestEN[62987] = { title = "[DNT] Test Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[62995] = { title = "Spiritforged Aegis", description = "<As you pick up the shield, your hands seem to lightly bounce off of it with ease.\n\nThis should help your soulbinds take a few hits in the Path of Ascension.>", objectives = "" }
WordHunterWoW_QuestEN[62996] = { title = "Vial of Lichfrost", description = "<The vial, filled with a frosty liquid, is chill to the touch.\n\nThis should hinder your soulbinds' opponents in the Path of Ascension.>", objectives = "" }
WordHunterWoW_QuestEN[62997] = { title = "Blueprint: Vial of Lichfrost", description = "<You have discovered plans for a concoction that may freeze opponents in the Path of Ascension.\n\nDactylis should be able to help you with crafting this piece of equipment.>", objectives = "" }
WordHunterWoW_QuestEN[62998] = { title = "Ring of Warding", description = "<You place down the ring and are knocked back by a protective bubble.\n\nThis should force your soulbinds' opponents away from an area in the Path of Ascension.", objectives = "" }
WordHunterWoW_QuestEN[62999] = { title = "Champion: Croman", description = "", objectives = "" }
WordHunterWoW_QuestEN[63000] = { title = "Blueprint: Charm of Focus", description = "<You have discovered plans for a charm that seems to energize your soulbinds in the Path of Ascension.\n\nDactylis should be able to help you with crafting this charm.>", objectives = "" }
WordHunterWoW_QuestEN[63002] = { title = "Dangerous to Go Alone", description = "I trust you know well all that Elysian Hold can provide, but that alone will not be enough to thwart Denathrius.\n\nYou must have a soulbind to aid you, Maw Walker.\n\nSeek out Soulguide Daelia in the chamber below. She has prepared for the ritual.", objectives = "" }
WordHunterWoW_QuestEN[63003] = { title = "Collective Soul", description = "You know conflict as well as any soldier in Maldraxxus, Maw Walker. But we do not fight alone.\n\nThere is great wisdom in leaning on the strengths of your allies. That is the Maldraxxi way.\n\nSpeak to Plague Deviser Marileth. He will show you how to soulbind and best reap its benefits.", objectives = "" }
WordHunterWoW_QuestEN[63006] = { title = "For Queen and Grove!", description = "You have already done so much to help us since you first step foot in our realm! I'm so glad you decided to join our covenant.\n\nThere will be plenty of time for reminiscing later, though. You have an audience with the Winter Queen herself to go to!\n\nLet's not keep her waiting!", objectives = "" }
WordHunterWoW_QuestEN[63008] = { title = "The Forge of Bonds", description = "To best serve the court and the forest, you must bond with another fae.\n\nIt is an ancient ritual, one which will grant you great strength to face the many trials ahead.\n\nFlutterby below will guide you further.", objectives = "" }
WordHunterWoW_QuestEN[63022] = { title = "Rule 6 Addendum: Save Me At Any Cost", description = "You! You, there! Wait!\n\nYou are the infamous Maw Walker, yes? I have heard much about you.\n\nPlease, help me! My compatriots have been drained of their essence. The Mawsworn are using it to fashion their foul runes.\n\nOne of them bound me here, and I am sure to be next on his list. You must slay him in order to free me!\n\nI can make it worth your while. I have collected a fair amount of stygia during my time in the Maw. It is yours, all of it, if you save me!", objectives = "" }
WordHunterWoW_QuestEN[63029] = { title = "The Highlord Calls", description = "We have received word from Highlord Fordragon urging you to return to him in Oribos at once.\n\nAll I know is it pertains to the Maw.\n\nYou should go to him with haste. Anything involving that dark place must be our top priority.", objectives = "" }
WordHunterWoW_QuestEN[63030] = { title = "The Highlord Calls", description = "Highlord Fordragon needs you in Oribos right away!\n\nI'm not sure of the details, but the messenger mentioned the Maw.\n\nYou should go to him as soon as you can. If the Maw is involved, it must be serious!", objectives = "" }
WordHunterWoW_QuestEN[63031] = { title = "Acquisition: Crystallized Stygia", description = "<This shard of crystal appears to have broken off of one of the massive crystalline structures throughout the area. It thrums with untapped energy.\n\nVe'nari would likely be interested in any of these shards you come across.>", objectives = "" }
WordHunterWoW_QuestEN[63032] = { title = "The Highlord Calls", description = "Highlord Fordragon has requested your presence in Oribos.\n\nWe know only that it involves the Maw.\n\nGo to him, and show him that the Maldraxxi will never falter. Even in the face of that dark place.", objectives = "" }
WordHunterWoW_QuestEN[63033] = { title = "The Highlord Calls", description = "A messenger from Oribos has informed us that Highlord Fordragon has requested your presence in Oribos.\n\nIt seems it pertains to the Maw... and the Master's plans, no doubt.\n\nI suggest you heed his summons, Maw Walker. We must leave nothing to chance.", objectives = "" }
WordHunterWoW_QuestEN[63034] = { title = "The Elysian Fields", description = "You must travel to Bastion, eternal home of the winged kyrian.\n\nDo not be fooled by their golden fields and shining spires--the kyrian have been weakened by the great anima drought, and face the brink of civil war against their own fallen brethren.\n\nThey will benefit greatly from your aid. Seek one known as Kalisthene in your new sanctum, Elysian Hold. She will direct you further.\n\nPathscribe Roh-Avonavi in the Ring of Transference above can provide transport.", objectives = "" }
WordHunterWoW_QuestEN[63035] = { title = "A Fresh Blade", description = "Though they were once unified in defending the Shadowlands, the houses of Maldraxxus have turned against each other.\n\nTheir armies clash within their realm and have even orchestrated an assault on Bastion. Now only the Necrolords remain loyal to the Primus.\n\nSpeak to Secutor Mevix at the Seat of the Primus in Maldraxxus. His tactical skills will ensure you are sent where you are most needed.\n\nPathscribe Roh-Avonavi in the Ring of Transference above can provide you with transportation.", objectives = "" }
WordHunterWoW_QuestEN[63036] = { title = "Restoring Balance", description = "Ardenweald is crucial to the cycle of rebirth for nature spirits that enter their realm.\n\nUnfortunately, the anima drought has led to the loss of entire groves--souls that will never complete their cycle.\n\nNow foes seek to destroy what remains of the once tranquil forests, threatening the already beleaguered Court of Night. \n\nLady Moonberry of the Court has requested aid. Pathscribe Roh-Avonavi in the Ring of Transference above can provide transport.", objectives = "" }
WordHunterWoW_QuestEN[63037] = { title = "Dark Aspirations", description = "Prince Renathal has started a daring rebellion against his father, the nefarious Sire Denathrius who betrayed us all by pouring Revendreth's vast anima stores into the Maw.\n\nYou must travel to Revendreth and aid Renathal in his efforts. He is our best hope at restoring Revendreth to order.\n\nPathscribe Roh-Avonavi in the Ring of Transference above can provide transport.", objectives = "" }
WordHunterWoW_QuestEN[63038] = { title = "Guaranteed Delivery", description = "<The broker appears to be from Cartel Ve. Perhaps they were once an associate of Ve'nari.\n\nClutched in their hand is a list of items and a containment orb.\n\nFinishing this broker's task and sending the items back to Ve'nari will surely earn you some compensation.>", objectives = "" }
WordHunterWoW_QuestEN[63039] = { title = "A Monument to Vengeance", description = "<Corpses of Ebon Blade knights litter the Crucible of the Damned, displaying the aftermath of your first foray into this desolate place.\n\nTheir sacrifice should not be forgotten.>", objectives = "" }
WordHunterWoW_QuestEN[63040] = { title = "Guaranteed Delivery", description = "<The broker appears to be from Cartel Ve. Perhaps they were once an associate of Ve'nari.\n\nClutched in their hand is a list of items and a containment orb.\n\nFinishing this broker's task and sending the items back to Ve'nari will surely earn you some compensation.>", objectives = "" }
WordHunterWoW_QuestEN[63041] = { title = "Short-Supply Reward", description = "", objectives = "" }
WordHunterWoW_QuestEN[63043] = { title = "Sundered Souls", description = "The traps... they didn't affect us before. Too many souls... escaping. \n\nThey... made new traps... tear apart fleeing souls...\n\n...too late for me. Destroy... so others might escape!", objectives = "" }
WordHunterWoW_QuestEN[63045] = { title = "Feed Your Soul", description = "They... drained my anima... to fuel their ritual...\n\nSouls of great power are brought here... to this altar... and sacrificed to conjure unspeakable horrors bound to the Jailer.\n\nI was powerful once... Imbue me with the anima they stole... and I can be powerful again.\n\nThen, together... we will destroy the one who leads their efforts.", objectives = "" }
WordHunterWoW_QuestEN[63046] = { title = "The End and the Beginning", description = "I am so happy you restored our connection to the Queen's Conservatory!\n\nIn light of this accomplishment, the Winter Queen has requested you attend her at the Grove of Awakening! \n\nYou will see first hand the purpose of Ardenweald and gain a greater understanding of our sacred charge before you too, take it upon yourself.\n\nHurry! Don't keep everyone waiting!", objectives = "" }
WordHunterWoW_QuestEN[63047] = { title = "Acquisition: Runeforged Shackles", description = "<The chains here are carved with domination runes, imbuing them with the magic needed to subdue the most powerful of the Mawsworn's prisoners.\n\nNo doubt Ve'nari could find some use in studying these runes.>", objectives = "" }
WordHunterWoW_QuestEN[63050] = { title = "Acquisition: Blazing Ingots", description = "<The runesmiths have imbued this ingot with an enchantment that causes it to burn with inextinguishable flames. \n\nIt is likely that this metal is used to empower the Mawsworn protectors of Zovaal's Cauldron. \n\nBringing some samples of this ore to Ve'nari could aid her attempts at unlocking the Jailer's secrets.>", objectives = "" }
WordHunterWoW_QuestEN[63051] = { title = "Trust Issues", description = "Ah, Maw Walker! Allow me to introduce myself. I am Ve'rayn. I deal with assets and liabilities for Cartel Ve.\n\nI have heard that you are able to freely travel between Oribos and the Maw, a place of great interest to my cartel.\n\nWould you mind if I ask you a few questions about it?\n\nYou will, of course, be properly compensated for your time and information. They are the most valuable of commodities, after all.", objectives = "" }
WordHunterWoW_QuestEN[63052] = { title = "Step of Faith", description = "Our ascended fly across Bastion with ease, ensuring safety and prosperity across the realm.\n\nLong ago we established a network of anima gateways to help our aspirants, goliaths, and stewards traverse our realm more quickly.\n\nGo forth and activate the network once more, so that you too may be wherever you are needed in the mere blink of an eye.", objectives = "" }
WordHunterWoW_QuestEN[63053] = { title = "At a Moment's Notice", description = "No longer must you take a larion across Bastion, Maw Walker.\n\nWith our gateways active once more, you shall enjoy instantaneous travel wherever you are needed.\n\nDo note that you must still utilize a larion to return to Oribos or travel to the other realms.\n\nGive it a try and see for yourself.", objectives = "" }
WordHunterWoW_QuestEN[63054] = { title = "Strength in Numbers", description = "Every soul in Maldraxxus has the potential for greatness, and we will need all we can muster if we hope to restore order to the Shadowlands.\n\nWith this addition to the sanctum, we can mobilize our forces and give them the chance to prove themselves on the field of battle.\n\nSeek out Merick Feldscar. He will see to the deployment of our soldiers.", objectives = "" }
WordHunterWoW_QuestEN[63055] = { title = "Powering the Portals", description = "The Primus once maintained a network of portals that linked the necropoli of Maldraxxus directly to the Seat of the Primus. The lack of anima and recent destruction of many of the necropoli have rendered those connections inactive.\n\nWith the anima you have provided us, we have managed to reconnect one of those portals. You shall once more be able to travel to one of our great necropoli... assuming it still exists.", objectives = "" }
WordHunterWoW_QuestEN[63056] = { title = "Sanctum Upgrade: Mirror Network", description = "Right. So, we got a Scroll of Dark Empowerment ready for youz that should manifest 'em mirror frames for you. Pre'y standard work.\n\nThing is, after you going to need a proper mirror maker to get 'em up an' workin'. \n\nPrince Renathal might know a fang with the right skills. Best speak with him.", objectives = "" }
WordHunterWoW_QuestEN[63057] = { title = "Restoring Power", description = "Anima is power, {name}! \n\nWhen it was plentiful, the Primus ensured that his soldiers received all of the anima they required.\n\nNow, in the midst of this drought, the Maldraxxi fight amongst themselves for any anima they can find. \n\nAs our stockpile of anima grows, we can distribute it throughout Maldraxxus. It falls to us Necrolords to carry out the Primus's duty in his absence. \n\nSpeak to Yondare Hex. She will show you how to do so.", objectives = "" }
WordHunterWoW_QuestEN[63058] = { title = "Abominable Stitching and Me", description = "Constructs have formed the backbone of Maldraxxi armies in more wars than anyone can count. A well-constructed body can turn any soul into a potent frontline weapon.\n\nThere is an old abominable stitching table outside of the sanctum that could be used to build our own constructs. With the anima you've secured for our covenant, we should be able to restore it.\n\nReport to Miggsie once the work has begun. You can find her at Butchers Block.", objectives = "" }
WordHunterWoW_QuestEN[63059] = { title = "Blink of an Eye", description = "This was once a long tauralus ride, but not anymore!\n\nBy simply stepping through this portal, you can now journey to the House of Eyes in an instant.\n\nThe House of Eyes may not be what it once was, but valuable allies can still be found in the ruins of their once great necropolis.\n\nTravel there now to test the portal's functionality.", objectives = "" }
WordHunterWoW_QuestEN[63060] = { title = "Rule 6 Footnote: Don't Forget Anything", description = "In the Maw, you must never forget to take everything with you.\n\nMany things crawl within the Beastwarrens. The runes you brought back indicate that something of interest may have been left behind by the brokers who were taken there.\n\nSee if you can find it.", objectives = "" }
WordHunterWoW_QuestEN[63061] = { title = "Helping Hand", description = "We may have the stitching table, but it won't do us any good without someone to use it... someone like Rathan!\n\nI've heard that he's already gone to speak with the Necrolords. Perhaps if you meet with him, you could ask him to set up shop here.\n\nWith his assistance, we could be stitching abominations together in no time!", objectives = "" }
WordHunterWoW_QuestEN[63062] = { title = "Torment for the Taking", description = "<A broker device has been abandoned here. It seems like it was being used to siphon energy from rifts of soul energy that have erupted in the area.\n\nThe brokers surely would not have sought to harness this energy if it didn't have a use. Perhaps you should finish what they started.>", objectives = "" }
WordHunterWoW_QuestEN[63063] = { title = "Sanctum Upgrade: Mirror Network", description = "We got a Scroll of Dark Empowerment ready for youz that should manifest 'em mirror frames for you. Pre'y standard work.\n\nOnce you do the conjurin', then ol' Laurent should be able to work 'is magic as it were. Right proper glass guy he is.", objectives = "" }
WordHunterWoW_QuestEN[63064] = { title = "Sanctum Upgrade: Command Table", description = "We got a Scroll of Dark Empowerment ready for youz that should manifest a command table for you. Not just any command table, but one of 'em magic ones that lets you issue orders from afar.\n\nTactician Sakaa insisted she be your wing for that one. Never much trusted 'em wings as they ain't too kind to us dredgers but put 'em in charge of war and even Maldraxxus flinches.", objectives = "" }
WordHunterWoW_QuestEN[63065] = { title = "Sanctum Upgrade: The Ember Court", description = "We got a Scroll of Dark Empowerment ready for youz that should provide you with enough resources to get one of 'em fancy parties the fangs are fond of.\n\nThe Mad Duke is the one you should chat with 'bout this one. He used to run all the court parties back before he got roasted.", objectives = "" }
WordHunterWoW_QuestEN[63066] = { title = "Sanctum Upgrade: Anima Conductor", description = "Right. So we got all this anima you been collecting.\n\nThing is, all that anima originally got squeezed out of the other realms. The Master, he was big on drainin' anything that weren't him. \n\nSo, we set up a Scroll of Dark Empowerment for you on the lower level. Should conjure somefin' strong enough for you to channel anima back into the Shadowlands, by way of Revendreth Wards. \n\nSeems to me there'd be some fringe benefits from somefin like that.", objectives = "" }
WordHunterWoW_QuestEN[63067] = { title = "Root Restoration", description = "Anima once flowed freely, but we have been thirsting. You bring us nourishment in times of trouble. We grow.\n\nWe may now help others and share our bounty.\n\nWatch our growth, then speak with Sesselie. They will guide you further.", objectives = "" }
WordHunterWoW_QuestEN[63068] = { title = "Settling Disputes", description = "In my search to find kyrian that would fit our purposes here, I have landed on two in particular -- Pelodis and Nemea.\n\nHowever, the two are involved in quite the rivalry, and struggle to focus their attention elsewhere. I propose that you aid them in settling their dispute so that they may focus on the task at hand.\n\nI doubt they shall work together, however, so you will need to pick one to aid us.", objectives = "" }
WordHunterWoW_QuestEN[63069] = { title = "What They Know", description = "<It looks like this broker was gathering information before he met his unfortunate end. Ve'nari would likely be very interested in what he found.\n\nUnfortunately, his notes look to have been scattered far and wide by the local beasts.>", objectives = "" }
WordHunterWoW_QuestEN[63072] = { title = "Acquisition: Stygic Ore", description = "<The rock columns in this area are teeming with veins of a glowing, otherworldly metal. \n\nThe Mawsworn have employed souls to mine it, but it looks like they didn't last long.\n\nVe'nari could certainly find use for some of this ore, if you can manage to mine it.>", objectives = "" }
WordHunterWoW_QuestEN[63073] = { title = "A Mycelial Network", description = "Anima flows into the deepest of roots, feeding the mushrooms. Long has it been since we used the rings to travel across Ardenweald.\n\nRestore our connection to the mushroom network.", objectives = "" }
WordHunterWoW_QuestEN[63100] = { title = "Misery's Company", description = "<The husk of this poor soul has been stripped of everything, down to near nonexistence.\n\nThis suffering cannot continue. Save the others from their misery.>", objectives = "" }
WordHunterWoW_QuestEN[63132] = { title = "Constellan Writ", description = "<The writing on the scroll changes rapidly. It likely holds ancient secrets that Ve'nari may find intriguing.>", objectives = "" }
WordHunterWoW_QuestEN[63133] = { title = "Shifting Cryptogram", description = "<The ever-shifting facets of the cube are inlaid with runes you cannot read. \n\nVe'nari may have an interest in it.>", objectives = "" }
WordHunterWoW_QuestEN[63134] = { title = "Mawsworn Patrol Map", description = "<A diagram outlining Mawsworn movement patterns has been scrawled onto the parchment.\n\nVe'nari may find this useful.>", objectives = "" }
WordHunterWoW_QuestEN[63135] = { title = "Coldheart Flight Routes", description = "<These diagrams contain detailed information concerning the patrols of the Mawsworn Kyrian. \n\nVe'nari would relish this knowledge.>", objectives = "" }
WordHunterWoW_QuestEN[63136] = { title = "Chaotic Runes", description = "<A series of unintelligible lines has been inscribed onto ancient parchment. \n\nVe'nari would value this.>", objectives = "" }
WordHunterWoW_QuestEN[63137] = { title = "Puzzling Cryptogram", description = "<The markings on each side of the cube periodically switch positions. \n\nVe'nari will be interested in this.>", objectives = "" }
WordHunterWoW_QuestEN[63140] = { title = "Worn Obleron Etching", description = "<The etching on the crumbling manuscript hints at the origins of the Maw. \n\nVe'nari would be fascinated by this.>", objectives = "" }
WordHunterWoW_QuestEN[63142] = { title = "Soulforge Blueprints", description = "<As you scan the documents in your possession, you realize that they outline the horrific methods by which souls can be forged into armaments. \n\nVe'nari would be intrigued by this.>", objectives = "" }
WordHunterWoW_QuestEN[63145] = { title = "Shadebound Testimonial", description = "<These appear to be the pain-induced ramblings of a tormented Torghast prisoner. \n\nVe'nari would find value in this.>", objectives = "" }
WordHunterWoW_QuestEN[63152] = { title = "Venthyr Concordat", description = "<This appears to be an encoded correspondence between a venthyr noble and a Mawsworn lieutenant.\n\nPerhaps Ve'nari can decipher it.>", objectives = "" }
WordHunterWoW_QuestEN[63153] = { title = "Discarded Torments", description = "<The torn and faded pages depict punishments deemed too lenient and therefore disposed of. \n\nVe'nari may wish to study them.>", objectives = "" }
WordHunterWoW_QuestEN[63154] = { title = "Shadehound Armor Plating", description = "<The salvaged piece of plating is covered in runes that slowly shift and flow across its surface. \n\nVe'nari would be interested in studying this.>", objectives = "" }
WordHunterWoW_QuestEN[63155] = { title = "Indecipherable Map", description = "<The map is covered in scribbles and notations that hint at realms unknown. \n\nVe'nari would likely find this fascinating.>", objectives = "" }
WordHunterWoW_QuestEN[63156] = { title = "Mawsworn Shackles", description = "<The shackles are part tangible, part ethereal. They scream into your mind when held. \n\nJust the sort of thing Ve'nari might be looking for.>", objectives = "" }
WordHunterWoW_QuestEN[63157] = { title = "Box of Torments", description = "<The insidious music box hums an endlessly repeating set of dissonant chords. \n\nVe'nari may find it melodious.>", objectives = "" }
WordHunterWoW_QuestEN[63158] = { title = "Wailing Coin", description = "<The odd coin appears to be from a forgotten time. As you hold it, you are haunted by the cries of suffering souls. \n\nVe'nari may recognize the coin's value.>", objectives = "" }
WordHunterWoW_QuestEN[63159] = { title = "Words of the Warden", description = "<As far as you can tell, this is a faded segment of a desiccated journal scrawled in Warden Korrath's hand. \n\nVe'nari would find value in this.>", objectives = "" }
WordHunterWoW_QuestEN[63160] = { title = "Korrath's Grimoire: Aleketh", description = "<These appear to be a collection of pages from a tome studying the denizens of the Maw in unsettling detail. \n\nNo doubt Ve'nari would wish to peruse this.>", objectives = "" }
WordHunterWoW_QuestEN[63161] = { title = "Korrath's Grimoire: Belidir", description = "<These appear to be a collection of pages from a tome studying the denizens of the Maw in unsettling detail. \n\nNo doubt Ve'nari would wish to peruse this.>", objectives = "" }
WordHunterWoW_QuestEN[63162] = { title = "Korrath's Grimoire: Gyadrek", description = "<These appear to be a collection of pages from a tome studying the denizens of the Maw in unsettling detail. \n\nNo doubt Ve'nari would wish to peruse this.>", objectives = "" }
WordHunterWoW_QuestEN[63163] = { title = "Tormentor's Notes", description = "<The crumpled and singed page describes the Mawsworn's preferred methods of interrogation and subjugation. \n\nVe'nari may find it of interest.>", objectives = "" }
WordHunterWoW_QuestEN[63164] = { title = "Mawsworn Orders", description = "<The document outlines a set of orders issued by Warden Korrath. \n\nVe'nari would find this illuminating.>", objectives = "" }
WordHunterWoW_QuestEN[63166] = { title = "A Shadowed Fate", description = "The Mawsworn... torture and torment souls within Ruin's Cradle.\n\nI... barely escaped, but I'm afraid I won't last long.\n\nTheir twisted rituals... breaking souls to serve as wretched shades. \n\nSpare them this fate!", objectives = "" }
WordHunterWoW_QuestEN[63168] = { title = "Path of Ascension: Echthra", description = "Your soulbinds request your strategic mind in another trial.\n\nTheir sights this week are set on Echthra, that they may learn from the lessons her memory teaches.\n\nWhen you are able, report to Artemede to return to the Path of Ascension. Aid your soulbinds in defeating Echthra to prove their growth.", objectives = "" }
WordHunterWoW_QuestEN[63169] = { title = "Path of Ascension: Alderyn and Myn'ir", description = "Your soulbinds request your strategic mind in another trial.\n\nTheir sights this week are set on Alderyn and Myn'ir, that they may learn from the lessons their memories teach.\n\nWhen you are able, report to Artemede to return to the Path of Ascension. Aid your soulbinds in defeating Alderyn and Myn'ir to prove their growth.", objectives = "" }
WordHunterWoW_QuestEN[63170] = { title = "Path of Ascension: Nuuminuuru", description = "Your soulbinds request your strategic mind in another trial.\n\nTheir sights this week are set on Nuuminuuru, that they may learn from the lessons their memory teaches.\n\nWhen you are able, report to Artemede to return to the Path of Ascension. Aid your soulbinds in defeating Nuuminuuru to prove their growth.", objectives = "" }
WordHunterWoW_QuestEN[63171] = { title = "Path of Ascension: Craven Corinth", description = "Your soulbinds request your strategic mind in another trial.\n\nTheir sights this week are set on Craven Corinth, that they may learn from the lessons his memory teaches.\n\nWhen you are able, report to Artemede to return to the Path of Ascension. Aid your soulbinds in defeating Craven Corinth to prove their growth.", objectives = "" }
WordHunterWoW_QuestEN[63172] = { title = "Path of Ascension: Splinterbark Nightmare", description = "Your soulbinds request your strategic mind in another trial.\n\nTheir sights this week are set on Splinterbark Nightmare, that they may learn from the lessons its memory teaches.\n\nWhen you are able, report to Artemede to return to the Path of Ascension. Aid your soulbinds in defeating Splinterbark Nightmare to prove their growth.", objectives = "" }
WordHunterWoW_QuestEN[63173] = { title = "Path of Ascension: Thran'tiok", description = "Your soulbinds request your strategic mind in another trial.\n\nTheir sights this week are set on Thran'tiok, that they may learn from the lessons her memory teaches.\n\nWhen you are able, report to Artemede to return to the Path of Ascension. Aid your soulbinds in defeating Thran'tiok to prove their growth.", objectives = "" }
WordHunterWoW_QuestEN[63174] = { title = "Path of Ascension: Mad Mortimer", description = "Your soulbinds request your strategic mind in another trial.\n\nTheir sights this week are set on Mad Mortimer, that they may learn from the lessons his memory teaches.\n\nWhen you are able, report to Artemede to return to the Path of Ascension. Aid your soulbinds in defeating Mad Mortimer to prove their growth.", objectives = "" }
WordHunterWoW_QuestEN[63175] = { title = "Path of Ascension: Athanos", description = "Your soulbinds request your strategic mind in another trial.\n\nTheir sights this week are set on Athanos, that they may learn from the lessons his memory teaches.\n\nWhen you are able, report to Artemede to return to the Path of Ascension. Aid your soulbinds in defeating Athanos to prove their growth.", objectives = "" }
WordHunterWoW_QuestEN[63176] = { title = "Path of Ascension: Azaruux", description = "Your soulbinds request your strategic mind in another trial.\n\nTheir sights this week are set on Azaruux, that they may learn from the lessons their memory teaches.\n\nWhen you are able, report to Artemede to return to the Path of Ascension. Aid your soulbinds in defeating Azaruux to prove their growth.", objectives = "" }
WordHunterWoW_QuestEN[63179] = { title = "Drowned and Torn Asunder", description = "Maw Walker! I am relieved to see you in this place.\n\nA dark sect of kyrian who have allied themselves with the Maw stole my brothers and sisters from their posts in Bastion. They turned us over to a foul sea witch, the likes of which I've never seen.\n\nThis... Helya, I believe they called her... seems determined to break us so that we might also join her ranks.\n\nPlease, if you can, save my brethren.", objectives = "" }
WordHunterWoW_QuestEN[63181] = { title = "Path of Ascension: Artemede's Challenge", description = "Are you prepared for a challenge, {name}?\n\nIt seems Pelagos has been struggling with his trials. I believe, with your guidance, some extra training on the Path is just what he needs!\n\nAthanos has many lessons to teach. With your aid, Pelagos can achieve victory and new experience to meditate on.", objectives = "" }
WordHunterWoW_QuestEN[63182] = { title = "Path of Ascension: Artemede's Challenge", description = "Are you prepared for a challenge, {name}?\n\nPelagos's time spent in Ardenweald taught him many lessons. I would like to witness what he has learned.\n\nA trial against Nuuminuuru should allow him this chance. With your aid, Pelagos can achieve victory and new experience to meditate on.", objectives = "" }
WordHunterWoW_QuestEN[63184] = { title = "Path of Ascension: Artemede's Challenge", description = "Are you prepared for a challenge, {name}?\n\nMikanikos has requested an additional trial to train Bron. Splinterbark Nightmare's memory was captured with the help of his praetors, and should prove a worthy challenge for his goliath.\n\nWith your guidance, Mikanikos and Bron can overcome another trial.", objectives = "" }
WordHunterWoW_QuestEN[63185] = { title = "Path of Ascension: Artemede's Challenge", description = "Are you prepared for a challenge, {name}?\n\nKleia is ready for another challenge. She is hungry to get back to the Path so she may exercise her new abilities further.\n\nEchthra's memory shall provide her with new lessons. With your aid, Kleia can overcome this challenge and incorporate its lessons into her eternal training.", objectives = "" }
WordHunterWoW_QuestEN[63186] = { title = "Path of Ascension: Artemede's Challenge", description = "Are you prepared for a challenge, {name}?\n\nKleia is ready for another challenge. She is hungry to get back to the Path so she may exercise her new abilities further.\n\nIf she is to bear souls across the veil, she will need be prepared to contend against devourers like Azaruux. With your aid, Kleia can overcome this challenge and incorporate its lessons into her eternal training.", objectives = "" }
WordHunterWoW_QuestEN[63187] = { title = "Path of Ascension: Artemede's Challenge", description = "Are you prepared for a challenge, {name}?\n\nMikanikos has requested an additional trial to train Bron. Mad Mortimer's memory should prove a good challenge, as he and Mikanikos share a mind with a passion to further their research.\n\nWith your guidance, Mikanikos and Bron can overcome another trial.", objectives = "" }
WordHunterWoW_QuestEN[63188] = { title = "Path of Ascension: Artemede's Challenge", description = "Are you prepared for a challenge, {name}?\n\nThenios has requested a Trial of Wisdom to exercise your strategic mind, as well as your soulbinds' abilities.\n\nA trial against Alderyn and Myn'ir shall suffice. Let us see you and your soulbinds can do.", objectives = "" }
WordHunterWoW_QuestEN[63189] = { title = "Path of Ascension: Artemede's Challenge", description = "Are you prepared for a challenge, {name}?\n\nThenios has requested a Trial of Wisdom to exercise your strategic mind, as well as your soulbinds' abilities.\n\nA trial against Thran'tiok shall suffice. Let us see you and your soulbinds can do.", objectives = "" }
WordHunterWoW_QuestEN[63190] = { title = "Path of Ascension: Artemede's Challenge", description = "Are you prepared for a challenge, {name}?\n\nThough most kyrian have their preferences, every kyrian must learn to fight with a multitude of weapons and equipment. This allows them to keep both their minds sharp and their muscles and movements honed.\n\nLet us see how your soulbinds fare against the memory of Craven Corinth while utilizing the Ring of Warding.", objectives = "" }
WordHunterWoW_QuestEN[63191] = { title = "Path of Ascension: Artemede's Challenge", description = "Are you prepared for a challenge, {name}?\n\nThough most kyrian have their preferences, every kyrian must learn to fight with a multitude of weapons and equipment. This allows them to keep both their minds sharp and their muscles and movements honed.\n\nLet us see how your soulbinds fare against the memory of Kalisthene while utilizing the Spiritforged Aegis.", objectives = "" }
WordHunterWoW_QuestEN[63192] = { title = "Path of Ascension: Trial of Humility", description = "Are you prepared for a challenge, {name}?\n\nMany kyrian struggle with their trials of humility at some point along their path. It is important to remember that we can always be learning and improving, no matter how far we have come. But as we continue training, we can overcome more obstacles than before.\n\nIt is time for your soulbinds to be reminded of this lesson. Let us witness you all succeed in a Trial of Humility.", objectives = "" }
WordHunterWoW_QuestEN[63206] = { title = "Soulless Husks", description = "Some of the Mawsworn begin as inanimate suits of armor, forged by the stygian smiths of Zovaal's Cauldron. Once fashioned, they await infusion of a decrepit shade to complete their genesis.\n\nIt is at this time they are the most vulnerable, and so it is then you should strike.\n\nThe hammers wielded by the Mawsworn runesmiths hold the power to break as well as they shape. Procure one of them and smash our foes to dust before they can rise against us.", objectives = "" }
WordHunterWoW_QuestEN[63208] = { title = "The Next Step", description = "Your efforts have not gone unnoticed, but there are other realms that still require your aid.\n\nConsider the next step in your journey, mortal.", objectives = "" }
WordHunterWoW_QuestEN[63209] = { title = "Furthering the Purpose", description = "There are realms which still require your aid, mortal.\n\nYou must journey to one of their realms and ensure they stand strong.\n\nWhere will you go next?", objectives = "" }
WordHunterWoW_QuestEN[63210] = { title = "The Last Step", description = "Just one realm remains which requires your aid, mortal.\n\nSpeak with me when you are ready, and I shall inform you further.\n\nSuch is the Purpose.", objectives = "" }
WordHunterWoW_QuestEN[63211] = { title = "Report to Adrestes", description = "You have chosen well.\n\nThe Kyrian have long ferried souls across the veil into the Shadowlands, ensuring a steady supply of anima for all the realms.\n\nTheir sacred purpose must be kept strong. Speak with Polemarch Adrestes and begin your future with your covenant.", objectives = "" }
WordHunterWoW_QuestEN[63212] = { title = "Report to Mevix", description = "You have chosen well.\n\nThe Necrolords, eternal protectors of the Shadowlands, must remain strong to ensure we may continue to fulfill the Purpose.\n\nAid them as best you can. Speak with Secutor Mevix and begin your future with your covenant.", objectives = "" }
WordHunterWoW_QuestEN[63213] = { title = "Naladu the Elder", description = "<Noko breathes in slowly.>\n\nThe stage manager says he cannot find my flute anywhere.\n\nThe last time this happened, one of the rowdy roadies had run off with.\n\nYou can find those troublesome dredgers causing trouble around the party.\n\nRetrieve my flute from them and I will play for your guests.", objectives = "" }
WordHunterWoW_QuestEN[63214] = { title = "Report to Moonberry", description = "You have chosen well.\n\nThe Night Fae fill a critical role in the eternal cycle of nature spirits. The balance of many worlds depends on their work.\n\nSpeak with Lady Moonberry and begin your future with your covenant.", objectives = "" }
WordHunterWoW_QuestEN[63215] = { title = "Report to Draven", description = "You have chosen well.\n\nThe Venthyr must return to their duty helping souls atone for their sins, saving them from an eternity in the Maw.\n\nDenathrius's treachery must be righted. Speak with General Draven and begin your future with your covenant.", objectives = "" }
WordHunterWoW_QuestEN[63340] = { title = "Sinfall Veteran", description = "Sinfall's influence grows thanks to your triumphs, {name}!\n\nYour accomplishments have not gone unnoticed, even beyond the borders of Revendreth.\n\nTales of your victories have echoed through the halls of Oribos. Zo'sorg, the Master of Conflict, has requested a meeting with you in the Enclave.\n\nThey have a keen interest in the art of war. I suggest you don't keep them waiting.", objectives = "" }
WordHunterWoW_QuestEN[63341] = { title = "Sinfall Tactician", description = "Sinfall is gaining more respect than Denathrius could have ever hoped to earn! It is all thanks to your efforts, {name}.\n\nZo'sorg has once again requested your presence in Oribos. Go at once.\n\nThe favor of Cartel Zo is not something we want to squander. A broker clan's trust is not one effortlessly gained.\n\nPerhaps they have more rewards to bestow upon you.", objectives = "" }
WordHunterWoW_QuestEN[63342] = { title = "Necrolord Veteran", description = "The might of the Necrolords grows thanks to you, {name}.\n\nYour accomplishments have not gone unnoticed, even beyond the borders of Maldraxxus.\n\nTales of your victories have echoed through the halls of Oribos. Zo'sorg, the Master of Conflict, has requested a meeting with you in the Enclave.\n\nThey have a keen interest in the art of war. I suggest you don't keep them waiting.", objectives = "" }
WordHunterWoW_QuestEN[63343] = { title = "Necrolord Tactician", description = "You have brought great honor to the Necrolords. Such honor attracts the attention of others yet again.\n\nZo'sorg has once again requested your presence in Oribos. Go at once.\n\nThe favor of Cartel Zo is not something we want to squander. A broker clan's trust is not one effortlessly gained.\n\nPerhaps they have more rewards to bestow upon you.", objectives = "" }
WordHunterWoW_QuestEN[63344] = { title = "Kyrian Veteran", description = "Bastion is healing thanks to you, {name}. The path is clear.\n\nYour accomplishments have not gone unnoticed, even beyond the borders of Bastion.\n\nTales of your victories have echoed through the halls of Oribos. Zo'sorg, the Master of Conflict, has requested a meeting with you in the Enclave.\n\nThey have a keen interest in the art of war. I suggest you don't keep them waiting.", objectives = "" }
WordHunterWoW_QuestEN[63345] = { title = "Kyrian Tactician", description = "Look around you, {name}. Elysian Hold stands as a testament to the progress we have made thanks to you.\n\nZo'sorg has once again requested your presence in Oribos. Go at once.\n\nThe favor of Cartel Zo is not something we want to squander. A broker clan's trust is not one effortlessly gained.\n\nPerhaps they have more rewards to bestow upon you.", objectives = "" }
WordHunterWoW_QuestEN[63346] = { title = "Night Fae Veteran", description = "Ardenweald is safer than it has been in quite some time, thanks to you.\n\nYour accomplishments have not gone unnoticed, even beyond the borders of Ardenweald.\n\nTales of your victories have echoed through the halls of Oribos. Zo'sorg, the Master of Conflict, has requested a meeting with you in the Enclave.\n\nThey have a keen interest in the art of war. I suggest you don't keep them waiting.", objectives = "" }
WordHunterWoW_QuestEN[63347] = { title = "Night Fae Tactician", description = "Your bravery has allowed Ardenweald to grow once again. It has also once again drawn the attention of brokers.\n\nZo'sorg has once again requested your presence in Oribos. Go at once.\n\nThe favor of Cartel Zo is not something we want to squander. A broker clan's trust is not one effortlessly gained.\n\nPerhaps they have more rewards to bestow upon you.", objectives = "" }
WordHunterWoW_QuestEN[63418] = { title = "Exploited Explorers", description = "Chuck explains that something weird is happening in the jungle, and that his  group has been captured by wild fungarians.\n\nHe asks you to rescue his friends to help find out what's going on with the jungle.", objectives = "" }
WordHunterWoW_QuestEN[63419] = { title = "Spores Galore", description = "Chuck goes over again how the jungle seems to be alive and all wrong.\n\nHe asks you to recover the spores that are on the fungarians and the beasts they've infected.\n\nChuck is worried whatever is happening isn't natural.", objectives = "" }
WordHunterWoW_QuestEN[63420] = { title = "Further In", description = "Flora says she can feel something dark within the spores and feels it's pointing northward.\n\nThe Explorer's League will move forward, she asks you join them up ahead.", objectives = "" }
WordHunterWoW_QuestEN[63430] = { title = "Toppling Terrors", description = "Flora says there's a huge monster within the Horde camp that needs to be destroyed. She believes this creature is the source of the corruption in this forest.", objectives = "" }
WordHunterWoW_QuestEN[63431] = { title = "Plume Power", description = "Boxy's readings indicate that the poisonous plumes nearby are also spreading the corruption of local flora.\n\nShe suggests you destroy several of them to prevent them from spreading any further.", objectives = "" }
WordHunterWoW_QuestEN[63432] = { title = "Unruly Garden", description = "Boxy's analysis shows that there's something not right within the creatures of the canopy. \n\nShe wants you to kill the creatures while she's scanning the area so she can determine what is causing them to animate.", objectives = "" }
WordHunterWoW_QuestEN[63435] = { title = "Temple Throwdown", description = "My parents are busy defending the Shrine of the... Eight... Coconuts? I wasn't paying attention. That's probably why they left me here.\n\nThey told me I could train with the big white cat! I'm going to be a ninja!\n\n<Anthea kicks several times in your direction.>\n\nYa! Kya! You better watch out!\n\n...\n\nI'm bored, do you want to pet battle? I brought all of my favorite pets with me.", objectives = "" }
WordHunterWoW_QuestEN[63447] = { title = "Fear No Evil", description = "Have you embraced the Holy Light yet, brother? It is through the Holy Light that we are saved! It is through the Holy Light that I am able to heal these overly demanding soldiers! And it is through the Holy Light that you will be able to venture out into the field to the north and rescue our fallen brothers!\n\nTake this prayer book with you into the field and cast the Light's healing touch on the injured.", objectives = "" }
WordHunterWoW_QuestEN[63455] = { title = "Dead On Their Feet", description = "As the Jailer twists the souls here to his will, there are still some that continue to resist him.\n\nI shall give you the ability to aid them in their resistance. Through Necrotic Cohesion we shall bind the runes, armor, and bones that reside here to create bodies for these souls. Bodies that will allow them to fight for us and their freedom!\n\nBind the Zealous souls and build us an army!", objectives = "" }
WordHunterWoW_QuestEN[63479] = { title = "Summons from the Matriarch", description = "Greetings, {name}.\n\nLet us not mince words--you are urgently needed in Silvermoon. \n\nWe're experiencing a resurgence of Scourge in Quel'Thalas. With nothing to hold the Scourge in check, we'll soon be overrun. We must hold the line!\n\nMeet me in the Hall of Blood, and we will get you a full briefing.", objectives = "" }
WordHunterWoW_QuestEN[63480] = { title = "Briefing", description = "We haven't much time. \n\nThe Scourge have attacked Tranquillien, and there's nothing to hold them back.\n\nWe must take decisive action.", objectives = "" }
WordHunterWoW_QuestEN[63481] = { title = "Tranquillien Besieged", description = "Rommath has opened the way for us to quickly travel to Tranquillien. I warn you, it's already a bloody battlefield.\n\nTake the portal, and I will be along right after you.\n\nAnd {name}... keep an eye on Salandria. She may have excelled in her training thus far, but she has yet to be tested like this.", objectives = "" }
WordHunterWoW_QuestEN[63482] = { title = "Death to the Scourge", description = "I haven't seen Scourge mustering in numbers like this since...\n\n<Liadrin shakes her head, steeling herself.>\n\nNever mind. There's no use dwelling in the past.\n\nOur first priority is thinning their numbers enough that we can find out what--or who--is really behind this attack. \n\nSlay as many of the undead as you can.", objectives = "" }
WordHunterWoW_QuestEN[63483] = { title = "Magus Installation", description = "This is no mindless strike... I have a strong suspicion that some powerful entity is manipulating the Scourge.\n\nEver since the Helm of Domination was shattered, there has been a conceivable risk that someone else could exert their will and assume control over the undead--at least temporarily.\n\nRommath and I can help defend Tranquillien, but we need to break those lines. \n\nClear a spot for us. Let us see if we can draw out their leader.", objectives = "" }
WordHunterWoW_QuestEN[63484] = { title = "A Knight's Weapon", description = "It's clear that this san'layn has decided to use the Scourge to empower himself somehow. We can keep taking him out, but he will just keep coming back.\n\nWe need a weapon that can break him for good.\n\nI think I have a solution. Upstairs, you will find a newly forged ranseur. It has yet to be tempered with magic--we will need to unlock its full potential. It will be our instrument of the Light.", objectives = "" }
WordHunterWoW_QuestEN[63485] = { title = "An Honest Heart", description = "If we are to defeat Vorath, we need to amplify the power of the ranseur. But we will not cut corners or impose our will to do it. That lesson has been learned.\n\nHowever, the kyrian of Bastion are masters of ushering souls to their proper places. Perhaps they would lend a fragment of their power to our cause.\n\nGo to Bastion, and find a way to empower the ranseur.", objectives = "" }
WordHunterWoW_QuestEN[63486] = { title = "An Unbreakable Will", description = "We're clearly dealing with someone who is using terrible magic to suspend his own death.\n\nThere's another force we know of that uses magic in this fashion. The Maldraxxi are intimately familiar with the trappings of death, and equally familiar with how to subvert it. Perhaps one of the Houses knows of a way to help us.\n\nGo there, and seek out power that can break this unnatural loop.", objectives = "" }
WordHunterWoW_QuestEN[63487] = { title = "Return to the Ghostlands", description = "Such power! Surely not even Vorath can withstand the might of this weapon now. \n\nWe have what we came to the Shadowlands for. The ranseur is ready.\n\nLet's get back to Lady Liadrin in Tranquillien. I hope we're not too late to make a difference!", objectives = "" }
WordHunterWoW_QuestEN[63488] = { title = "I Am the Blade of the Light", description = "It's time to put all that power and training into the field.\n\nTake the empowered ranseur, and cut a swath of destruction through the Scourge!\n\nWe'll meet you at the doorstep of Deatholme.", objectives = "" }
WordHunterWoW_QuestEN[63489] = { title = "Justice Long Overdue", description = "You made short work of the Scourge in the Dead Scar, but we've a bigger target to face. It's time to test the mettle of your weapon against Vorath.\n\nLet us finish this, together.", objectives = "" }
WordHunterWoW_QuestEN[63490] = { title = "Blood Knight", description = "The power of the ranseur has been spent, but we are victorious! With Vorath defeated, perhaps the Scourge will be more easily dealt with--thanks to you.\n\nMeet me back in Silvermoon. Your efforts and heroism today will not go unrecognized.", objectives = "" }
WordHunterWoW_QuestEN[63494] = { title = "The Anvil-Thane's Designs", description = "I see you eyein' our weapons here. Wouldnae ye know, I forged them myself!\n\nSo far, I've got designs for a staff, a one-handed axe, and a shield... I could make ye some, if you'd like!\n\nO' course, that's what I'd normally say. Unfortunately I lost the designs in a bet down at the Grim Guzzler. If ye could get them back, as well as gather the materials, I'd be happy to forge ye some weapons!", objectives = "" }
WordHunterWoW_QuestEN[63498] = { title = "Brawl or Brew", description = "Ach, Thurgaden sent ye did he? Ye'd think the Anvil-Thane would be made o' tougher stuff than the rest of this drunken lot, but I guess I was mistaken!\n\nIf ye want tae win back his designs, yer gonna have tae win 'em fair and square.\n\nI've only got one question left fer ye.\n\nBrawl? Or Brew?", objectives = "" }
WordHunterWoW_QuestEN[63501] = { title = "It's Called Borrowing", description = "<These complex blueprints detail Thurgaden's designs for his weaponry, but are hard to parse. Notes are scribbled in the margins in messy handwriting, listing modifications and notes Thurgaden left for himself.\n\nTwo notes in particular stand out to you. One denotes that he lent his engraving tool to the core hound trainer Kasea Angerforge, and the other wonders how many elementals they employ at the Grim Guzzler brewing operation.>", objectives = "" }
WordHunterWoW_QuestEN[63502] = { title = "Weapons o' the Dark Iron", description = "One step left, friend. Lend me a hand in my craftin', then you'll have yer hands on the most powerful weapons forged in the deepest fires of Blackrock Mountain!", objectives = "" }
WordHunterWoW_QuestEN[63505] = { title = "An Engraved Invitation", description = "<The fox kit sits on his haunches and pulls out an elaborate winged scroll from seemingly nowhere. He expectantly waits for you to read it.>", objectives = "" }
WordHunterWoW_QuestEN[63506] = { title = "Mecha Gone", description = "Now this... This is what I wanted to see! A place filled with industry, technology, and that strange and exotic material... Metal! \n\nWhy, most of these little people appear to be made of it. Oh! Some of the animals are entirely metal as well!  How delightful! I wish to see more.\n\nYou are a native of this world, {name}, guide us-- But, wait! One must be properly dressed for such a task.\n\nWe shall fix that! And then... <Renard flings out a dramatic paw.>The Tour!", objectives = "" }
WordHunterWoW_QuestEN[63507] = { title = "Kate Reuse Me", description = "One of my most talented children is interested in your further exploits.\n\n<Renard's grin is sharp. You are fairly certain foxes are not supposed to have that many teeth.>\n\nI would be an irresponsible parent if I did not investigate your world personally! So you will show us Stormwing or Stormshield or Stormheim or Stormwhatever.\n\nWhat? You say, it isn't your capitol?\n\n<Renard waves a dismissive paw.>\n\nEh. Details. We're going on a road trip! Meet us there.", objectives = "" }
WordHunterWoW_QuestEN[63508] = { title = "Into the Woods Without Delay", description = "One of my most talented children has been following your exploits closely and has grown fascinated with your world.\n\n<Renard's grins sharply at you with his many, many teeth. You are fairly certain foxes are not supposed to have that many teeth.>\n\nAs a responsible parent, I wish to show them it first hand! So, you will guide us around Azathon or Azathoth or Azeroth or whatever you mortals call your realm.\n\n<Renard waves a dismissive paw.>\n\nMere details. Come Renata! The mortal world awaits!", objectives = "" }
WordHunterWoW_QuestEN[63509] = { title = "Road Trip!", description = "I have heard of a magical floating city called \"Dalaran.\" It sounds fun! Our fabulous tour will head there next! \n\n<Renard pauses a moment, a paw brushing his bushy moustache.>\n\nIt occurs to me we seem to be skipping over much of this world by always using portals. Let us make it a road trip this time!\n\nCome along!", objectives = "" }
WordHunterWoW_QuestEN[63510] = { title = "Hi, Mountain!", description = "Maw walker, I wish to see Highmountain. The Horned Hunter is from there. He is a most canny soul. Why, he even managed to pull a prank or two on my father!\n\nLet us go to Highmountain next!", objectives = "" }
WordHunterWoW_QuestEN[63511] = { title = "Big Finish", description = "", objectives = "" }
WordHunterWoW_QuestEN[63519] = { title = "Unfair Fight", description = "A cowardly pest that cheats his way out of the glory of death? Bah!\n\nI have something that'll cut him down where he stands. But such an enhancement requires one who is strong enough to wield it properly.\n\nShow me your mettle and fight! If you can prove yourself, I'll empower that ranseur of yours.", objectives = "" }
WordHunterWoW_QuestEN[63522] = { title = "A Fair Race", description = "A soul that refuses to cross the veil is a problem we kyrian are familiar with. I can help you.\n\nBut before I grant your weapon this power, I must know that you will not abuse it, and that your heart is true.\n\nLet us run a race. Along the course, ring the bells. If your heart is pure, they will aid your speed. You must have at least five bells recently rung in order to complete the race.\n\nDo not be distracted by shortcuts. And do not try to cheat to get ahead, it will not work.\n\nAre you ready?", objectives = "" }
WordHunterWoW_QuestEN[63545] = { title = "Putting A Plan Together", description = "While Maldraxxus pushes the main gate, we can take the side gate with the help of our Centurions.\n\nThe remains of many Corrupted Centurions taken by the Jailor litter this area. Their parts could be used to build new ones to help in the assault.\n\nSee if you can locate the parts we need to build a new Centurion.", objectives = "" }
WordHunterWoW_QuestEN[63576] = { title = "The First Move", description = "While the covenants labor to defend the Shadowlands, the Jailer has not sat idle within Torghast. It seems he intends to set the next phase of his scheme into motion.\n\nPolemarch Adrestes has brought us disturbing news from Elysian Hold. He will recount what he witnessed once you arrive.\n\nMake haste. I fear that time grows short.", objectives = "" }
WordHunterWoW_QuestEN[63578] = { title = "The Battle of Ardenweald", description = "With the betrayal of Sire Denathrius, and the absence of the Primus of Maldraxxus, we must assume that the Winter Queen is the Jailer's next target.\n\nAnd we won't let anyone take her sigil!\n\nArdenweald has endured much, but it is a realm of great and mysterious power. Things aren't always what they seem.\n\nWe'll use this to our advantage, no matter who comes for the Queen!", objectives = "" }
WordHunterWoW_QuestEN[63579] = { title = "A Paladin's Soul", description = "Bolvar Fordragon has seen visions of a vault hidden deep within Torghast where the Jailer keeps souls he deems valuable.\n\nUther was struck down by a mourneblade. When such a weapon is wielded with rage, it can shatter a soul into fragments.\n\nIf the Jailer holds a part of Uther's soul, it cannot be fully mended until the lost piece is restored.\n\nTake this attuned shard to Torghast, {name}. It should guide you to the vault's location.\n\nFind the lost fragment of Uther's soul so that he can be made whole.", objectives = "" }
WordHunterWoW_QuestEN[63580] = { title = "Wounded Memories", description = "The arrival of Uther's wounded soul was the impetus for many events that led us to our current struggles.\n\nDevos's broken trust. Her involvement with Helya. The rise of the Forsworn.\n\nBastion needs to change, but we struggle to find a solution.\n\nPerhaps this soul fragment will provide valuable insight.", objectives = "" }
WordHunterWoW_QuestEN[63581] = { title = "Step Into the Light", description = "It is as I feared.\n\nThis fragment of Uther's soul was darkened by the mourneblade that slew him. His memories are shattered and twisted.\n\nFor Uther to move past his pain, to move past his grief, he must experience his past once again.\n\nBut he does not have to do this alone.\n\nUsing my soul mirror, we can aid Uther in walking through these memories. He can then come to terms with the emotions they contain. We must help him see past the distortions and understand the truths they hold.", objectives = "" }
WordHunterWoW_QuestEN[63582] = { title = "He Was My Student", description = "Uther's memories of this Prince Arthas haunt him deeply. He is the reason Uther's soul was fragmented, why Devos fell the way she did.\n\nThe pain in these memories is palpable.\n\nWe have to dig deeper. Uther must face the source of this darkness.\n\nOnce again, you need to enter his past to protect his future.", objectives = "" }
WordHunterWoW_QuestEN[63583] = { title = "I Intend to Live Forever", description = "Please, {name}. I am not finished.\n\nThere is one more memory that I must see. One more that must be faced.\n\nIt... it will not be easy. I will need support from all of you.\n\nBut it must be done.", objectives = "" }
WordHunterWoW_QuestEN[63584] = { title = "A Triumphant Return", description = "This temple represents a new dawn for Bastion, {name}.\n\nThe Temple of Devotion will stand as a place of fellowship. We will work with the Forsworn, as well as aspirants and kyrian of all experience and backgrounds, to forge a future of which all can be proud.\n\nLet us return to Elysian Hold. I request that you join us for a momentous occasion--the ascension of a new Paragon and the creation of a new sigil.", objectives = "" }
WordHunterWoW_QuestEN[63585] = { title = "Blind Loyalty", description = "The path forward for the kyrian is clear to me now.\n\nFirst we will speak with Nikolon. I urge you to stay and listen.\n\nAfterward, we must return to Elysian Hold.\n\nThere I will request an audience with the Archon, and I need you all by my side as I do so.", objectives = "" }
WordHunterWoW_QuestEN[63586] = { title = "Compassion in Devotion", description = "Our first order of business is to rededicate the Temple of Loyalty.\n\nPelagos has volunteered to stay here and help prepare for the ceremony. I requested that Nikolon bring his companions to meet us at Steward's Rest, to aid us in convincing some of the Forsworn of our new path.\n\nMeet us there when you are able.", objectives = "" }
WordHunterWoW_QuestEN[63587] = { title = "Reclaimable Anima", description = "Mikanikos has explained much about Forsworn centurions to me, {name}.\n\nI cannot say that I understood all of it, but it seems he has not yet found a reliable way to return them to their proper operating standards.\n\nTheir anima can still be useful, though!\n\nAdrestes has focused on how to rededicate the temple, but not on his own safety. I worry the process will drain much of his anima.\n\nIf you can reclaim cores from the Forsworn centurions, we can use them as anima stores for Adrestes.", objectives = "" }
WordHunterWoW_QuestEN[63588] = { title = "Rebuilding Faith", description = "The Forsworn are lost, {name}.\n\nThey are like ghosts, haunting the Temple of Loyalty. Nowhere else to go. Leaderless, purposeless, abandoned.\n\nWe must show them that there is a path forward.\n\nLet me accompany you into the temple. Allow me to talk to them, speak to their sensibilities. Perhaps we can convince them to give Adrestes's new path a chance.", objectives = "" }
WordHunterWoW_QuestEN[63589] = { title = "Directing Dedication", description = "The five temples of Bastion have stood strong since its very creation. The idea of rededicating one has never been broached before, and will no doubt require a significant amount of anima.\n\nUnderneath this temple are stores of anima we rationed for the drought. Now that anima is returning, we can use these reserves for our purposes.\n\nYou will need to use channelers and collectors throughout the grounds to redirect anima to the top. That should give me the power I need.", objectives = "" }
WordHunterWoW_QuestEN[63590] = { title = "The Vesper Rings", description = "Loyalty shall no longer be a demanded tenet of the Path, but rather a virtue that is earned. A choice.\n\nWe must show devotion to those who struggle, whether they are recently arrived souls or peers who need our aid.\n\nIt will take all the anima at hand to rededicate this temple. And in so doing, to ring in a new age for the kyrian.\n\nI fear the Mawsworn may attempt to thwart our plans. Protect me during this ritual, {name}. We must see this through.", objectives = "" }
WordHunterWoW_QuestEN[63591] = { title = "The Grand Reception", description = "{name}, you have aided the kyrian in the most trying of times. Your devotion to our cause has helped usher in a new beginning for all of us.\n\nWe would be honored if you would join us for a gathering prior to the ceremony. Many members of our covenant wish to express their appreciation for all you have done.\n\nThis is a day of great joy. I am so pleased that you are here to witness it!", objectives = "" }
WordHunterWoW_QuestEN[63592] = { title = "The New Path", description = "Today, a new paragon is anointed. And for the first time since the dawn of our realm, a temple is rededicated to represent our devotion to one another.\n\nA new paragon, a new sigil, and a new path for all kyrian.\n\nThis ceremony shall be glorious indeed!", objectives = "" }
WordHunterWoW_QuestEN[63593] = { title = "New Sigil of the Kyrian", description = "With a future of kinship and devotion secured for Bastion, a new sigil is born to represent our path forward.\n\nPlease report all that you have done to the Primus. When he is ready, we will deliver the sigil to him. \n\nLet us hope he can use it to thwart the Jailer's plan and save the Shadowlands.", objectives = "" }
WordHunterWoW_QuestEN[63594] = { title = "Clearing the Walls", description = "<This scroll shows the locations of a series of pylons, that protect Perdition Hold from assault.\n\nDestroying these Pylons could aid in the success of our attack>", objectives = "" }
WordHunterWoW_QuestEN[63603] = { title = "Yak Soul", description = "<The Yak Soul is cordial and resilient. The shape of the yak will be yours to call upon.>", objectives = "" }
WordHunterWoW_QuestEN[63604] = { title = "Shoveltusk Soul", description = "<The Shoveltusk Soul is protective and determined. The shape of the shoveltusk will be yours to call upon.>", objectives = "" }
WordHunterWoW_QuestEN[63605] = { title = "Saurolisk Soul", description = "<The Saurolisk Soul is agile and clever. The shape of the saurolisk will be yours to call upon.>", objectives = "" }
WordHunterWoW_QuestEN[63606] = { title = "Spider Soul", description = "<The Spider Soul is nimble and cunning. The shape of the spider will be yours to call upon.>", objectives = "" }
WordHunterWoW_QuestEN[63607] = { title = "Direhorn Soul", description = "<The Direhorn Soul is brutal and tenacious. The shape of the direhorn will be yours to call upon.>", objectives = "" }
WordHunterWoW_QuestEN[63608] = { title = "Hippo Soul", description = "<The Hippo Soul is ferocious. The shape of the hippo will be yours to call upon.>", objectives = "" }
WordHunterWoW_QuestEN[63609] = { title = "Kodo Soul", description = "<The Kodo Soul is calm and loyal. The shape of the kodo will be yours to call upon.>", objectives = "" }
WordHunterWoW_QuestEN[63610] = { title = "Mammoth Soul", description = "<The Mammoth Soul is brave and protective. The shape of the mammoth will be yours to call upon.>", objectives = "" }
WordHunterWoW_QuestEN[63612] = { title = "The Chains of Command", description = "If we must hold a position so near to the Jailer's lands, we need to provide some assurances.\n\nVyraz and Helya have retreated within the walls of Desmotaeron. They have grown lax in their expected safety, which provides us with an opportunity.\n\nWe will take them by surprise. Strike swiftly and without mercy, and perhaps we can cut the heads off those snakes.", objectives = "" }
WordHunterWoW_QuestEN[63613] = { title = "Gates of the Damned", description = "We need to prepare for the assault before we signal Zerekriss. Once it is in place, our allies will use death gates to assault the area.\n\nWe will need to summon the death gates on this side. Find strategic locations for them.", objectives = "" }
WordHunterWoW_QuestEN[63614] = { title = "Weapon in Hand", description = "A moment, {name}.\n\nI threw my axe Dra'gora at Helya during our first encounter in the Maw, and I haven't seen it since. If this is truly where she commands her forces, then perhaps it's held here.\n\nI crafted that weapon in Nagrand, and it reminds me of many good days spent beside my family there. I want to feel its weight in my hands once again.", objectives = "" }
WordHunterWoW_QuestEN[63615] = { title = "Clip Their Wings", description = "The skies are dark with Helya's kyrian followers. If we do not thin their numbers, Zerekriss and our aerial allies may have difficulties pushing forward.\n\nI've noticed that the Mawsworn often use magical chains. We could turn their equipment against them and tear them down from the sky.", objectives = "" }
WordHunterWoW_QuestEN[63616] = { title = "A Job Done Right", description = "We should be clear to start the assault.\n\nSignal the Zerekriss. Let us show them the might of a Maldraxxian necropolis and the combined armies of the Shadowlands!", objectives = "" }
WordHunterWoW_QuestEN[63617] = { title = "Bending Bars", description = "In all the chaos, the gates of the upper hold have been left open. If we slip through, they might not even notice us until it is too late.\n\nOne of Helya's lieutenants stands between us and Helgarde Keep. End them.", objectives = "" }
WordHunterWoW_QuestEN[63618] = { title = "What Maldraxxus Does Best", description = "Every enemy we vanquish here is one our army does not have to contend with. We will make sure they will not soon forget the true purpose of Maldraxxus. Show them what happens to those we deem a threat towards the Shadowlands.\n\nKill every Mawsworn in sight.", objectives = "" }
WordHunterWoW_QuestEN[63619] = { title = "Forsworn and Forgotten", description = "Wait... I know you! The Maw Walker!\n\nMy brothers and sisters have been twisted... tainted. Some took power willingly from Helya, but others resisted. Now all of us are forced to submit to her power.\n\nI escaped when the fighting started, but most of the remaining Forsworn are being subjected to horrific rituals.\n\nPlease, I beg you to free them. Then we will return to Bastion and submit to the Archon's judgment.", objectives = "" }
WordHunterWoW_QuestEN[63620] = { title = "A Traitor's Due", description = "Vyraz has been a constant thorn in Maldraxxus's side since he betrayed us. As Baroness of the House of the Chosen, it is my duty to see this threat eliminated... and the murder of Margrave Krexus avenged.\n\nAs the Primus said, we must remove the head from this snake.\n\nThe time to strike is now!", objectives = "" }
WordHunterWoW_QuestEN[63621] = { title = "Pulling His Chain", description = "They call this one the Keeper of Chains. Do not underestimate his power. He has bound nearby souls in preparation for an attack against our position.\n\nI need you to eliminate this threat, Maw Walker, before it moves against our forces.", objectives = "" }
WordHunterWoW_QuestEN[63622] = { title = "Victory in Our Name", description = "With Helya and Vyraz taken care of, we have achieved a major victory against the Mawsworn today. It is also a showing of what the combined might of the Shadowlands looks like.\n\nWe should return to Korthia before something else arises.", objectives = "" }
WordHunterWoW_QuestEN[63623] = { title = "Filling an Empty Throne", description = "Maw Walker.\n\nIn my long absence, you have done much to bring order and strength back to the necrolord covenant. In recognition, I invite you to witness a ceremony.\n\nReturn with me to my seat of power in Maldraxxus. It is time I rewarded one who was most loyal to our cause.", objectives = "" }
WordHunterWoW_QuestEN[63624] = { title = "The Roads We Walk", description = "The armies of Maldraxxus are strong. They will recover from Vyraz's transgression. \n\nThe first thing we must do is rebuild. Maw Walker, stand witness to a new era for Maldraxxus!", objectives = "" }
WordHunterWoW_QuestEN[63625] = { title = "Here's an Axe, Get to Work!", description = "Our troops are meeting stiff resistance! Maw Walker, grab a weapon and take the fight to them!\n\nEliminate the Mawsworn forces and their commander defending these gates.", objectives = "" }
WordHunterWoW_QuestEN[63638] = { title = "Can't Turn Our Backs", description = "That's Sylvanas and her Mawsworn dealt with... for now.\n\nBut we need to hurry and make sure that the Queen and her sigil are safe! \n\nThe Winter Queen was just outside the Heart of the Forest, protecting the stolen wildseeds from the Maw.", objectives = "" }
WordHunterWoW_QuestEN[63639] = { title = "Report to Oribos", description = "Ardenweald has withstood the unrelenting force of the Maw.\n\nBut it was still not enough.\n\nReturn to our allies in Oribos. There must be an answer for this loss, and action taken.", objectives = "" }
WordHunterWoW_QuestEN[63644] = { title = "Dread Tidings", description = "The threat the nathrezim pose to our forces must not be underestimated. They are cunning, rivaling the best veterans of the House of Eyes, and we do not know their full plan.\n\nAmong the venthyr there is one whose wrath scourged the nathrezim from the Shadowlands for many thousands of years. \n\nI ask you travel to Sinfall, seek out Prince Renathal, and deliver to him this missive. I shall send one of my own spies, the Baroness Vashj, to meet you there. Make use of her experience with the nathrezim.", objectives = "" }
WordHunterWoW_QuestEN[63645] = { title = "The Dawnkeep Prisoner", description = "Oh, you have not heard the news yet.\n\nWe have him. Sire Denathrius, Master of Revendreth, imprisoned within his own blade.\n\nWe managed to best him during one of our recent raids of Castle Nathria.\n\nIt took an army of unparalleled valor and preparation. It took skill and wealth. It took a miracle.\n\nAnd so the redeemer shall be redeemed. Would you like to know more?", objectives = "" }
WordHunterWoW_QuestEN[63646] = { title = "Convoy of the Covenants", description = "A new sigil for the Venthyr would require all seven medallions to forge.\n\nThe Primus was correct. The person we need is the Stonewright. Her grievances against the Unseen could fill a library and she holds the last of the medallions we need. I believe you and I are long overdue in convincing her to join our cause.\n\nI will make the arrangements. We shall go properly this time, with gifts and diplomacy. \n\nYou should warn Chelra, she will want to arrange an escort.", objectives = "" }
WordHunterWoW_QuestEN[63647] = { title = "The Unseen Guests", description = "Dreadlords.\n\nOf course. Of course they would come back now of all times. I half suspected they returned during the drought. \n\nI was not entirely convinced you were not one, the first time I saw you. They have gotten more clever over the eons since they fled Revendreth. \n\nBut not clever enough... I think.\n\nCome, Maw Walker. Follow me and do not make a fuss. Keep your weapon ready. The envoy you brought is not as well intentioned as you might have thought.", objectives = "" }
WordHunterWoW_QuestEN[63648] = { title = "Nal'ragas", description = "The Stonewright's medallion must not stay in the hands of the nathrezim. \n\nFrom what the Accuser explained of our mission, the medallion is required if we wish to forge a new sigil for the Venthyr. I have no doubt that is why Nal'ragas and her ilk executed their ambush now.\n\nThe medallions are not subtle magic, and their affect on this realm is easily tracked. I suggest we give chase and eliminate this Nal'ragas before she can be reinforced.", objectives = "" }
WordHunterWoW_QuestEN[63649] = { title = "Spy vs Spy", description = "Nathrezim. Dreadlords. The Unseen Guests.\n\nCall them what you will, they are a race that was crafted to be the greatest collection of spies and infiltrators in all of reality, once upon a time. \n\nTheir intrusion has underestimated three things. Kael'thas Sunstrider, Baroness Vashj, and {name}!\n\nI have brought a tool Kael'thas and I used to detect nathrezim when we served under Illidan. And I am the matron of spies!\n\nLet us hunt these intruders down.", objectives = "" }
WordHunterWoW_QuestEN[63650] = { title = "De-Infiltration", description = "Mal'Ganis.\n\nIt has been many ages since I have said his name. And now I find we must hunt him down.\n\nIf he has the Medallion of Wrath then there is nowhere he can hide. We can use the other medallions we have recovered to locate him.\n\nJoin me in Sinfall and bring your dreadlord hunting party. I suspect we will have need of them.", objectives = "" }
WordHunterWoW_QuestEN[63651] = { title = "Cryptograms", description = "If the nathrezim have infiltrated Sinfall they will be communicating, and not just through hand gestures or spoken words. They like to use magical written messages concealed by a simple cantrip, invisible to the average observer.\n\nHowever, I have developed an incantation that should allow you to see these messages.\n\nFind these cryptograms and bring me their contents. I can translate them if they are beyond your understanding.", objectives = "" }
WordHunterWoW_QuestEN[63652] = { title = "The \"Unwelcome\" Guests", description = "Chelra, I mean Nal'ragas, would not have been working alone. We must assume the worst, that not all of our friends and allies are who they seem to be.\n\nIt will take time for the Court of Harvesters to render our detection ritual. While we do so we will be exposed. I ask that you use the techniques you employed at Dominance Gate within Sinfall to root out any nathrezim within our ranks. \n\nGood hunting.", objectives = "" }
WordHunterWoW_QuestEN[63653] = { title = "The Power of a Crown", description = "We are ready.\n\nThe Court of Harvesters shall use the power of the medallions we have gathered thus far to locate the Medallion of Wrath. So long as they have not removed it from the realm we should be able to divine its presence.\n\nThis is not an easy ritual--the nathrezim specialize in avoiding detection. When you see the path, take it and move with speed.\n\nAnd when you find them, wait for us before you engage.", objectives = "" }
WordHunterWoW_QuestEN[63654] = { title = "The Nathrezim", description = "The Medallion of Wrath is more than just a powerful artifact. In the hands of a nathrezim it could be used to shape this realm to their dark purpose. What is more, while they hold it we are denied the ability to forge a new sigil.\n\nThey already nearly destroyed the Ember Ward with their reckless schemes. I will not have my medallion used for their ends.\n\nCome, let us get it back.", objectives = "" }
WordHunterWoW_QuestEN[63655] = { title = "Medallion of Wrath", description = "Maw Walker. I will march with my stoneborn into the depths of the Maw and rend the head off every nathrezim I find there.\n\nHowever, Revendreth is still too strategic in this war to lose out of misplaced vanity. \n\nTherefore, as Harvester of Wrath, the second of that title, I offer you my medallion for safe keeping and utilization while I wage this war.\n\nUse it to empower the Harvesters so they can prevent Denathrius from simply returning and regaining control with a snap of his fingers.", objectives = "" }
WordHunterWoW_QuestEN[63656] = { title = "The Meaning of Wrath", description = "I will gather my forces and dispense a portion to Korthia immediately. I will also see to it that they are provided the tools Baroness Vashj and Kael'thas were able to conjure so that we might further defend against nathrezim incursions.\n\nOther duties require my attention before I can descend on Korthia. I must secure Dominance Keep against further infiltrators.\n\nI suppose the Primus will want an update. You may tell him you were successful.", objectives = "" }
WordHunterWoW_QuestEN[63659] = { title = "Dreadlords!", description = "This is the fifth dreadlord I have found infiltrating our forces this week. Unchecked they can cause tremendous damage to our foothold here.\n\nIn life I learned how to identify these creatures from a demon hunter. It makes it far easier for me to locate them, but I cannot be in all places at once.\n\nWe must report these findings to the Primus.", objectives = "" }
WordHunterWoW_QuestEN[63660] = { title = "Opening the Maw", description = "The Jailer has gained another sigil, and his forces actively assault Oribos.\n\nBolvar Fordragon and Draka of Maldraxxus suggest taking the fight to the Jailer.\n\nTo do so, we need a way for their forces to safely come and go from the Maw.\n\nThis was considered impossible before you arrived, but now I believe we have a chance.\n\nI must examine your anima to see if this is truly what the Purpose wills.", objectives = "" }
WordHunterWoW_QuestEN[63661] = { title = "Link to the Maw", description = "The Fatescribe is certain that a second waystone has emerged in the Maw. It falls to you to locate it. \n\nI will create an anchor here in Oribos that links to your anima. Once you attune yourself to the waystone, this anchor will be bound to it.\n\nIf you are successful, the covenants will be able to send their forces inside and safely leave the Maw again.\n\nUse what resources you have within the Maw to find this waystone.\n\nGood luck, mortal. May the Purpose guide us all.", objectives = "" }
WordHunterWoW_QuestEN[63662] = { title = "Mysteries of the Maw", description = "The Maw is changing, mortal. And with change comes opportunity.\n\nThe Jailer has pulled a realm that was hidden deep within the Shadowlands into the Maw. It is a location of some interest to me, but I do not wish to approach it alone.\n\nThe Mawsworn are swarming the area, you see. There must be something of value that they seek.\n\nI have a safe enclave nearby. Accompany me there and I may be able to help you find that waystone you're looking for.\n\nDo we have a deal?", objectives = "" }
WordHunterWoW_QuestEN[63663] = { title = "Korthia, the City of Secrets", description = "We are on the threshold of attaining our desires, Maw Walker.\n\nYour grand waystone cannot be far off. Of course, my needs are much more modest. A bit of useful information here, a priceless relic there...\n\nI will survey the area to see if there is anything useful--or hazardous--nearby. Then we can proceed.", objectives = "" }
WordHunterWoW_QuestEN[63664] = { title = "Get to the Point", description = "Our position near the bridge to the Altar of Domination is under heavy attack! We can not afford to lose the ballista we have set up there.\n\nMaw Walker, I need you to defend that position till our troops can push forward!", objectives = "" }
WordHunterWoW_QuestEN[63665] = { title = "Opening to Oribos", description = "The prophecies told us that one day this dormant waystone would be needed by a  Maw Walker. That it would prove crucial to the fate of the Shadowlands.\n\nIt seems that day has come.\n\nDraw upon the anima within you to activate this waystone. It will then be usable by all those who aid your cause.\n\nIf, as you say, Tal-Inara has created an anchor in Oribos, then that anchor will bring you back to us.\n\nGo, {name}. Inform your allies that the Maw awaits... and that Korthia needs their help.", objectives = "" }
WordHunterWoW_QuestEN[63669] = { title = "Somebody Feed Kevin", description = "My family of slimes is always hungry for anima. Thankfully the bodies of the defeated here are a good source!\n\nThe more the slimes consume the larger they grow. Then what remains of the fallen will become part of our wonderful, happy family.\n\nTake Kevin and let him consume fallen enemies till he is fully grown, then unleash him upon our foes!", objectives = "" }
WordHunterWoW_QuestEN[63672] = { title = "A Cry From the Heart", description = "<The voice of Ysera emanates from the scroll as you read the words.>\n\n{name},\n\nThere is a matter of great importance which requires your help. Please meet me at the Heart of the Forest as soon as you can.", objectives = "" }
WordHunterWoW_QuestEN[63673] = { title = "Hunting Amid Houses", description = "I have good news, {name}. With the covenants working more closely together, Huln's hunt has found greater success. He has solid leads on two more Night Warriors here in the Shadowlands.\n\nHe wishes for you to meet him in Maldraxxus about the first. Huln awaits you at the Sepulcher of Knowledge.\n\nHurry, {name}. Elune's power rips at Tyrande's essence. I do not know how much longer she can hold on.", objectives = "" }
WordHunterWoW_QuestEN[63674] = { title = "By Your Leave", description = "I have a task set before me by my Baroness, Lady Vashj. With assistance, my vengeance would be swift. But she must approve of your help as well as my release to assist you with your task.\n\nGo to the Seat of the Primus. There we will speak with her.", objectives = "" }
WordHunterWoW_QuestEN[63675] = { title = "You Cannot Run", description = "Zelmany was integral in the fall of my Margrave.\n\nSin'Dane believes he is trying to gather forces loyal to Kel'Thuzad so they might help him in his next plot.\n\nWe should look for clues to his location and then slay him.", objectives = "" }
WordHunterWoW_QuestEN[63676] = { title = "You Cannot Hide", description = "There are those who held their affiliation with Kel'Thuzad secret even after he made his move. They too were involved in the fall of my Margrave, and they too shall die.\n\nI have one name, Drava'ora, but there are more. Sin'dane had indicated these traitors carry marks of favor. She doesn't know who has them so we'll start killing until we find them.\n\nThe rest will see the example made.", objectives = "" }
WordHunterWoW_QuestEN[63677] = { title = "You Can Only Die", description = "The last name on my list is a lich named Fal'zinge.\n\nSin'Dane has been keeping a close eye on him to learn more of what Kel'Thuzad is planning next. \n\nShe wishes for Fal'zinge's execution to be brutal. \n\nWe will find him in the Exoramas in the House of Rituals.", objectives = "" }
WordHunterWoW_QuestEN[63678] = { title = "Akarek Avenged", description = "The last of those traitors involved in taking down Margrave Akarek are dead. \n\nIt will not bring our Margrave back, but I am still pleased.\n\nMy Baroness wished for us to inform Margrave Sin'dane that the job was done before departing for Ardenweald.", objectives = "" }
WordHunterWoW_QuestEN[63679] = { title = "Magical Mystery Tour!", description = "<Lady Moonberry's voice rises from the scroll.>\n\n{name}! It seems Huln got into some trouble. And--well--it's complicated. We could really use your help in Revendreth! Please meet me at Dominance Keep.\n\nSee you soon!", objectives = "" }
WordHunterWoW_QuestEN[63680] = { title = "Out On the Edge", description = "It sounds like Huln was taken elsewhere, and by the Stonewright herself!\n\nWe should look for signs she came through the area. Hopefully that will lead us to Huln!", objectives = "" }
WordHunterWoW_QuestEN[63681] = { title = "Back to The Heart", description = "We should hurry back to Ardenweald!\n\nYou go on ahead and find Ysera. I'll escort the Stonewright there and make sure Huln gets back.", objectives = "" }
WordHunterWoW_QuestEN[63682] = { title = "The Power of Elune", description = "We have done as much as we can with the time we had.\n\nNow we must lend our power to Thiernax and the others, and hope Tyrande survives.", objectives = "" }
WordHunterWoW_QuestEN[63683] = { title = "Winter's Sigil", description = "My sister... After all this time... She did not abandon me...\n\n<The barest hint of a smile graces the Winter Queen's face before it is gone. She turns her attention to you with the weight of eons.>\n\nAttend me, {name}. Take my sister's tear, and come to the Heart of the Forest.", objectives = "" }
WordHunterWoW_QuestEN[63684] = { title = "Feral Shadehound", description = "<The runed armor husk pulses with power and seems to struggle for its freedom.\n\nRelease your feral shadehound and bind it to you.>", objectives = "" }
WordHunterWoW_QuestEN[63685] = { title = "Cryptkeeper Kassir's Best Friend", description = "", objectives = "" }
WordHunterWoW_QuestEN[63686] = { title = "Baroness Vashj's Best Friend", description = "", objectives = "" }
WordHunterWoW_QuestEN[63687] = { title = "Lady Moonberry's Best Friend", description = "", objectives = "" }
WordHunterWoW_QuestEN[63688] = { title = "Mikanikos's Best Friend", description = "", objectives = "" }
WordHunterWoW_QuestEN[63689] = { title = "The Countess's Best Friend", description = "", objectives = "" }
WordHunterWoW_QuestEN[63690] = { title = "Alexandros Mograine's Best Friend", description = "", objectives = "" }
WordHunterWoW_QuestEN[63691] = { title = "Hunt-Captain Korayn's Best Friend", description = "", objectives = "" }
WordHunterWoW_QuestEN[63692] = { title = "Polemarch Adrestes's Best Friend", description = "", objectives = "" }
WordHunterWoW_QuestEN[63693] = { title = "Rendle and Cudgelface's Best Friend", description = "", objectives = "" }
WordHunterWoW_QuestEN[63694] = { title = "Choofa's Best Friend", description = "", objectives = "" }
WordHunterWoW_QuestEN[63695] = { title = "Droman Aliothe's Best Friend", description = "", objectives = "" }
WordHunterWoW_QuestEN[63696] = { title = "Grandmaster Vole's Best Friend", description = "", objectives = "" }
WordHunterWoW_QuestEN[63697] = { title = "Kleia and Pelagos's Best Friend", description = "", objectives = "" }
WordHunterWoW_QuestEN[63698] = { title = "Plague Deviser Marileth's Best Friend", description = "", objectives = "" }
WordHunterWoW_QuestEN[63699] = { title = "Sika's Best Friend", description = "", objectives = "" }
WordHunterWoW_QuestEN[63700] = { title = "Stonehead's Best Friend", description = "", objectives = "" }
WordHunterWoW_QuestEN[63703] = { title = "Vault of Secrets", description = "You've helped us regain a semblance of order, Maw Walker, but the outlook is dire.\n\nThe Jailer's forces have launched an all-out assault upon the ruins of our vault at the outer reaches of Korthia. Clearly the Banished One seeks something of value inside.\n\nThe vault's defenses activate when the structure is threatened, so getting inside won't be easy. But we must recover whatever the Jailer is seeking before his Mawsworn do.\n\nI've enlisted the aid of a necrolord who can help open the vault.", objectives = "" }
WordHunterWoW_QuestEN[63704] = { title = "Vengeance for Korthia", description = "While opening the vault is our priority, I  must ask a favor.\n\nWhen Korthia was pulled into the Maw, my people were terrified. We fled to the area you see before you, a place of peace called the Scholar's Den.\n\nThe Mawsworn soon descended upon us. Most of my kind were slaughtered. Others were taken captive.\n\nIf I could claim vengeance myself, I would. But I... I am ill-equipped for battle. Not like you.\n\nPlease. Show these monsters that their defilement of Korthia will not stand!", objectives = "" }
WordHunterWoW_QuestEN[63705] = { title = "The Knowledge Keepers", description = "Our vault was built to store countless secrets and artifacts. Even if we gain entrance, we can't be certain of what the Jailer is looking for.\n\nCertain attendants are given the title of record keeper. They track items stored in the vault, and are known for their utmost discretion.\n\nA number of keepers have been taken captive by the Mawsworn and are being tortured for information.\n\nSave the record keepers, {name}. They can help us determine what the Banished One seeks.", objectives = "" }
WordHunterWoW_QuestEN[63706] = { title = "Let the Anima Flow", description = "Tal-Galan briefed me on the situation and explained the vault's workings. As well as any scholarly type could, at least.\n\nFirst we need to ensure the vault is getting power. They use underground conduits to feed it anima.\n\nThe attendant says that one of these conduits is tucked away in a cave in Scholar's Den.\n\nYou get me there and I'll find a way to fix it. Just watch my back while I figure out how these Korthian devices work.", objectives = "" }
WordHunterWoW_QuestEN[63708] = { title = "Phantasmagoria", description = "<The strange mote of otherworldly energy glows with an erratic rhythm. \n\nVe'nari may find it of interest.>", objectives = "" }
WordHunterWoW_QuestEN[63709] = { title = "Secrets of the Vault", description = "What fortune! You rescued the record keepers before the Mawsworn could steal their knowledge of the vault's relics.\n\nBut their records are fragmented. Incomplete. I pray there's enough left to learn the truth.\n\nI will attempt to coalesce the knowledge that remains into a message. If the Purpose wills it, we will learn what the Jailer wants and to whom this item originally belonged.\n\nI must focus for a moment. Let me know when you are ready to begin.", objectives = "" }
WordHunterWoW_QuestEN[63710] = { title = "The Anima Trail", description = "So the Jailer seeks the Primus's sigil. We must beat the Mawsworn to it. To open the vault, we need to power it with anima.\n\nYou helped the Bonesmith repair the first conduit. The trail of anima in front of us leads to the next. \n\nIf we can activate it, then there should be enough anima flowing into Korthia to get us inside the vault.\n\nCome, we must make haste!", objectives = "" }
WordHunterWoW_QuestEN[63711] = { title = "Bone Tools", description = "So the device we need to open this vault is stuck on a floating island, eh?\n\nNot a problem.\n\nI see plenty of sturdy creatures around here. Like I always say, no bone goes to waste!\n\nBring me a pile of their bones. I'll use them to craft hookshot points for us to use to grapple over there.", objectives = "" }
WordHunterWoW_QuestEN[63712] = { title = "Lost Records", description = "Some of the record keepers fled to this mountain when Korthia was pulled into the Maw.\n\nI see no sign of them, but they may have left records behind. \n\nTake this beacon. I fashioned it using information from the previous record keepers you rescued.\n\nIt will lead you to any intact records that are on this mountain.", objectives = "" }
WordHunterWoW_QuestEN[63713] = { title = "Hooking Over", description = "I've made some solid hookshots and grapple points. Don't worry--if they hold my weight, they'll hold yours!\n\nThey can get us across the chasm to the next anima conduit.\n\nI'll go on ahead and wait for you. No telling what might be lurking over there.\n\nThe sooner we get the anima conduit working, the sooner we get into the vault and claim the Primus's sigil.", objectives = "" }
WordHunterWoW_QuestEN[63714] = { title = "To the Vault", description = "Thanks to the Bonesmith's repairs of both conduits, anima should now be flowing to the vault. That gives us a chance to get inside--assuming we can reach it.\n\nOur Maldraxxi allies have wrangled transportation to get us to and from the vault. I suggest we make haste.\n\nIf the Jailer's minions obtain the sigil of the Primus before we do, it won't just be Korthia that suffers. All the Shadowlands may be forfeit.\n\nLet's go, Maw Walker. Our forces will be awaiting us.", objectives = "" }
WordHunterWoW_QuestEN[63717] = { title = "Defending the Vault", description = "To reach the vault, we'll need to carve a path through the attacking Mawsworn.\n\nThe covenants are doing their best to drive off these monstrosities, but our allies can't hold out forever. The Mawsworn are intent on reaching the prize before you.\n\nWe could use your help fighting against the Jailer's forces, Maw Walker.\n\nPurpose guide us all.", objectives = "" }
WordHunterWoW_QuestEN[63722] = { title = "Keepers of Korthia", description = "We've barely held out against the Jailer's forces. Now that you're here, we can finally make some progress.\n\nI know your priority is to enter the vault, but our record keepers must also be recovered. \n\nThey are the authorities about everything kept in the vault. We can't let the Jailer learn what they know.", objectives = "" }
WordHunterWoW_QuestEN[63725] = { title = "Into the Vault", description = "The destruction here is... overwhelming.\n\n<Tal-Galan quietly utters a prayer.>\n\nAnima flows into what remains of the vault. We should now be able to enter.\n\nOnce inside, I will work on recovering the Primus's sigil. \n\nPlease show reverence within the vault. It is a sacred place that few are allowed to see.\n\nEven the prophecies did not foretell that a living mortal would gaze upon the secrets within.", objectives = "" }
WordHunterWoW_QuestEN[63726] = { title = "Untangling the Sigil", description = "The Primus's sigil is bound together with the magic of memory. It reminds me of something you have encountered before.\n\nYou made an ally of the Runecarver, that poor soul trapped in the bowels of Torghast. He took those memories you found and helped you forge them into weapons and armor.\n\nPerhaps he can separate the sigil from this tangle of memories.\n\nIt's our best chance to secure the sigil. But the way will be perilous.", objectives = "" }
WordHunterWoW_QuestEN[63727] = { title = "The Primus Returns", description = "The Jailer has four of the five sigils required for what he is planning.\n\nHe is a fool for allowing us to live. His desire to see us bend to his will shall be his undoing.\n\nAll is not lost, if you are willing to put in the work. There is still something that can be done.\n\nCome. I will meet with the rest of your forces and formulate our next attack.", objectives = "" }
WordHunterWoW_QuestEN[63728] = { title = "Hunting Amid Houses", description = "I have dreamed that Tyrande Whisperwind is crucial to the survival of Ardenweald.\n\nThe night fae have been searching for others like her who were once Night Warriors. We have recruited an ancient ally of Azeroth, Huln Highmountain, in order to look for them.\n\nElune's power is too much for any mortal to contain--even Tyrande. I do not know how much longer she can hold on.\n\nAllow me to explain further, then you must hurry to meet Huln in Maldraxxus.", objectives = "" }
WordHunterWoW_QuestEN[63731] = { title = "Researching Korthian Relics", description = "<You find a torn book regarding relics that were being kept within Korthia.\n\nA name written within its pages begins to glow: \"Roh-Suir.\"\n\nThe book spins in your hand and points in a direction while Roh-Suir's name pulses.\n\nPerhaps this Roh-Suir could help you discover more about the relics you've found.>", objectives = "" }
WordHunterWoW_QuestEN[63732] = { title = "Interrupt the Interrogations", description = "Shhh... quietly!\n\nThe invaders will kill me if they find me here, just as they have killed so many others!\n\n<Roh-Suir points frantically in the direction of the Mawsworn.>\n\nThey're torturing the Archivist!\n\nYou must find a way to rescue her. We cannot allow the Mawsworn to learn all that she knows!", objectives = "" }
WordHunterWoW_QuestEN[63733] = { title = "Carving Out a Path", description = "While I abhor violence and prefer a reasoned response to conflict, there is no alternative here.\n\nIn order for Roh-Suir and I to escape safely, you must deliver a decisive strike to the Mawsworn who have invaded Seeker's Quorum.\n\nCarve out a path so that we may escape.", objectives = "" }
WordHunterWoW_QuestEN[63734] = { title = "The Sundered Staff", description = "I have no choice but to trust you with the secrets of the Lodestaff.\n\nIn the right hands, such as those of a trained Archivist, the staff can locate influential relics from the afterlives of the Shadowlands.\n\nIt was split into three segments to ensure that it would not fall into the wrong hands. The invaders have found the pieces, but they are yet not aware of their significance.\n\nRecover the pieces of the staff. Each segment is held by a different member of the Mawsworn.", objectives = "" }
WordHunterWoW_QuestEN[63736] = { title = "An Infusion of Anima", description = "Normally we would infuse the Lodestaff with energy from the Netherstar, another relic of note.\n\nRegrettably, that is not an option. But, in a pinch, anima is an acceptable substitute.\n\nTake the Lodestaff. Brandish it near recently slain devourers in the estuary below us.\n\nThe staff should draw in and absorb their anima.", objectives = "" }
WordHunterWoW_QuestEN[63737] = { title = "Finding One's True Purpose", description = "All our efforts have led us here.\n\nWith the combined wisdom of the Archivists, and a little help from a {race} {class}, we will attune the Lodestaff to the relics that we seek.\n\nShould we succeed, we will have what we need to re-establish the Archive.\n\nOur sacred work can then continue.", objectives = "" }
WordHunterWoW_QuestEN[63738] = { title = "Establishing the Archive", description = "I will head to Keeper's Respite, where there is some small semblance of safety.\n\nThere, we will establish a new archive.\n\nMeet me there when you are able.\n\nI hope we can count on you again. We will have need of your assistance there in the future.", objectives = "" }
WordHunterWoW_QuestEN[63739] = { title = "Hope Ascending", description = "There is one final thing we must do.\n\nMeet us atop the peak of Hope's Ascent.", objectives = "" }
WordHunterWoW_QuestEN[63740] = { title = "Consulting the Experts", description = "We can restore the functions of the Lodestaff, but it will require the wisdom of the Archivists.\n\nNot just me, but the Archivists who have come before. They were laid to rest near here. Given the scale of the destruction of Korthia and the likely possibility that this destruction will continue, this may be our last chance to visit their memorials before they are irrevocably ruined.\n\nVisit the Archivists' memorials. Take Roh-Suir with you, so that he may take note of their messages before they are lost.", objectives = "" }
WordHunterWoW_QuestEN[63751] = { title = "A Terrible Power", description = "This strange shard pulses in your hand. An aura of dread radiates forth from it like a chill wind, sending a shiver down your spine. Perhaps the Primus could tell you more about this... if you could find him.", objectives = "" }
WordHunterWoW_QuestEN[63753] = { title = "Centurions March!", description = "Three of our Centurions have broken through the side gate. They need additional anima to continue their assault.\n\nSeveral of my assistants tried to deliver anima to them, but failed. Please get recover the anima and assist the Centurions in the attack.", objectives = "" }
WordHunterWoW_QuestEN[63754] = { title = "The Caged Bird", description = "Remain quiet. We must not attract attention.\n\nMany of my sisters have already been lost. It will soon be my turn to perish in that witch's vile ritual.\n\nRelease me from this cage and I can see us both to safety. Keeper Odyn must be warned of this foul betrayal!\n\nThe Mawsworn called Kjellrun holds the seal that can free me. You can find her gloating in the nearby hall.", objectives = "" }
WordHunterWoW_QuestEN[63755] = { title = "A Matter of Urgency", description = "Maw Walker, there is a matter of urgency that has not been addressed.\n\nOur Fatescribe is missing. They have not found their way here. They would have been in Seeker's Quorum before...\n\n<Pathscribe Roh-Vess pauses.>\n\nCan you look for the Fatescribe? Many attendants used the caves near the ruins to hide from the mawsworn.", objectives = "" }
WordHunterWoW_QuestEN[63756] = { title = "Rescued from Torment", description = "The Mawsworn are not only killing those they find in the Seeker's Quorum. They are interrogating the survivors.\n\nWe should help save those we can. It's possible one of them might have seen the Fatescribe.", objectives = "" }
WordHunterWoW_QuestEN[63757] = { title = "Looting the Looters", description = "<The Mawsworn was carrying a Korthian artifact.\n\nIt's unclear what the enemy wants with such relics, but you suspect the attendants in Keeper's Respite would want to see them returned.>", objectives = "" }
WordHunterWoW_QuestEN[63758] = { title = "The Last Place You Look", description = "I came here hoping to locate the Fatescribe or something to help me find him.\n\nEvidence shows he was here and survived a Mawsworn attack. The only other place I haven't looked is a meditation chamber on the opposite side of the ruins.\n\nIt's too dangerous for me to head back into the Seeker's Quorum alone. Could you help me?\n\nI must find the Fatescribe. It's a matter of great importance.", objectives = "" }
WordHunterWoW_QuestEN[63759] = { title = "Redirect the Search", description = "I believe the Fatescribe was headed to the Sanctuary of Guidance. A holy place for the attendants of Korthia.\n\nFortunately, because you seem to be in the habit of picking up every piece of trash you find, we have the Fatescribe's Implement!\n\nI'm sure that will prove useful in locating him. But first, on to the Sanctuary.", objectives = "" }
WordHunterWoW_QuestEN[63760] = { title = "Echoes of Fate", description = "The devourers have swarmed this place, but our focus must remain on finding the Fatescribe.\n\nAttendants who worshipped here would leave offerings of anima at the shrines.\n\nThe implement you found will resonate if the Fatescribe has been nearby. With any luck, it will give us insight into where he has gone.", objectives = "" }
WordHunterWoW_QuestEN[63761] = { title = "Revenge Delayed", description = "<The Korthian protector is gravely wounded and struggles to speak.>\n\nDevourers... swarmed the sanctuary. Too few of us...\n\nMy duty... incomplete.\n\nThe Purpose... I...\n\n<The protector's voice fades.>", objectives = "" }
WordHunterWoW_QuestEN[63762] = { title = "Under the Illusion", description = "The Fatescribe has collected the necessary items to create an illusion in this chamber. Fortunately, we can use his own implement to dispel it and reveal him.\n\nHe will be grateful to see a friendly face, I'm sure.\n\nI must say, you've proven to be incredibly helpful in this task. I truly couldn't have done it without you.", objectives = "" }
WordHunterWoW_QuestEN[63763] = { title = "They Could Be Anyone", description = "<The still-warm head of the dreadlord Azodius grimaces at you.\n\nThe attendants at Keeper's Respite should be told of the Fatescribe's abduction.\n\nNo doubt Highlord Fordragon will want to hear of this unexpected threat.>", objectives = "" }
WordHunterWoW_QuestEN[63764] = { title = "Claim the Sky", description = "I mourn the loss of my sisters and desire nothing more than to avenge them. Yet I know that I am no match for the witch's magics or her army of Mawsworn.\n\nWe must let wisdom guide us and fly from here. \n\nThough I am weak from my captivity, I have the strength to bear you from this place.\n\nLet us go, friend.", objectives = "" }
WordHunterWoW_QuestEN[63765] = { title = "Unseen Hero of the Party", description = "Oooh, this book looks long, I bet it is incredibly important.", objectives = "" }
WordHunterWoW_QuestEN[63771] = { title = "Fate's Reminder", description = "Fatescribe Roh-Tahl awaits you within Oribos, should you ever wish to change the course of fate.\n\nYou may speak with him at your leisure.", objectives = "" }
WordHunterWoW_QuestEN[63772] = { title = "Waiting in the Wings", description = "Kyrian forces have arrived to assist in the assault. They have secured our flank and will lay siege to the south gate of Perdition Hold. \n\nReport to Artemede and assist the Kyrians however you can!", objectives = "" }
WordHunterWoW_QuestEN[63773] = { title = "You and What Army", description = "The Jailer has dispatched a force of elite troops to strike our rear lines. Their attack threatens our whole assault!  \n\nI need you and one other soldier to eliminate these enemies. A volunteer from each of the five houses of Maldraxxus has requested to assist you, {name}.\n\nPick one and give them the honor of serving alongside you.", objectives = "" }
WordHunterWoW_QuestEN[63774] = { title = "An Embarrassment of Corpses", description = "Look around us, {name}. Everywhere you turn there are corpses piling up like mountains. These disembodied souls are desperate to return to battle.\n\nWe will use their fervor to turn the tide.\n\nRally the disembodied souls around the battlefield and bring them to my stitchers at the corpse piles to build them new bodies!", objectives = "" }
WordHunterWoW_QuestEN[63775] = { title = "Cryptograms and Keys", description = "The repositories of knowledge within Korthia have layers of security--for very good reasons.\n\nEach vault requires cryptographs in order to decode and disable the barriers. They are, for lack of a better term, the keys to every secret.\n\nSearch outside the Vault for cryptographs stolen by the Mawsworn and return them to me. I will keep them, and the secrets they protect, safe.", objectives = "" }
WordHunterWoW_QuestEN[63776] = { title = "Observational Records", description = "Greetings, Maw Walker, a moment of your time?\n\nAs you no doubt know, my cartel has quietly spread observational devices all across Korthia. But that data is no good to us if it is not retrieved. Which is where you come in.\n\nThe Scholar's Den records should be ready to collect. You won't see the devices themselves, but the data will appear to you as a bright orb.\n\nBe sure to check in the caverns below ground, as well!\n\nBring those data to me, and I will reward you handsomely.", objectives = "" }
WordHunterWoW_QuestEN[63777] = { title = "Sealed Secrets", description = "Ah, Korthia. What secrets will be revealed?\n\nMy associates have been hard at work, seeking to discover and procure various small items of interest throughout this broken land. Nothing of great importance, I assure you.\n\nThey have secured those items in designated drop boxes, and those now await pickup in the Scholar's Den. Don't worry: they are locked with an impenetrable seal to protect both the contents and the deliverer.\n\nBring those sealed containers to me, and I will reward you handsomely.", objectives = "" }
WordHunterWoW_QuestEN[63778] = { title = "We Move Forward", description = "It breaks my heart to see another land so utterly obliterated. I can imagine how beautiful Korthia must have been, once.\n\nBut we must not wallow in what we've lost. Like Ara'lon taught me: we don't have to stand still.\n\nWe can choose to fight.\n\nYou can help by taking anima back from those Mawsworn. We can put it to use, building up our own forces and defenses.", objectives = "" }
WordHunterWoW_QuestEN[63779] = { title = "A Semblance of Normalcy", description = "{name}, we have to help the attendants of Korthia. They have lost so much, so suddenly.\n\nNearby, in the Sanctuary of Guidance, they would take offerings and leave them at shrines. Since the mawsworn invaded, they haven't been able to enter the Sanctuary or retrieve their precious offerings.\n\nIf you could collect the offerings and retrieve them. It might allow the attendants some semblance of their normal lives.", objectives = "" }
WordHunterWoW_QuestEN[63780] = { title = "See How THEY Like It!", description = "Just thinking about how the Jailer's forces breached Ardenweald makes me so mad! \n\nAnd when I get mad, I get even.\n\nOr rather, I get your help with getting even! Slay those Mawsworn and bring back their emblems to show me how many you killed. \n\nI don't really care where you get them, as long as they come from those Maw jerks!", objectives = "" }
WordHunterWoW_QuestEN[63781] = { title = "Mawsworn Battle Plans", description = "Which is more damaging to the enemy, destroying a contingent of their forces or interrupting their communications?\n\nBetter yet, what if that communication allows you to best place your forces to ambush their reinforcements?\n\nI see you understand. There will be a Mawsworn lieutenant, Voxiferus, traveling from the Maw into Korthia, by way of the northern road. Find them, kill them, and bring me the battle plans.", objectives = "" }
WordHunterWoW_QuestEN[63782] = { title = "Mawsworn Rituals", description = "The Mawsworn have a myriad of magic users among their forces. Their magic is unknown to us and that makes it deadly.\n\nWe need to learn what they are capable of to properly prepare a defense. My own curiosity about their methods and rituals is secondary.\n\nHunt down these vile casters and bring me their grimoires.", objectives = "" }
WordHunterWoW_QuestEN[63783] = { title = "Anima Reclamation", description = "Our efforts here need a constant supply of troops, supplies, and anima. The last one is the hardest, for obvious reasons. But I've learned to be resourceful. \n\nNearby there is a plentiful source of anima: the devourers that currently swarm the Sanctuary of Guidance. It's not as easy as beating it out of a soul, but it's just as effective, if you're strong enough. Are you?", objectives = "" }
WordHunterWoW_QuestEN[63784] = { title = "Gold's No Object", description = "{name}! How's things?\n\nWe 'eard there was all kinds of interestin' stuff out 'ere.\n\nSo, 'em sneakin' hoppers? Hard to see, innit? They've got 'emselves a shiny pelt as me 'n' the lads could use to stay out of sight, as it were. You know, avoid the bosses n' such.\n\nI need ya to capture a bundle of 'em. Gold's no object, just bring me the little pests alive.", objectives = "" }
WordHunterWoW_QuestEN[63785] = { title = "Continued Efforts: Seeker's Quorum", description = "The onslaught from Zovaal's forces continues to devastate these lands.\n\nWe must send them a message. Show them we will not back down, {name}.\n\nThe might of Ardenweald stands with you.", objectives = "" }
WordHunterWoW_QuestEN[63786] = { title = "Sweep the Windswept Aerie", description = "The skies over Korthia are a dangerous place.\n\nNot only do the Mawsworn threaten our forces; the native creatures are also openly hostile. We must keep the skies safe for our own winged allies and beasts.\n\nThe source of the native flyers is the Windswept Aerie. Go there and clear the aerie of aggressive creatures.\n\nThen, we shall have aerial supremacy.", objectives = "" }
WordHunterWoW_QuestEN[63787] = { title = "Continued Efforts: Mauler's Outlook", description = "My Eyes tell me that the Mauler's Outlook is near the newly formed road from the Maw into Korthia. It would provide a strategic and tactical advantage.\n\nUnfortunately, the area is overrun with shardhides.\n\nIf we can secure the area, it will provide us with a clear path to the west, as well as a point of observation to monitor the Jailer's forces.", objectives = "" }
WordHunterWoW_QuestEN[63788] = { title = "Continued Efforts: Sanctuary of Guidance", description = "The attendant's home has been destroyed by the Jailer, but we can help them in this trying time.\n\nNearby is the Sanctuary of Guidance. They speak of it with reverence and great sadness. It is a place they go to pray and seek truth. It's currently infested with devourers.\n\nClear out the devourers, so they may once more seek solace in their rituals and prayers.", objectives = "" }
WordHunterWoW_QuestEN[63789] = { title = "Continued Efforts: Scholar's Den", description = "We cannot allow the mawsworn a foothold so close to our own encampment. The attendants say they keep this place hidden from eyes, but I will not rest easy while I can see them.\n\nEnter the Scholar's Den and cleanse the Jailer's forces from it.", objectives = "" }
WordHunterWoW_QuestEN[63790] = { title = "Broker's Bounty: Lord Azzorak", description = "A powerful dreadlord named Lord Azzorak is hampering the efforts of the Cartel in Korthia.\n\nAnyone who exterminates this evil will be rewarded. \n\nUse caution. Azzorak is a powerful foe. You may require several allies to slay him.", objectives = "" }
WordHunterWoW_QuestEN[63791] = { title = "Broker's Bounty: Valdinar the Curseborn", description = "A spike-armored Mawsworn named Valdinar the Curseborn is hampering the efforts of the Cartel in Korthia.\n\nAnyone who exterminates this evil will be rewarded. \n\nUse caution. Valdinar is a powerful foe. You may require several allies to defeat him.", objectives = "" }
WordHunterWoW_QuestEN[63792] = { title = "Broker's Bounty: Nocturnus the Unraveler", description = "A nefarious Maw magus named Nocturnus the Unraveler is hampering the efforts of the Cartel in Korthia.\n\nAnyone who exterminates this evil will be rewarded. \n\nUse caution. Nocturnus is a powerful foe. You may require several allies to defeat him.", objectives = "" }
WordHunterWoW_QuestEN[63793] = { title = "Broker's Bounty: Ensydius the Defiler", description = "A winged Mawsworn named Ensydius the Defiler is hampering the efforts of the Cartel in Korthia.\n\nAnyone who exterminates this evil will be rewarded. \n\nUse caution. Ensydius is a powerful foe. You may require several allies to defeat him.", objectives = "" }
WordHunterWoW_QuestEN[63794] = { title = "Broker's Bounty: Hungering Behemoth", description = "New lands bring new opportunity. We will provide a quantity of valuables to any interested party in return for a substantial amount of devourer blood, preferably the goliath kind.\n\nFaint-hearted collectors need not bother.\n\nPlease bring this sample to Ta'nasi in Keeper's Respite.", objectives = "" }
WordHunterWoW_QuestEN[63810] = { title = "Birds of a Feather", description = "I have seen many ebon wings in the Maw, but never brilliant golden ones.\n\nNow that the aural sequencers are relaying information reliably, we should discover the source of these feathers.\n\nFollow the trail, Maw Walker. There is a mystery here... and very likely profit.\n\nGold has value where you come from, does it not?", objectives = "" }
WordHunterWoW_QuestEN[63811] = { title = "A Hate-Hate Relationship", description = "When the first of my sisters went missing, we were concerned. Those sent to find her did not return. Nor did the next.\n\nWhat we have discovered is a dreadful betrayal by someone we once trusted.\n\nCome, we must tell Odyn what we have witnessed in the Maw.\n\nHis wrath will be great.", objectives = "" }
WordHunterWoW_QuestEN[63827] = { title = "Encouraging Words", description = "Our forces have been battling relentlessly for hours. No doubt they grow tired and disheartened.\n\nTake this codex and recite the words within to our troops. Do not be fooled. Though the prose may seem meaningless, it holds immense power.\n\nHearing these words will reinvigorate our exhausted Protectors with hope.", objectives = "" }
WordHunterWoW_QuestEN[63828] = { title = "Mine's Bigger", description = "The Jailer has deployed a large number of newly forged constructs to oppose our forces. Fortunately, I was completely prepared for this possibility. \n\nI have readied our largest Centurion to repel this threat.\n\nPlease Maw Walker, ride with our Centurion and direct it in combat.", objectives = "" }
WordHunterWoW_QuestEN[63829] = { title = "No One Floats Down Here", description = "Now is our chance to free those we had assumed were lost!\n\nMany of our aspirants were seized by the Jailer to make troops for his army. Those that resisted him are locked in the cages that float above us, left there till their souls are broken. \n\nShatter the Chains of Domination and free the Trapped Aspirants from the cages.", objectives = "" }
WordHunterWoW_QuestEN[63831] = { title = "Fury Given Voice", description = "I will answer this attack upon my val'kyr with relentless fury!\n\nYou have a vital role to play in this, {class}. You will muster the courage that you have demonstrated this day to lure my Eye to battle.\n\nBut first, a simpler task ... the creation of the horn that will summon my wrath. Master Smith Helgar will guide you.", objectives = "" }
WordHunterWoW_QuestEN[63833] = { title = "Terrorizing the Tremaculum", description = "I am certain that my compatriots and generals have more specific tasks they require of you.\n\nBut my request is simple. Our enemies currently surround us on all sides.\n\nPush them back and give us more room to operate.", objectives = "" }
WordHunterWoW_QuestEN[63834] = { title = "Weapons of the Tremaculum", description = "The venthyr of Sinfall do not waste souls, and her stoneborn do not waste armaments.\n\nRetrieve the tools of our enemies so that we may repurpose them for our army.", objectives = "" }
WordHunterWoW_QuestEN[63835] = { title = "Wrath of the Party Herald", description = "Oh, you're back so soon, {name}!\n\n...Or have we not already met? It is difficult to remember at times...\n\nRegardless, I trust you are making progress with Cryptkeeper Kassir's plan to weaken our adversaries.\n\nDetails of the plan escape me, but I am certain Temel was involved. I hear he fancies himself a \"party herald\" nowadays...\n\n<The Curator looks beyond you for a moment.>\n\n\"Party herald\"... I must have been gone from Revendreth for longer than I thought.", objectives = "" }
WordHunterWoW_QuestEN[63836] = { title = "Fangcrack's Fan Club", description = "Fangcrack is the strongest dredger I e'er seen! He's incredible!\n\nHe's down there, reaching into dat big Torghast portal, pulling the baddies right out o' their home!\n\nThey don't even know what's happenin' half the time, ha ha!\n\nMe and Cudgelface joined his fan club soon as we got here.\n\nYou want in? You gotta earn your membership same as everyone else: go down there and fight whatever he pulls out of the portal!", objectives = "" }
WordHunterWoW_QuestEN[63837] = { title = "A Tea for Every Occasion", description = "My dear {name}! I knew you would arrive in the nick of time to save us all from the brink of boredom!\n\nI was just telling Niya here about the time you saved me from the Ember Ward through the healing power of tea!\n\nShe is a bit skeptical. Perhaps you can help Tubbins and Gubbins show her that, through tea, all things are possible!", objectives = "" }
WordHunterWoW_QuestEN[63838] = { title = "Duelist's Challenge", description = "<Nadjia continues to parry attacks from enemy Mawsworn while she turns to face you.>\n\nAs you can see, we have our hands full here on the barricade.\n\nI will hold the line while you challenge the champions of the Mawsworn army.\n\nDefeat them in full view of their underlings.\n\nNo mercy, {name}. Demoralize them.", objectives = "" }
WordHunterWoW_QuestEN[63839] = { title = "If Even One is Worthy", description = "I have seen firsthand that worthy souls have been unjustly cast into the Maw.\n\nGresit here was almost cast in himself by the Lord Chamberlain's minion. He has more than proven himself under my care.\n\nLook among the souls that the Jailer's filth have deemed \"unworthy\". Inspect each to confirm that they deserve their fate.\n\nEven if we examine every soul in the Tremaculum and find only a single worthy one to bring back to Revendreth, it will still be valuable.", objectives = "" }
WordHunterWoW_QuestEN[63840] = { title = "They Grow Up So Quickly", description = "I know what you're thinking, but I have these gormlings completely under control!\n\nI picked up a trick or two at the venthyr's Ember Court for suppressing and controlling these troublemakers.\n\nIf you wish to use their power to aid our battle, I will loan you my staff. With it you can choose a gormling that can be ordered to feed on the corpses of our enemies and grow in strength and size.\n\nYou won't need many. Gormling grow quickly.", objectives = "" }
WordHunterWoW_QuestEN[63841] = { title = "The Skyhunt", description = "Boot the Beaut and the other large dredgers are being hit hard from air assaults.\n\nThe dredgers may not be able to reach them, but the Wild Hunt can reach any prey.\n\nTake my spear and use it to ground the Mawsworn in the sky above the western bridge.\n\nOnce they are grounded, they will be easy to dispatch.\n\nMy trappers will help slow them down for you.", objectives = "" }
WordHunterWoW_QuestEN[63842] = { title = "That's a Good Trick", description = "These cruel tormentors make me so mad...\n\nThe Jailer's bullies torture good souls sent here unjustly because no one will stand up to them!\n\nWell, I am here now, and I have the perfect plan to make them pay.\n\nWhat do you say? Want to help me turn the tables on these bullies?", objectives = "" }
WordHunterWoW_QuestEN[63843] = { title = "Heart and Soul", description = "The Forsworn that serve the Jailer dominate the skies above, but we know their weakness and shall use it against them.\n\nUnder my direction Mikanikos has created a supply of Trueheart Spears for our Protectors. When hit by these spears the Mawsworn will be weakened with their soul laid bare as they face their true self.\n\nCollect the Trueheart Spears and use them to defeat the Mawsworn Myrmidons that fly above us.", objectives = "" }
WordHunterWoW_QuestEN[63844] = { title = "The Chosen Few", description = "I have need of more val'kyr to join Danica in the battle to come. {name}, you are granted the honor of choosing the most worthy.\n\nThe strongest will present themselves in challenge at the Circle of Glory. Fight hard, {class}, and do honor to your weapons.", objectives = "" }
WordHunterWoW_QuestEN[63845] = { title = "Wrath of Odyn", description = "The horn has been forged and the worthy have been selected.\n\nNow, {name}, we have only to bind my chosen val'kyr to the horn and infuse them with my power that they may strike with my fury.\n\nCome, bear witness.", objectives = "" }
WordHunterWoW_QuestEN[63846] = { title = "The Ember Count", description = "Theotar's brilliance is undeniable, but far too many overlook the ingenuity of his dredger helpers, Gubbins and Tubbins.\n\nLook to that ridge beyond us. The Jailer's forges over there are spewing out Soulsteel Embers.\n\nWe could accomplish many things with a mirror made from them...\n\nGubbins has already crafted a special parasol, capable of shielding its wielder from any falling embers.\n\nMeet him by the forges and obtain some of those Soulsteel Embers!", objectives = "" }
WordHunterWoW_QuestEN[63848] = { title = "A Show of Gratitude", description = "Your presence here fulfils an ancient prophecy, Maw Walker. I am certain you and your allies will save us.\n\nPerhaps I judged your broker friend too harshly. She did escort you to Korthia, after all. \n\nPlease extend our thanks to Ve'nari, and let her know we are happy to answer her questions.\n\nShe... does seem to have quite a number of them.", objectives = "" }
WordHunterWoW_QuestEN[63849] = { title = "Hearing Aid", description = "How fortuitous! You just happened to be transferred to a location in which I have a certain... interest. Place the aural sequencers I gave you and I will attempt to establish a functional signal.\n\nSuch a perilous location will require the utmost discretion. You will want to use your ethereal cloak to avoid being seen.", objectives = "" }
WordHunterWoW_QuestEN[63853] = { title = "Kill the Flame", description = "Can you see it?  \n\nJust out of the corner of my eye, it's always there... glowing so brightly!\n\nHow is one supposed to relax and enjoy a cup of tea while that reminder of fire and ash is around.\n\nPlease Maw Walker do me a favor... remove it so that we may all enjoy a cup of my favorite blend!", objectives = "" }
WordHunterWoW_QuestEN[63855] = { title = "Ease of Passage", description = "Korthia is ripe with opportunity. Look at all of these intriguing objects.\n\nIn anticipation of such wonders, I have come prepared. Let us find a suitable location and establish a more permanent connection between this place and my refuge.\n\nOur work together is not yet finished.", objectives = "" }
WordHunterWoW_QuestEN[63856] = { title = "A Gathering of Covenants", description = "Though the Jailer remains confined to the Maw, his cruelty extends beyond the bounds of his prison.\n\nThankfully, the Archon is recovering from the attack. Though I am told her wound has an... unsettling quality.\n\nThe Eternal Ones and their allies await you and Highlord Fordragon in the Arbiter's chamber. I shall open the way.\n\nWith her voice have I spoken.", objectives = "" }
WordHunterWoW_QuestEN[63857] = { title = "Voices of the Eternal", description = "<Bolvar peers at the grand figures before him, at the numberless gateways stretching out into the ether.>\n\nThis chamber is... truly wondrous.\n\nYet there is no time to be awestruck. The Honored Voice must begin this meeting at once.", objectives = "" }
WordHunterWoW_QuestEN[63858] = { title = "Courage of the Soul", description = "In this time of conflict, we are all tested, Maw Walker. It takes great bravery and strength of soul to confront our enemies without fear.\n\nWade into their lines and show them the power of your courage.", objectives = "" }
WordHunterWoW_QuestEN[63859] = { title = "Saved By The Bells", description = "Our stewards are preparing Reinforcement Bells to summon additional Kyrian to aid in our assault. However, the Mawsworn have been attacking the stewards in order to disrupt their efforts. \n\nWe need you to defend our stewards while they complete their work, then ring each bell to call in reinforcements.", objectives = "" }
WordHunterWoW_QuestEN[63860] = { title = "Talisman of the Eternal Scholar", description = "<The talisman is dented and spattered with muck. Whoever stashed this here handled it roughly.\n\nArchivist Roh-Suir has a spot for this talisman in the Reliquary of Remembrance.>", objectives = "" }
WordHunterWoW_QuestEN[63861] = { title = "Beginning the Collection", description = "Let us continue our work by retrieving the most important item of any scholarly study--the lost codex.\n\nIt will take some time, but as we continue our work the pages of this work will continue to grow and flourish, just as Korthia has itself for eons.\n\nAs for its location, it previously resided deep within the underbelly of Korthia itself inside the Cavern of Contemplation to the south.\n\nWe can only hope the Jailer's forces have yet to locate it.", objectives = "" }
WordHunterWoW_QuestEN[63862] = { title = "NavTest", description = "Follow the path before you.", objectives = "" }
WordHunterWoW_QuestEN[63863] = { title = "United In Pride", description = "Despite our competitive differences, Nemea and I work as a team when faced with greater threats. The pride and the phalynx are both fierce fighters upon the battlefield.\n\nWe would both be honored to assist you in the battle that lies ahead.\n\nPlease allow either Andira or Gatamatos to assist you in defeating the Jailer's champions that threaten our forces.", objectives = "" }
WordHunterWoW_QuestEN[63864] = { title = "The Dreadful Blend", description = "Gravedust and Stipple Weed is a dreadful flavor combination, and Tubbins made a very large batch of tea with those ingredients.\n\nIt was so horrid that I tossed the entire pot of tea on the fire. It turns out to be very wet, and an excellent extinguisher of flames! \n\nTubbins will haul the entire batch with you. Put it to good use, by tossing it on the Volatile Embersparks around Zovaal's Cauldron.", objectives = "" }
WordHunterWoW_QuestEN[63867] = { title = "Anger Management", description = "I am no musician, though I've spent many an hour enjoying the entertainment in Tazavesh.\n\nGiving this horn a voice will require the harvest of strong emotions.\n\nAnger seethes unrestrained within the damned unfortunates consigned to the River of Souls. Use this siphoning device to drain the rage of these furious shades into your instrument.\n\nThe shrieks of fury that you acquire should allow you to pierce the Maw and reach your allies.\n\nThe tune, I suspect, will not be a popular one.", objectives = "" }
WordHunterWoW_QuestEN[63892] = { title = "Diviner's Rune Chits", description = "<Inside the pouch is a single rune chit. It rotates and flips as if moved by an unseen hand.\n\nRunes vaguely reminiscent of the Vrykul language are delicately carved into the stone. On the back of the chit is an indication that it is part of a set.>", objectives = "" }
